            <div className="space-y-4">

              {/* Playbook Item 1 */}
              <div className="border border-border bg-[#0e1117] p-5 space-y-3">
                <div className="flex items-center gap-2 text-xs font-bold text-foreground border-b border-border/40 pb-2">
