      <p className={cn("shrink-0 text-right text-xs", strong && "font-semibold text-zinc-100", large && "text-base font-bold text-white", tone === "warning" && "text-amber-500", tone === "danger" && "text-red-500", tone === "success" && "text-emerald-500")}>
