/**
 * app/api/v1/agent/status/route.ts
 *
 * Returns complete agent status: active goal, roadmap summary, progress,
 * and latest analysis snapshot — all in one call for the dashboard.
 */

import { NextRequest, NextResponse } from "next/server";
import { auth } from "@/auth";
import { prisma } from "@/lib/db/prisma";
import { AgentMemory, ProgressTrackingEngine } from "@/lib/agent";
import { logger } from "@/lib/logger";
import type { CareerRoadmap } from "@/lib/agent/types";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function GET(_req: NextRequest) {
  try {
    const session = await auth();
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }
    const userId = session.user.id;

    const [twin, profile, progress, recentMemories, skillGap, readiness] = await Promise.all([
      AgentMemory.getOrCreateTwin(userId),
      prisma.careerProfile.findUnique({ where: { userId } }),
      ProgressTrackingEngine.getUserProgressSummary(userId),
      prisma.twinMemory.findMany({
        where: { userId },
        orderBy: { createdAt: "desc" },
        take: 10,
      }),
      prisma.skillGapAnalysis.findFirst({
        where: { userId },
        orderBy: { updatedAt: "desc" },
      }),
      prisma.readinessScore.findFirst({
        where: { userId },
        orderBy: { createdAt: "desc" },
      }),
    ]);

    const roadmap = twin.activePlan && typeof twin.activePlan === "object" && Object.keys(twin.activePlan).length > 0
      ? (twin.activePlan as unknown as CareerRoadmap)
      : null;

    const goals = (profile?.goals as Record<string, any>) ?? {};
    const primaryGoal = goals.primary ?? null;

    // Calculate current active week
    let currentWeek = 1;
    if (roadmap) {
      for (const phase of roadmap.phases) {
        for (const week of phase.weeklyPlans) {
          if (week.actionItems.some((t) => !t.completed)) {
            currentWeek = week.weekNumber;
            break;
          }
        }
      }
    }

    return NextResponse.json({
      success: true,
      status: {
        hasActiveGoal: !!roadmap,
        primaryGoal,
        roadmap,
        currentWeek,
        progress,
        twinStatus: twin.status,
        twinScores: twin.scores,
        recentMemories: recentMemories.map((m) => ({
          id: m.id,
          type: m.type,
          title: m.title,
          content: m.content,
          createdAt: m.createdAt.toISOString(),
        })),
        skillGapSummary: skillGap
          ? {
              targetRole: skillGap.targetRole,
              gapCount: (skillGap.gapSkills as any[]).length,
              estimatedWeeks: skillGap.estimatedWeeks,
              topGaps: (skillGap.gapSkills as any[]).slice(0, 5).map((g: any) => g.name ?? g),
            }
          : null,
        readinessScore: readiness?.overallScore ?? 0,
      },
    });
  } catch (err) {
    logger.error({ err }, "[API /agent/status] Failure");
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

import { NextRequest } from "next/server";
import { requireUser } from "@/lib/auth/session";
import { apiOk, errorToResponse } from "@/lib/api/response";
import { prisma } from "@/lib/db/prisma";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function GET() {
  try {
    const user = await requireUser();

    // 1. Fetch pending email drafts that are waiting for approval
    const pendingDrafts = await prisma.emailDraft.findMany({
      where: {
        status: "pending_approval",
        campaign: {
          userId: user.id,
        },
      },
      include: {
        campaign: true,
      },
      orderBy: {
        scheduledAt: "asc",
      },
    });

    const emailApprovals = pendingDrafts.map((draft) => ({
      id: draft.id,
      type: "email_follow_up",
      title: `Approve follow-up email to ${draft.campaign.recruiterName || "recruiter"} at ${draft.campaign.companyName}`,
      summary: `AI generated sequence ${draft.sequence} follow-up for your application to ${draft.campaign.jobTitle}.`,
      payload: {
        subject: draft.subject,
        body: draft.body,
        campaignId: draft.campaignId,
        sequence: draft.sequence,
        formFields: [
          { field: "Subject", value: draft.subject },
          { field: "Recipient", value: draft.campaign.recruiterEmail || "Unknown Recruiter" },
          { field: "Sequence", value: `Email #${draft.sequence}` },
        ],
      },
      riskFlags: null,
      expiresAt: new Date(draft.scheduledAt.getTime() + 24 * 60 * 60 * 1000).toISOString(), // 24 hours expiry
      createdAt: draft.campaign.createdAt.toISOString(),
      workflowId: draft.campaignId,
      workflowRun: {
        id: draft.campaignId,
        type: "email_campaign",
        goal: `Follow up on ${draft.campaign.jobTitle} application at ${draft.campaign.companyName}`,
        status: draft.campaign.status,
      },
    }));

    // 2. Fetch any BrowserExecution status that is waiting_for_approval
    const pendingExecutions = await prisma.browserExecution.findMany({
      where: {
        status: "waiting_for_approval",
        userId: user.id,
      },
      orderBy: {
        createdAt: "desc",
      },
    });

    const executionApprovals = pendingExecutions.map((exec) => {
      const metadata = exec.metadata && typeof exec.metadata === "object" ? (exec.metadata as Record<string, unknown>) : {};
      return {
        id: exec.id,
        type: "browser_action",
        title: `Approve browser automation action: ${exec.currentTitle || "Form Submission"}`,
        summary: `The AI Agent is ready to perform an action on ${exec.currentUrl || "external site"}. Please review.`,
        payload: {
          currentUrl: exec.currentUrl,
          screenshotData: typeof metadata.screenshotUrl === "string" ? metadata.screenshotUrl : null,
          formFields: Array.isArray(metadata.fieldsToFill) ? metadata.fieldsToFill : [],
        },
        riskFlags: metadata.riskFlags && typeof metadata.riskFlags === "object" ? metadata.riskFlags : null,
        expiresAt: new Date(exec.updatedAt.getTime() + 15 * 60 * 1000).toISOString(), // 15 mins expiry
        createdAt: exec.createdAt.toISOString(),
        workflowId: exec.workflowId,
        workflowRun: {
          id: exec.workflowId,
          type: "browser_automation",
          goal: exec.currentTitle || "Automated Application",
          status: "running",
        },
      };
    });

    return apiOk({
      approvals: [...emailApprovals, ...executionApprovals],
    });
  } catch (error) {
    return errorToResponse(error);
  }
}

import { NextRequest, NextResponse } from "next/server";
