import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { auth } from "@/auth";
import { prisma } from "@/lib/db/prisma";
import { callClaudeJson } from "@/app/api/interview/_lib/claude";
import { memoryService } from "@/lib/services/memory.service";

export const runtime = "nodejs";

const schema = z.object({
  targetRole: z.string().min(1),
  targetCompany: z.string().min(1),
  jobOpportunityId: z.string().uuid().optional(),
});

const CACHE_DAYS = 7;

function buildResumeSummary(resumeData: any): string {
  const parts: string[] = [];
  const personal = resumeData?.personal ?? resumeData?.personalInfo ?? {};
  if (personal.summary) parts.push(`Summary: ${personal.summary}`);
  const exp = resumeData?.experience ?? [];
  if (exp.length > 0) {
    parts.push(`Experience: ${exp.slice(0, 3).map((e: any) => `${e.role} at ${e.company}`).join(", ")}`);
  }
  const skills = resumeData?.skills ?? [];
  if (skills.length > 0) parts.push(`Skills: ${skills.slice(0, 10).join(", ")}`);
  return parts.join(". ") || "No resume summary available.";
}

function padPaths(paths: any[]): any[] {
  const normalized = paths.slice(0, 3);
  while (normalized.length < 3) {
    normalized.push({
      path: "unknown",
      probability: 0,
      avgTimeYears: 0,
      nextRoles: [],
      salaryGrowthPct: 0,
      likelihood: "low",
    });
  }
  return normalized;
}

export async function POST(req: NextRequest) {
  try {
    const session = await auth();
    const userId = session?.user?.id;
    if (!userId) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    const body = await req.json().catch(() => null);
    const parsed = schema.safeParse(body);
    if (!parsed.success) return NextResponse.json({ error: "Invalid request payload." }, { status: 400 });

    const { targetRole, targetCompany, jobOpportunityId } = parsed.data;

    // Load resume + career profile in parallel
    const [profile, latestResume] = await Promise.all([
      prisma.careerProfile.findUnique({
        where: { userId },
        select: { goals: true, headline: true },
      }),
      prisma.resume.findFirst({
        where: { userId },
        orderBy: { updatedAt: "desc" },
        select: { data: true },
      }),
    ]);

    const resumeData = latestResume?.data as any;
    const goals = profile?.goals as any;
    const currentRole =
      (resumeData?.experience?.[0]?.role ?? resumeData?.experience?.[0]?.title) ||
      profile?.headline ||
      "Not specified";
    const goalIn5Years = goals?.targetIn5Years || "Not specified";
    const resumeSummary = buildResumeSummary(resumeData);

    // Check Prisma cache — skip re-running within 7 days
    const sevenDaysAgo = new Date(Date.now() - CACHE_DAYS * 24 * 60 * 60 * 1000);
    const cached = await prisma.careerPathSimulation.findFirst({
      where: {
        userId,
        targetCompany: { equals: targetCompany, mode: "insensitive" },
        targetRole: { equals: targetRole, mode: "insensitive" },
        createdAt: { gte: sevenDaysAgo },
      },
      orderBy: { createdAt: "desc" },
    });
    if (cached) return NextResponse.json({ data: cached, error: null, cached: true });

    // Load relevant career memories
    let memorySummary = "";
    try {
      const memories = await memoryService.searchMemories(
        userId,
        `career goals ${targetRole}`,
        5
      );
      memorySummary = memories.map((m) => m.content).join(". ");
    } catch {
      // gracefully degrade if pgvector/OpenAI unavailable
    }

    const systemPrompt =
      "You are a career intelligence analyst. Simulate realistic career trajectories. Return ONLY valid JSON.";

    const userPrompt = `Current: ${currentRole}. Evaluating: ${targetRole} at ${targetCompany}. 5-year goal: ${goalIn5Years}. Background: ${resumeSummary}. Memories: ${memorySummary || "None available."}. 

Simulate 3 career paths — optimistic, realistic, conservative — and return:
{
  "trajectoryPaths": [
    {
      "path": "optimistic|realistic|conservative",
      "probability": 0.0-1.0,
      "avgTimeYears": number,
      "nextRoles": ["string"],
      "salaryGrowthPct": number,
      "likelihood": "high|medium|low"
    }
  ],
  "careerAlignScore": 0-100,
  "alignRationale": "string",
  "riskFactors": ["string"],
  "opportunities": ["string"],
  "skillsGained": ["string"],
  "skillsMissing": ["string"],
  "verdict": "strong_yes|yes|sideways|risky|step_back"
}`;

    const { data: aiResult } = await callClaudeJson<any>({
      system: systemPrompt,
      user: userPrompt,
      maxTokens: 2500,
    });

    const simulation = await prisma.careerPathSimulation.create({
      data: {
        userId,
        jobOpportunityId: jobOpportunityId ?? null,
        targetCompany,
        targetRole,
        currentRole,
        goalIn5Years,
        trajectoryPaths: padPaths(aiResult?.trajectoryPaths ?? []),
        careerAlignScore: Number(aiResult?.careerAlignScore ?? 50),
        alignRationale: aiResult?.alignRationale ?? "Analysis complete.",
        riskFactors: Array.isArray(aiResult?.riskFactors) ? aiResult.riskFactors : [],
        opportunities: Array.isArray(aiResult?.opportunities) ? aiResult.opportunities : [],
        skillsGained: Array.isArray(aiResult?.skillsGained) ? aiResult.skillsGained : [],
        skillsMissing: Array.isArray(aiResult?.skillsMissing) ? aiResult.skillsMissing : [],
        verdict: aiResult?.verdict ?? "sideways",
      },
    });

    return NextResponse.json({ data: simulation, error: null, cached: false });
  } catch (error: any) {
    console.error("[CareerPathSimulate] Error:", error);
    return NextResponse.json({ error: "Failed to simulate career path." }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { auth } from "@/auth";
import { checkDailyRateLimit } from "@/lib/security/ratelimit";
import { CompanyDashboardService } from "@/lib/services/company-dashboard.service";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function GET(req: NextRequest, context: { params: Promise<{ name: string }> }) {
  const session = await auth();
  const userId = session?.user?.id;
  if (!userId) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const limited = await checkDailyRateLimit(userId, 50, "company_dashboard");
  if (!limited.allowed) {
    return NextResponse.json({ error: "Daily dashboard lookup limit reached." }, { status: 429 });
  }

  const { name: slug } = await context.params;
  if (!slug) {
    return NextResponse.json({ error: "Slug is required." }, { status: 400 });
  }

  const forceRefresh = req.nextUrl.searchParams.get("refresh") === "true";

  try {
    const data = await CompanyDashboardService.getDashboard(slug, forceRefresh);
    return NextResponse.json(data);
  } catch (error: any) {
    console.error("Dashboard API error:", error);
    return NextResponse.json({ error: error.message || "Failed to load dashboard data" }, { status: 500 });
  }
}

import { Prisma } from "@prisma/client";
import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { auth } from "@/auth";
import { callClaudeJson } from "@/app/api/interview/_lib/claude";
import { prisma } from "@/lib/db/prisma";
import { checkDailyRateLimit } from "@/lib/security/ratelimit";
import { decodeCTC, type OtherAllowance, type TaxRegime } from "@/lib/services/ctc-calculator";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const allowanceSchema = z.object({
  name: z.string().min(1).max(80),
  amount: z.number().nonnegative(),
});

const manualBreakdownSchema = z.object({
  quotedCtc: z.number().nonnegative().optional(),
  fixedComponent: z.number().nonnegative(),
  variableComponent: z.number().nonnegative().optional(),
  variablePct: z.number().nonnegative().max(100).optional(),
  basicSalary: z.number().nonnegative(),
  hra: z.number().nonnegative().optional(),
  specialAllowance: z.number().nonnegative().optional(),
  pfEmployer: z.number().nonnegative().optional(),
  gratuityAnnual: z.number().nonnegative().optional(),
  bonus: z.number().nonnegative().optional(),
  esop: z.number().nonnegative().optional(),
  otherAllowances: z.array(allowanceSchema).optional(),
});

const requestSchema = z.object({
  rawText: z.string().max(20000).optional(),
  company: z.string().max(160).optional(),
  manualBreakdown: manualBreakdownSchema.optional(),
  taxRegime: z.enum(["new", "old"]).default("new"),
}).refine((value) => value.rawText?.trim() || value.manualBreakdown, {
  message: "Either rawText or manualBreakdown is required.",
});

type ExtractedOffer = z.infer<typeof manualBreakdownSchema> & {
  company?: string;
};

function toNumber(value: unknown): number {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value !== "string") return 0;

  const normalized = value.replace(/,/g, "").trim().toLowerCase();
  const numeric = Number(normalized.replace(/[^0-9.]/g, ""));
  if (!Number.isFinite(numeric)) return 0;

  if (/\bcr(?:ore)?s?\b/.test(normalized)) return numeric * 10000000;
  if (/\bl(?:akh|ac)?s?\b/.test(normalized)) return numeric * 100000;
  if (/\bk\b/.test(normalized)) return numeric * 1000;
  return numeric;
}

function findAmount(text: string, patterns: RegExp[]): number {
  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (match?.[1]) return toNumber(match[1]);
  }

  return 0;
}

function fallbackExtract(rawText: string): ExtractedOffer {
  const text = rawText.replace(/\s+/g, " ");
  const fixedComponent = findAmount(text, [
    /fixed\s+(?:component|pay|salary|compensation)[^0-9]*(?:inr|rs\.?|₹)?\s*([0-9,.]+\s*(?:lakh|lakhs|lac|lacs|cr|crore|k)?)/i,
    /base\s+(?:salary|pay)[^0-9]*(?:inr|rs\.?|₹)?\s*([0-9,.]+\s*(?:lakh|lakhs|lac|lacs|cr|crore|k)?)/i,
  ]);
  const quotedCtc = findAmount(text, [
    /(?:total\s+)?ctc[^0-9]*(?:inr|rs\.?|₹)?\s*([0-9,.]+\s*(?:lakh|lakhs|lac|lacs|cr|crore|k)?)/i,
    /cost\s+to\s+company[^0-9]*(?:inr|rs\.?|₹)?\s*([0-9,.]+\s*(?:lakh|lakhs|lac|lacs|cr|crore|k)?)/i,
  ]);
  const variableComponent = findAmount(text, [
    /variable\s+(?:pay|component|bonus)[^0-9]*(?:inr|rs\.?|₹)?\s*([0-9,.]+\s*(?:lakh|lakhs|lac|lacs|cr|crore|k)?)/i,
    /performance\s+bonus[^0-9]*(?:inr|rs\.?|₹)?\s*([0-9,.]+\s*(?:lakh|lakhs|lac|lacs|cr|crore|k)?)/i,
  ]);
  const basicSalary = findAmount(text, [/basic\s+(?:salary|pay)[^0-9]*(?:inr|rs\.?|₹)?\s*([0-9,.]+\s*(?:lakh|lakhs|lac|lacs|cr|crore|k)?)/i]);
  const hra = findAmount(text, [/hra[^0-9]*(?:inr|rs\.?|₹)?\s*([0-9,.]+\s*(?:lakh|lakhs|lac|lacs|cr|crore|k)?)/i]);
  const specialAllowance = findAmount(text, [/special\s+allowance[^0-9]*(?:inr|rs\.?|₹)?\s*([0-9,.]+\s*(?:lakh|lakhs|lac|lacs|cr|crore|k)?)/i]);
  const pfEmployer = findAmount(text, [/employer'?s?\s+pf[^0-9]*(?:inr|rs\.?|₹)?\s*([0-9,.]+\s*(?:lakh|lakhs|lac|lacs|cr|crore|k)?)/i]);
  const gratuityAnnual = findAmount(text, [/gratuity[^0-9]*(?:inr|rs\.?|₹)?\s*([0-9,.]+\s*(?:lakh|lakhs|lac|lacs|cr|crore|k)?)/i]);
  const esop = findAmount(text, [/(?:esop|rsu|stock)[^0-9]*(?:inr|rs\.?|₹)?\s*([0-9,.]+\s*(?:lakh|lakhs|lac|lacs|cr|crore|k)?)/i]);
  const usableFixed = fixedComponent || Math.max(0, quotedCtc - variableComponent - pfEmployer - gratuityAnnual);
  const inferredBasic = basicSalary || Math.round(usableFixed * 0.5);

  return {
    quotedCtc,
    fixedComponent: usableFixed,
    variableComponent,
    variablePct: usableFixed > 0 && variableComponent > 0 ? Math.round((variableComponent / usableFixed) * 100) : 0,
    basicSalary: inferredBasic,
    hra: hra || Math.round(inferredBasic * 0.5),
    specialAllowance,
    pfEmployer,
    gratuityAnnual,
    bonus: variableComponent,
    esop,
    otherAllowances: [],
  };
}

function sanitizeExtracted(value: Partial<ExtractedOffer> | null | undefined): ExtractedOffer {
  const fixedComponent = toNumber(value?.fixedComponent);
  const quotedCtc = toNumber(value?.quotedCtc);
  const variableComponent = toNumber(value?.variableComponent);
  const basicSalary = toNumber(value?.basicSalary) || Math.round(fixedComponent * 0.5);
  const allowances = Array.isArray(value?.otherAllowances)
    ? value.otherAllowances.map((item) => ({ name: item.name, amount: toNumber(item.amount) })) as OtherAllowance[]
    : [];

  const extracted: ExtractedOffer = {
    quotedCtc,
    fixedComponent,
    variableComponent,
    variablePct: toNumber(value?.variablePct),
    basicSalary,
    hra: toNumber(value?.hra),
    specialAllowance: toNumber(value?.specialAllowance),
    pfEmployer: toNumber(value?.pfEmployer),
    gratuityAnnual: toNumber(value?.gratuityAnnual),
    bonus: toNumber(value?.bonus),
    esop: toNumber(value?.esop),
    otherAllowances: allowances,
  };

  if (typeof value?.company === "string" && value.company.trim()) {
    extracted.company = value.company.trim();
  }

  return extracted;
}

async function extractFromRawText(rawText: string): Promise<ExtractedOffer> {
  try {
    const { data } = await callClaudeJson<ExtractedOffer>({
      system: "Extract salary components from this Indian offer letter. Return ONLY valid JSON.",
      user: `Extract from: "${rawText}". Return: { company, fixedComponent, quotedCtc, variableComponent, variablePct, basicSalary, hra, specialAllowance, pfEmployer, gratuityAnnual, bonus, esop, otherAllowances: [{name, amount}] }. All values in INR per annum. If a component is not mentioned, set it to 0.`,
      maxTokens: 1200,
    });

    return sanitizeExtracted(data);
  } catch {
    return fallbackExtract(rawText);
  }
}

import { requireUser } from "@/lib/auth/session";
import { errorToResponse } from "@/lib/api/response";

export async function POST(req: NextRequest) {
  try {
    const user = await requireUser();
    const userId = user.id;

    // Rate limit checks
    const limited = await checkDailyRateLimit(userId, 20, "ctc_decode");
    if (!limited.allowed) return NextResponse.json({ error: "Daily CTC decode limit reached." }, { status: 429 });


  const parsed = requestSchema.safeParse(await req.json().catch(() => null));
  if (!parsed.success) return NextResponse.json({ error: "Invalid request payload.", details: parsed.error.flatten() }, { status: 400 });

  const input = parsed.data;
  const extracted = input.rawText?.trim()
    ? await extractFromRawText(input.rawText.trim())
    : sanitizeExtracted(input.manualBreakdown);

  if (!extracted.fixedComponent && !extracted.quotedCtc) {
    return NextResponse.json({ error: "Could not identify salary components from the offer." }, { status: 400 });
  }

  const fixedComponent = extracted.fixedComponent || extracted.quotedCtc || 0;
  const decoded = decodeCTC({
    quotedCtc: extracted.quotedCtc ?? 0,
    fixedComponent,
    variableComponent: extracted.variableComponent ?? 0,
    variablePct: extracted.variablePct ?? 0,
    basicSalary: extracted.basicSalary,
    hra: extracted.hra ?? 0,
    specialAllowance: extracted.specialAllowance ?? 0,
    pfEmployer: extracted.pfEmployer ?? 0,
    gratuityAnnual: extracted.gratuityAnnual ?? 0,
    bonus: extracted.bonus ?? 0,
    esop: extracted.esop ?? 0,
    otherAllowances: extracted.otherAllowances ?? [],
    taxRegime: input.taxRegime as TaxRegime,
  });

  const record = await prisma.ctcDecoding.create({
    data: {
      userId,
      rawInput: input.rawText ?? null,
      company: input.company ?? extracted.company ?? null,
      quotedCtc: decoded.quotedCtc,
      fixedComponent: decoded.fixedComponent,
      variableComponent: decoded.variableComponent,
      variablePct: decoded.variablePct,
      basicSalary: decoded.basicSalary,
      hra: decoded.hra,
      specialAllowance: decoded.specialAllowance,
      pfEmployee: decoded.pfEmployee,
      pfEmployer: decoded.pfEmployer,
      gratuityAnnual: decoded.gratuityAnnual,
      bonus: decoded.bonus,
      esop: decoded.esop,
      otherAllowances: decoded.otherAllowances as unknown as Prisma.InputJsonValue,
      grossMonthly: decoded.grossMonthly,
      netMonthly: decoded.netMonthly,
      taxAnnual: decoded.taxAnnual,
      taxRegime: decoded.taxRegime,
      effectiveCtc: decoded.effectiveCtc,
    },
  });

  return NextResponse.json({ id: record.id, ...decoded });
  } catch (error) {
    return errorToResponse(error);
  }
}

import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { prisma } from "@/lib/db/prisma";
import { unstable_cache } from "next/cache";
import type { MomentumTask, MomentumTaskType } from "@/types/momentum";
import {
  getUserApplicationsWithStatus,
  getResumeLastUpdated,
  getPendingSkillGaps,
} from "@/lib/db/momentum";

export const runtime = "nodejs";

// Helper function to get cached momentum data partitioned by userId
const getCachedMomentumData = (userId: string) =>
  unstable_cache(
    async () => {
      const [applications, latestResume, skillGaps, jobOpportunities] = await Promise.all([
        getUserApplicationsWithStatus(userId),
        getResumeLastUpdated(userId),
        getPendingSkillGaps(userId),
        prisma.jobOpportunity.findMany({
          where: { userId },
          orderBy: { matchScore: "desc" },
          take: 5,
        }),
      ]);
      return { applications, latestResume, skillGaps, jobOpportunities };
    },
    [`momentum-tasks-${userId}`],
    {
      revalidate: 3600, // Cache for 1 hour
      tags: [`momentum-tasks-${userId}`],
    }
  )();

export async function GET(request: Request) {
  try {
    const session = await auth();
    const userId = session?.user?.id;

    if (!userId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { searchParams } = new URL(request.url);
    const forceRefresh = searchParams.get("refresh") === "true";
    const salaryBenchmarkViewed = searchParams.get("salaryBenchmarkViewed") === "true";

    // 1. Retrieve Data (either via Cache or direct DB query if forcing refresh)
    let data;
    if (forceRefresh) {
      const [applications, latestResume, skillGaps, jobOpportunities] = await Promise.all([
        getUserApplicationsWithStatus(userId),
        getResumeLastUpdated(userId),
        getPendingSkillGaps(userId),
        prisma.jobOpportunity.findMany({
          where: { userId },
          orderBy: { matchScore: "desc" },
          take: 5,
        }),
      ]);
      data = { applications, latestResume, skillGaps, jobOpportunities };
    } else {
      data = await getCachedMomentumData(userId);
    }

    const { applications, latestResume, skillGaps, jobOpportunities } = data;
    const tasks: MomentumTask[] = [];

    // 2. PRIORITY GENERATION LOGIC

    // Rule 1: Interview Scheduled (status === 'interview')
    const interviewApps = applications.filter((a) => a.status === "interview");
    if (interviewApps.length > 0) {
      const app = interviewApps[0];
      if (app) {
        // Assume interview is 5 days away from updatedAt if not specified
        const daysUntil = Math.max(
          1,
          Math.ceil((app.updatedAt.getTime() + 5 * 24 * 60 * 60 * 1000 - Date.now()) / (24 * 60 * 60 * 1000))
        );
        tasks.push({
          id: `interview-${app.id}`,
          text: `Prep for your ${app.company} interview — ${daysUntil} days away`,
          priority: "urgent",
          link: "/interview",
          icon: "Calendar",
          type: "interview",
        });
      }
    }

    // Rule 2: Applied with no response for >= 7 days
    const appliedApps = applications.filter((a) => a.status === "applied");
    const silenceThreshold = 7 * 24 * 60 * 60 * 1000;
    const silentApp = appliedApps.find((a) => Date.now() - a.updatedAt.getTime() >= silenceThreshold);
    if (silentApp) {
      const daysSince = Math.floor((Date.now() - silentApp.updatedAt.getTime()) / (24 * 60 * 60 * 1000));
      tasks.push({
        id: `followup-${silentApp.id}`,
        text: `Follow up on ${silentApp.company} application — ${daysSince} days of silence`,
        priority: "urgent",
        link: "/applications",
        icon: "MessageSquare",
        type: "followup",
      });
    }

    // Rule 3: No applications in last 14 days
    const lastApplication = applications[0];
    const fourteenDaysAgo = 14 * 24 * 60 * 60 * 1000;
    const hasRecentApp = lastApplication && Date.now() - lastApplication.updatedAt.getTime() < fourteenDaysAgo;
    if (!lastApplication || !hasRecentApp) {
      const daysSince = lastApplication
        ? Math.floor((Date.now() - lastApplication.updatedAt.getTime()) / (24 * 60 * 60 * 1000))
        : 14; // Default to 14 if never applied
      tasks.push({
        id: "no-applications",
        text: `You haven't applied in ${daysSince} days — apply to 3 roles today`,
        priority: "normal",
        link: "/matches",
        icon: "Briefcase",
        type: "apply",
      });
    }

    // Rule 4: Resume hasn't been updated in > 30 days
    const thirtyDaysAgo = 30 * 24 * 60 * 60 * 1000;
    if (latestResume && Date.now() - latestResume.updatedAt.getTime() > thirtyDaysAgo) {
      const daysSince = Math.floor((Date.now() - latestResume.updatedAt.getTime()) / (24 * 60 * 60 * 1000));
      tasks.push({
        id: "resume-outdated",
        text: `Your resume is ${daysSince} days old — refresh metrics before applying`,
        priority: "normal",
        link: "/builder",
        icon: "FileText",
        type: "resume",
      });
    }

    // Rule 5: Offer received (status === 'offer')
    const offerApps = applications.filter((a) => a.status === "offer");
    if (offerApps.length > 0) {
      const app = offerApps[0];
      if (app) {
        const deadlineDate = new Date(app.updatedAt.getTime() + 7 * 24 * 60 * 60 * 1000);
        const deadline = deadlineDate.toLocaleDateString("en-US", { month: "short", day: "numeric" });
        tasks.push({
          id: `offer-${app.id}`,
          text: `You have an offer from ${app.company} — use Salary Intelligence to negotiate before ${deadline}`,
          priority: "urgent",
          link: "/compare-offers",
          icon: "Award",
          type: "offer",
        });
      }
    }

    // Rule 6: No salary benchmark viewed in current session
    if (!salaryBenchmarkViewed) {
      let topCompany = "Atlassian";
      if (jobOpportunities.length > 0 && jobOpportunities[0]) {
        topCompany = jobOpportunities[0].company;
      } else if (applications.length > 0 && applications[0]) {
        topCompany = applications[0].company;
      }
      tasks.push({
        id: "salary-benchmark",
        text: `Check SDE2 salaries at ${topCompany} — updated this week`,
        priority: "normal",
        link: "/salary-intelligence",
        icon: "TrendingUp",
        type: "salary",
      });
    }

    // Rule 7: Skill gaps identified but not acted on
    const pendingGapAnalysis = skillGaps.find((g) => {
      const gap = Array.isArray(g.gapSkills) ? g.gapSkills : [];
      const completed = Array.isArray(g.completedSkills) ? g.completedSkills : [];
      return gap.length > completed.length;
    });
    if (pendingGapAnalysis) {
      const gap = Array.isArray(pendingGapAnalysis.gapSkills) ? pendingGapAnalysis.gapSkills : [];
      const completed = Array.isArray(pendingGapAnalysis.completedSkills) ? pendingGapAnalysis.completedSkills : [];
      const missingCount = gap.length - completed.length;
      tasks.push({
        id: "skill-gaps",
        text: `${missingCount} skills in your JDs are missing from your resume`,
        priority: "normal",
        link: "/skill-gap",
        icon: "Brain",
        type: "skill_gap",
      });
    }

    // Rule 8: Fallback (New user / no other tasks triggered)
    if (tasks.length === 0) {
      tasks.push({
        id: "fallback-onboarding",
        text: "Add your first target role to unlock personalized tasks",
        priority: "normal",
        link: "/onboarding",
        icon: "Sparkles",
        type: "fallback",
      });
    }

    // Return the prioritized list (unfiltered - client side handles mood filtering)
    return NextResponse.json({ tasks });
  } catch (error) {
    console.error("[MOMENTUM_TASKS_API]", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/db/prisma";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function POST(req: NextRequest) {
  try {
    const body = await req.json().catch(() => null);
    if (!body || !body.email || !body.userId) {
      return NextResponse.json({ error: "Missing email or userId" }, { status: 400 });
    }

    const { email, userId } = body;

    const existing = await prisma.emailCapture.findUnique({
      where: { email },
    });

    if (existing) {
      const updated = await prisma.emailCapture.update({
        where: { email },
        data: {
          convertedAt: new Date(),
          userId,
        },
      });
      return NextResponse.json({ success: true, updated: updated.id });
    }

    return NextResponse.json({ success: false, message: "Lead not found" }, { status: 404 });
  } catch (error: any) {
    console.error("[CONVERT API] Conversion failed:", error);
    return NextResponse.json(
      { error: error.message || "Internal server error during conversion" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { prisma } from "@/lib/db/prisma";
import { sendEmail } from "@/lib/mailer";
import { getWelcomeEmailHtml } from "@/emails/WelcomeCapture";
import { scheduleEmailSequence, startEmailCaptureWorker } from "@/lib/queue/email-capture-queue";

const captureSchema = z.object({
  email: z.string().trim().toLowerCase().email("Invalid email address").min(5).max(254),
  source: z.string().min(1).max(100),
  metadata: z.record(z.string(), z.any()).optional(),
});

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

// Initialize the drip worker once when this API is hit
try {
  startEmailCaptureWorker();
} catch (e) {
  console.error("[MAILER-QUEUE] Worker initialization failed:", e);
}

export async function POST(req: NextRequest) {
  try {
    const body = await req.json().catch(() => null);
    const parsed = captureSchema.safeParse(body);
    if (!parsed.success) {
      return NextResponse.json(
        { error: "Invalid payload details", details: parsed.error.flatten() },
        { status: 400 }
      );
    }

    const { email, source, metadata } = parsed.data;

    // Check if user already exists
    const existing = await prisma.emailCapture.findUnique({
      where: { email },
    });

    const alreadyExists = !!existing;

    // Upsert EmailCapture record
    const record = await prisma.emailCapture.upsert({
      where: { email },
      update: {
        source,
        metadata: metadata ?? {},
      },
      create: {
        email,
        source,
        metadata: metadata ?? {},
      },
    });

    // 1. Send Welcome Email Immediately
    const subject = "Your CareerOS results are saved 🎯";
    const html = getWelcomeEmailHtml(source, {
      ...metadata,
      email,
    });

    try {
      await sendEmail({
        to: email,
        subject,
        html,
      });
    } catch (emailError) {
      console.error("[MAILER] Welcome email sending failed:", emailError);
      // We still want to return success because the capture succeeded
    }

    // 2. Schedule Day 3, 7, 14 Follow-up drip sequence using BullMQ
    try {
      await scheduleEmailSequence(record.id, email);
    } catch (queueError) {
      console.error("[QUEUE] Failed to schedule drip emails sequence:", queueError);
    }

    return NextResponse.json({
      success: true,
      alreadyExists,
      id: record.id,
      email: record.email,
    });
  } catch (error: any) {
    console.error("[EMAIL CAPTURE API] Failed:", error);
    return NextResponse.json(
      { error: error.message || "Internal server error during capture" },
      { status: 500 }
    );
  }
}

import { NextRequest } from "next/server";
import { auth } from "@/auth";
import { prisma } from "@/lib/db/prisma";
import { apiOk, apiError } from "@/lib/api/response";

export const runtime = "nodejs";

export async function GET(req: NextRequest) {
  const session = await auth();
  if (!session?.user?.id) return apiError("Unauthorized", 401);

  const userId = session.user.id;

  const resume = await prisma.resume.findFirst({
    where: { userId },
    orderBy: { updatedAt: "desc" },
  });

  const data = (resume?.data ?? {}) as Record<string, unknown>;
  const personal = (data.personal ?? data.personalInfo ?? {}) as Record<string, unknown>;
  const contact = (data.contact ?? {}) as Record<string, unknown>;
  const links = (data.links ?? data.profiles ?? {}) as Record<string, unknown>;

  const skills: string[] = [];
  if (Array.isArray(data.skills)) {
    for (const s of data.skills) {
      if (typeof s === "string") skills.push(s);
      else if (typeof s === "object" && s !== null && "name" in s) skills.push(String((s as { name: unknown }).name));
    }
  }

  return apiOk({
    firstName: String(personal.firstName ?? personal.first_name ?? ""),
    lastName: String(personal.lastName ?? personal.last_name ?? ""),
    email: session.user.email ?? String(contact.email ?? ""),
    phone: String(personal.phone ?? contact.phone ?? ""),
    linkedin: String(links.linkedin ?? links.linkedinUrl ?? ""),
    github: String(links.github ?? links.githubUrl ?? ""),
    portfolio: String(links.portfolio ?? links.website ?? links.portfolioUrl ?? ""),
    location: String(personal.location ?? personal.city ?? ""),
    skills,
    currentRole: String(personal.title ?? personal.headline ?? personal.currentRole ?? ""),
  });
}

