import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { prisma } from "@/lib/db/prisma";

export async function PATCH(request: Request) {
  const session = await auth();
  if (!session?.user?.id) return new NextResponse("Unauthorized", { status: 401 });

  try {
    const body = await request.json();
    const enabled = Boolean(body.enabled);

    const profile = await prisma.careerProfile.findUnique({ where: { userId: session.user.id } });
    if (!profile) {
       return new NextResponse("Profile not found", { status: 404 });
    }

    const prefs = (profile.preferences as Record<string, unknown>) || {};
    prefs.marketDigestEnabled = enabled;

    await prisma.careerProfile.update({
      where: { userId: session.user.id },
      data: { preferences: prefs as any }
    });

    return NextResponse.json({ success: true, enabled });
  } catch (e) {
    console.error("[PreferencesAPI] Error updating market-digest", e);
    return new NextResponse("Error updating preferences", { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { auth } from "@/auth";
import { prisma } from "@/lib/db/prisma";

export const runtime = "nodejs";

const schema = z.object({
  resumeId: z.string().uuid(),
  suggestionId: z.string().uuid(),
  applyFields: z.array(z.enum(['summary', 'skills', 'education', 'projects'])),
});

export async function POST(req: NextRequest) {
  try {
    const session = await auth();
    const userId = session?.user?.id;
    if (!userId) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    const parsed = schema.safeParse(await req.json().catch(() => null));
    if (!parsed.success) return NextResponse.json({ error: "Invalid request payload." }, { status: 400 });

    const { resumeId, suggestionId, applyFields } = parsed.data;

    if (applyFields.length === 0) {
      return NextResponse.json({ error: "No fields selected to apply" }, { status: 400 });
    }

    const [resume, suggestion] = await Promise.all([
      prisma.resume.findUnique({ where: { id: resumeId, userId } }),
      prisma.resumeEqualizerSuggestion.findUnique({ where: { id: suggestionId, userId, resumeId } }),
    ]);

    if (!resume) return NextResponse.json({ error: "Resume not found" }, { status: 404 });
    if (!suggestion) return NextResponse.json({ error: "Suggestion not found" }, { status: 404 });

    // Create a new version of the resume before modifying
    const latestVersion = await prisma.resumeVersion.findFirst({
      where: { resumeId },
      orderBy: { version: 'desc' }
    });

    const nextVersionNum = (latestVersion?.version || resume.version || 1) + 1;

    await prisma.resumeVersion.create({
      data: {
        resumeId,
        userId,
        version: nextVersionNum,
        title: `Before Equalization (${new Date().toLocaleString()})`,
        data: resume.data || {},
      }
    });

    const data = JSON.parse(JSON.stringify(resume.data)) as any;

    // Apply rewrites
    if (applyFields.includes('summary') && suggestion.summaryRewrite) {
      if (!data.personal) data.personal = {};
      data.personal.summary = suggestion.summaryRewrite;
    }

    if (applyFields.includes('skills') && suggestion.skillsSectionBoost) {
      // In a real scenario we'd parse or merge, but since the LLM gave a string for skillsSectionBoost,
      // we'll replace the text. Or if it's supposed to be an array:
      // Typically `data.skills` is an array of strings. We could just dump it as a single element or attempt to split it.
      // Assuming skillsSectionBoost is stringified or comma separated.
      data.skills = suggestion.skillsSectionBoost.split(',').map(s => s.trim()).filter(Boolean);
    }

    if (applyFields.includes('education') && suggestion.educationDeEmphasis) {
      if (data.education && data.education.length > 0) {
        data.education[0].institution = suggestion.educationDeEmphasis; 
        // We could overwrite the whole entry but doing simple replacement for this feature prototype.
        // Usually, the LLM will provide a condensed version of the degree.
      }
    }

    if (applyFields.includes('projects') && suggestion.projectHighlights && Array.isArray(suggestion.projectHighlights)) {
      if (data.experience && Array.isArray(data.experience)) {
        suggestion.projectHighlights.forEach((highlight: any) => {
          const expIndex = data.experience.findIndex((e: any) => e.id === highlight.experienceId);
          if (expIndex !== -1 && highlight.rewrittenPoints) {
            data.experience[expIndex].points = highlight.rewrittenPoints;
          }
        });
      }
    }

    // Move projects/experience above education if we're optimizing formatting
    if (applyFields.includes('education') || applyFields.includes('projects')) {
      // Typically handled by a layout property in ResumeData, let's just append a metadata flag
      if (!data.layout) data.layout = {};
      data.layout.sectionOrder = ['personal', 'summary', 'skills', 'experience', 'education'];
    }

    // Save updated resume
    const updatedResume = await prisma.resume.update({
      where: { id: resumeId },
      data: {
        data,
        version: nextVersionNum,
      },
    });

    // Mark as applied
    await prisma.resumeEqualizerSuggestion.update({
      where: { id: suggestionId },
      data: { appliedAt: new Date() },
    });

    return NextResponse.json({ 
      message: "Equalizer applied successfully",
      resume: updatedResume
    });

  } catch (error: any) {
    console.error("[Equalizer Apply Error]:", error);
    return NextResponse.json({ error: "Failed to apply equalizer suggestion." }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { auth } from "@/auth";
import { callClaudeJson } from "@/app/api/interview/_lib/claude";
import { prisma } from "@/lib/db/prisma";
import { detectCollegeTier } from "@/lib/data/tier1-colleges";

export const runtime = "nodejs";

const schema = z.object({
  resumeId: z.string().uuid(),
  targetRole: z.string().min(1),
});

export async function POST(req: NextRequest) {
  try {
    const session = await auth();
    const userId = session?.user?.id;
    if (!userId) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    const parsed = schema.safeParse(await req.json().catch(() => null));
    if (!parsed.success) return NextResponse.json({ error: "Invalid request payload." }, { status: 400 });

    const { resumeId, targetRole } = parsed.data;

    const resume = await prisma.resume.findUnique({
      where: { id: resumeId, userId },
    });

    if (!resume) return NextResponse.json({ error: "Resume not found" }, { status: 404 });

    const data = resume.data as any;
    const education = data.education?.[0];
    const collegeName = education?.institution || "";

    const tier = detectCollegeTier(collegeName);

    if (tier === 'tier1') {
      return NextResponse.json({
        tier: 'tier1',
        message: 'Your college is well-recognized. Focus on quantifying your impact and projects.',
        suggestion: null
      });
    }

    const systemPrompt = `You are an expert resume strategist specializing in "opportunity signal optimization". Help candidates from non-IIT/NIT colleges compete by re-ordering and rewriting their resume to emphasize skills and impact over education to counter ATS and recruiter bias. 

Return ONLY valid JSON matching this schema:
{
  "suggestedFormat": "skills_first",
  "summaryRewrite": "string (no mention of college, 100% skills and impact focused)",
  "skillsSectionBoost": "string (expanded skills section format or content to display prominently)",
  "educationDeEmphasis": "string (factual but de-emphasized education entry)",
  "projectHighlights": [{ "experienceId": "string", "rewrittenPoints": ["string"] }],
  "rationale": "string (WHY these sections changed. e.g., 'Moved projects above education because recruiters spend more time on measurable impact signals. This format puts your skills front and center.')",
  "signalDensity": "string (e.g., 'Current resume: 40% space spent on low-signal content. High-impact content underrepresented...')",
  "attentionGain": number (e.g., 28 for +28% estimated recruiter attention gain)
}

CRITICAL RULES:
1. NEVER fabricate achievements, inflate titles, or invent metrics.
2. NEVER hide education entirely.
3. ONLY reorder, rewrite for clarity, emphasize evidence, and improve signal hierarchy.
4. Your rationale must explain WHY the changes improve recruiter signal tracking.`;

    const userPrompt = `Resume data: ${JSON.stringify(data)}. 
Target role: ${targetRole}. 
College: ${collegeName} (tier ${tier}). 
The resume currently leads with education — this creates unconscious bias. Generate skill-first rewrites according to the schema.`;

    const { data: suggestionData } = await callClaudeJson<any>({
      system: systemPrompt,
      user: userPrompt,
      maxTokens: 3000,
    });

    const suggestion = await prisma.resumeEqualizerSuggestion.create({
      data: {
        resumeId,
        userId,
        collegeName,
        collegeTier: tier,
        suggestedFormat: suggestionData.suggestedFormat || "skills_first",
        summaryRewrite: suggestionData.summaryRewrite,
        skillsSectionBoost: suggestionData.skillsSectionBoost,
        educationDeEmphasis: suggestionData.educationDeEmphasis,
        projectHighlights: suggestionData.projectHighlights || [],
        rationale: suggestionData.rationale || "Optimized signal hierarchy to prioritize impact.",
        signalDensity: suggestionData.signalDensity || null,
        attentionGain: suggestionData.attentionGain || null,
      }
    });

    return NextResponse.json({
      tier,
      message: 'AI detected opportunity for skill-first repositioning.',
      suggestion,
    });

  } catch (error: any) {
    console.error("[Equalizer API Error]:", error);
    return NextResponse.json({ error: "Failed to generate equalizer suggestion." }, { status: 500 });
  }
}

