"use client";

import React, { useState, useEffect, useMemo } from "react";
import { 
  CheckCircle2, 
  Circle, 
  ArrowRight, 
  Sparkles, 
  Smile, 
  Brain, 
  FileText, 
  CheckCircle,
  HelpCircle,
  Clock,
  Briefcase,
  ExternalLink,
  ChevronRight,
  Heart
} from "lucide-react";
import Link from "next/link";
import { motion, AnimatePresence } from "framer-motion";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { WeeklyMomentumCard } from "./WeeklyMomentumCard";

// Props from Server Component
interface ZenDashboardProps {
  stats: {
    totalApplications: number;
    resumeCount: number;
    hasPendingApproval: boolean;
    upcomingInterview: { id: string; company: string; role: string; updatedAt: string } | null;
    totalOffers: number;
    totalApplied: number;
  };
}

type MoodState = "focused" | "calm" | "anxious" | "tired" | null;

export function ZenDashboard({ stats }: ZenDashboardProps) {
  // 1. Emotional motivation state
  const [mood, setMood] = useState<MoodState>(null);

  useEffect(() => {
    const savedMood = localStorage.getItem("careerOS_mood");
    if (savedMood) setMood(savedMood as MoodState);
  }, []);

  const handleSetMood = (selected: MoodState) => {
    setMood(selected);
    if (selected) {
      localStorage.setItem("careerOS_mood", selected);
    } else {
      localStorage.removeItem("careerOS_mood");
    }

    // Dispatch storage event manually so other components in the same window update immediately
    if (typeof window !== "undefined") {
      window.dispatchEvent(new Event("storage"));
    }
  };

  // 3. Primary Mission of the Day (One Primary Action Rule)
  const primaryMission = useMemo(() => {
    if (stats.resumeCount === 0) {
      return {
        title: "Create or upload your first resume snapshot",
        why: "Unlocks the ATS parser & starts scanning matching tech positions in India.",
        cta: "Create Profile Resume",
        href: "/builder",
        color: "border-violet-500 bg-violet-950/10 text-violet-400"
      };
    }
    if (stats.totalApplications === 0) {
      return {
        title: "Review top job matches for your level",
        why: "We found active roles matching your tech stack. Review fit rates before applying.",
        cta: "Scan Active Matches",
        href: "/matches",
        color: "border-cyan-500 bg-cyan-950/10 text-cyan-400"
      };
    }
    if (stats.upcomingInterview) {
      return {
        title: `Prepare for your ${stats.upcomingInterview.company} interview`,
        why: "Hiring managers check architecture decisions. Run a mock prep now.",
        cta: "Start Mock Simulator",
        href: "/interview",
        color: "border-emerald-500 bg-emerald-950/10 text-emerald-400"
      };
    }
    if (stats.hasPendingApproval) {
      return {
        title: "Review pending outreach drafts",
        why: "Your automated agent generated customized networking templates for target hiring leads.",
        cta: "Review & Dispatch Drafts",
        href: "/agents",
        color: "border-amber-500 bg-amber-950/10 text-amber-400"
      };
    }
    // Default fallback
    return {
      title: "Optimize resume metrics for target companies",
      why: "Adding quantitative results to your experience bullets can boost callback rates by 40%.",
      cta: "Run Resume Diagnostic",
      href: "/ats",
      color: "border-cyan-500 bg-cyan-950/10 text-cyan-400"
    };
  }, [stats]);

  // Support messages for wellbeing check-in
  const moodGreetings: Record<NonNullable<MoodState>, string> = {
    focused: "Superb. Let's block out the noise and work on your single most high-leverage step today.",
    calm: "Excellent. Steady progress beats frantic application bursts every single time. Breathe.",
    anxious: "That is completely normal. The search is a marathon, not a sprint. Just focus on one tiny checklist step today.",
    tired: "Rest is part of the work. If you need to step away after ticking off today's primary action, do it."
  };

  return (
    <div className="space-y-8 font-mono max-w-[900px] mx-auto text-left">

      {/* 1. ZEN HEADER GREETING */}
      <div className="space-y-2 border-b border-border pb-6">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h1 className="text-xl font-bold uppercase tracking-tight text-foreground">
              WELCOME BACK
            </h1>
            <p className="text-xs text-muted-foreground mt-0.5">
              Focus on today&apos;s single high-leverage action. Avoid the application clutter.
            </p>
          </div>

          {/* Quick Wellbeing Check-in */}
          <div className="flex items-center gap-2 bg-[#0e1117] border border-border px-3 py-1.5 rounded-none">
            <span className="text-[9px] text-muted-foreground uppercase font-bold mr-1 flex items-center gap-1">
              <Heart className="h-3 w-3 text-red-500 fill-red-500" /> State Check:
            </span>
            <div className="flex gap-1">
              {(["calm", "focused", "anxious", "tired"] as MoodState[]).map(m => (
                <button
                  key={m}
                  onClick={() => handleSetMood(m)}
                  className={`text-[9px] px-2 py-0.5 border capitalize transition-all ${
                    mood === m
                      ? "border-cyan-400 bg-cyan-950/20 text-cyan-400 font-bold"
                      : "border-border text-muted-foreground hover:text-foreground"
                  }`}
                >
                  {m}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Dynamic support caption based on check-in */}
        {mood && (
          <motion.p
            initial={{ opacity: 0, y: 3 }}
            animate={{ opacity: 1, y: 0 }}
            className="text-xs text-cyan-400 font-semibold mt-2.5 leading-normal"
          >
            {moodGreetings[mood]}
          </motion.p>
        )}
      </div>

      {/* 2. THE ONE PRIMARY ACTION (Mission Card) */}
      <div className={`border p-6 relative overflow-hidden ${primaryMission.color}`}>
        <div className="absolute top-0 right-0 bg-[#0b0d13] border-l border-b border-border px-3 py-1 text-[8px] uppercase tracking-widest font-black text-muted-foreground">
          Primary Mission
        </div>

        <div className="space-y-4">
          <div className="space-y-1.5 max-w-xl">
            <h2 className="text-base font-bold text-foreground leading-snug">
              {primaryMission.title}
            </h2>
            <p className="text-xs text-muted-foreground leading-relaxed">
              <strong className="text-foreground uppercase tracking-widest text-[9px] block mb-1">Why it matters:</strong>
              {primaryMission.why}
            </p>
          </div>

          <Link href={primaryMission.href} className="inline-block pt-1">
            <Button className="h-10 rounded-none bg-foreground text-background font-bold text-xs uppercase px-5 hover:opacity-95 flex items-center gap-2">
              {primaryMission.cta} <ArrowRight className="h-3.5 w-3.5" />
            </Button>
          </Link>
        </div>
      </div>

      {/* 3. MOMENTUM TRACK & STATS FUNNEL */}
      <div className="grid grid-cols-1 gap-6 md:grid-cols-[1.3fr_1fr]">

        {/* Daily Tasks Checklist */}
        {/* Dynamic Weekly Momentum Card */}
        <WeeklyMomentumCard />

        {/* Minimal Pipeline Status Funnel */}
        <div className="border border-border bg-[#0b0d13] p-6 space-y-4">
          <span className="text-xs font-bold text-foreground uppercase tracking-wider block border-b border-border/40 pb-3">
            JOB SEARCH PIPELINE STATUS
          </span>

          <div className="grid grid-cols-2 gap-4 pt-1">
            <div className="border border-border bg-[#0e1117] p-3 text-left">
              <span className="text-[9px] text-muted-foreground uppercase">Resumes Active</span>
              <div className="text-xl font-bold text-foreground mt-1">{stats.resumeCount}</div>
            </div>
            <div className="border border-border bg-[#0e1117] p-3 text-left">
              <span className="text-[9px] text-muted-foreground uppercase">Applied (Dispatches)</span>
              <div className="text-xl font-bold text-foreground mt-1">{stats.totalApplied}</div>
            </div>
            <div className="border border-border bg-[#0e1117] p-3 text-left">
              <span className="text-[9px] text-muted-foreground uppercase">Interviews Scheduled</span>
              <div className="text-xl font-bold text-emerald-400 mt-1">{stats.totalApplied > 0 ? (stats.upcomingInterview ? 1 : 0) : 0}</div>
            </div>
            <div className="border border-border bg-[#0e1117] p-3 text-left">
              <span className="text-[9px] text-muted-foreground uppercase">Offers Secured</span>
              <div className="text-xl font-bold text-cyan-400 mt-1">{stats.totalOffers}</div>
            </div>
          </div>
        </div>

      </div>

      {/* 4. PREPARATION READINESS STATS */}
      <div className="border border-border bg-[#0b0d13] p-6 space-y-4">
        <span className="text-xs font-bold text-foreground uppercase tracking-wider block border-b border-border/40 pb-3">
          READINESS INTEGRITY OVERVIEW
        </span>

        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 text-xs">
          <div className="flex items-start gap-3 bg-[#0e1117] p-3.5 border border-border">
            <div className="flex h-7 w-7 shrink-0 items-center justify-center bg-cyan-950/20 border border-cyan-800 text-cyan-400">
              <FileText className="h-4 w-4" />
            </div>
            <div>
              <span className="font-bold text-foreground block">Resume Score Integrity</span>
              <p className="text-[10px] text-muted-foreground mt-1 leading-normal">
                {stats.resumeCount > 0 
                  ? "Standard tags parsed successfully. Needs metric checks for target startups."
                  : "No resume found. Upload to analyze compliance."}
              </p>
            </div>
          </div>

          <div className="flex items-start gap-3 bg-[#0e1117] p-3.5 border border-border">
            <div className="flex h-7 w-7 shrink-0 items-center justify-center bg-emerald-950/20 border border-emerald-800 text-emerald-400">
              <Brain className="h-4 w-4" />
            </div>
            <div>
              <span className="font-bold text-foreground block">Interview Readiness Index</span>
              <p className="text-[10px] text-muted-foreground mt-1 leading-normal">
                {stats.upcomingInterview
                  ? `Upcoming interview at ${stats.upcomingInterview.company}. Custom mock workspace created.`
                  : "Mock interview practice recommended for SDE-2 structures."}
              </p>
            </div>
          </div>
        </div>
      </div>

    </div>
  );
}

"use client";

import React, { useState } from "react";
import { X, Award, Zap, TrendingUp, ShieldCheck, Loader2, ArrowRight, AlertTriangle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { safeFetch } from "@/lib/utils/safeFetch";

export function CollegeEqualizerPanel({
  resumeId,
  resumeData,
  onClose,
  onApplied
}: {
  resumeId: string;
  resumeData: any;
  onClose: () => void;
  onApplied: () => void;
}) {
  const [status, setStatus] = useState<"idle" | "loading" | "success" | "error">("idle");
  const [tier, setTier] = useState<"tier1" | "tier2" | "tier3" | null>(null);
  const [suggestion, setSuggestion] = useState<any>(null);
  const [applying, setApplying] = useState<string[]>([]);

  const institution = resumeData?.education?.[0]?.institution || "Unknown College";

  const analyze = async () => {
    setStatus("loading");
    try {
      const res = await safeFetch("/api/v1/resume/equalize", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ resumeId, targetRole: resumeData?.personal?.title || "Software Engineer" })
      });
      if (res.error) throw new Error(res.error);

      const data = res.data as any;
      setTier(data.tier);
      if (data.suggestion) {
        setSuggestion(data.suggestion);
      }
      setStatus("success");
    } catch (err) {
      console.error(err);
      setStatus("error");
    }
  };

  const applyField = async (field: string) => {
    if (!suggestion) return;
    setApplying(prev => [...prev, field]);
    try {
      const res = await safeFetch("/api/v1/resume/equalize/apply", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          resumeId,
          suggestionId: suggestion.id,
          applyFields: [field]
        })
      });
      if (res.error) throw new Error(res.error);
      onApplied();
    } catch (err) {
      console.error(err);
    } finally {
      setApplying(prev => prev.filter(f => f !== field));
    }
  };

  const applyAll = async () => {
    if (!suggestion) return;
    const allFields = ['summary', 'skills', 'education', 'projects'];
    setApplying(allFields);
    try {
      const res = await safeFetch("/api/v1/resume/equalize/apply", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          resumeId,
          suggestionId: suggestion.id,
          applyFields: allFields
        })
      });
      if (res.error) throw new Error(res.error);
      onApplied();
      onClose();
    } catch (err) {
      console.error(err);
    } finally {
      setApplying([]);
    }
  };

  return (
    <div className="absolute inset-0 z-40 flex justify-end">
      <div className="absolute inset-0 bg-black/20 backdrop-blur-sm" onClick={onClose} />
      <div className="relative w-[480px] bg-white shadow-2xl h-full border-l border-gray-200 flex flex-col animate-in slide-in-from-right-8 duration-300">

        {/* Header */}
        <div className="px-6 py-5 border-b border-gray-100 flex items-center justify-between shrink-0 bg-gray-50/50">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-indigo-100 text-indigo-600 rounded-lg">
              <Award className="h-5 w-5" />
            </div>
            <div>
              <h3 className="text-sm font-black tracking-tight text-gray-900">Skill-First Equalizer</h3>
              <p className="text-xs font-medium text-gray-500">Opportunity Signal Optimization</p>
            </div>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-lg text-gray-400 transition-colors">
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto custom-scrollbar p-6">
          {status === "idle" && (
            <div className="flex flex-col items-center justify-center text-center mt-12">
              <div className="w-16 h-16 bg-amber-100 text-amber-600 rounded-full flex items-center justify-center mb-6">
                <ShieldCheck className="w-8 h-8" />
              </div>
              <h4 className="text-lg font-black text-gray-900 mb-2">Analyze Signals</h4>
              <p className="text-sm text-gray-500 mb-8 max-w-sm">
                Many engineers miss opportunities due to ATS college filters. We'll analyze your resume to ensure it leads with skills and impact, not pedigree.
              </p>
              <Button onClick={analyze} className="w-full max-w-xs h-12 rounded-xl bg-indigo-600 hover:bg-indigo-700 text-white font-bold shadow-lg">
                Analyze & Optimize
              </Button>
            </div>
          )}

          {status === "loading" && (
            <div className="flex flex-col items-center justify-center text-center mt-24">
              <Loader2 className="w-8 h-8 text-indigo-600 animate-spin mb-4" />
              <p className="text-sm font-bold text-gray-500 animate-pulse">Analyzing signal density...</p>
            </div>
          )}

          {status === "error" && (
            <div className="p-6 bg-rose-50 rounded-2xl border border-rose-100 text-center mt-12">
              <AlertTriangle className="w-10 h-10 text-rose-500 mx-auto mb-3" />
              <h4 className="font-black text-rose-900 mb-2">Analysis Failed</h4>
              <p className="text-sm text-rose-700 font-medium mb-4">
                Could not complete the analysis. Check your connection and try again.
              </p>
              <Button onClick={() => setStatus("idle")} variant="outline" className="h-9 text-sm font-bold rounded-xl border-rose-200">
                Try Again
              </Button>
            </div>
          )}

          {status === "success" && tier === "tier1" && (
            <div className="p-6 bg-emerald-50 rounded-2xl border border-emerald-100 text-center mt-12">
              <div className="w-12 h-12 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-4">
                <ShieldCheck className="w-6 h-6" />
              </div>
              <h4 className="font-black text-emerald-900 mb-2">Strong Institutional Signal</h4>
              <p className="text-sm text-emerald-700 font-medium leading-relaxed">
                Your college ({institution}) is well-recognized by ATS filters. No structural equalization needed.
              </p>
            </div>
          )}

          {status === "success" && (tier === "tier2" || tier === "tier3") && !suggestion && (
            <div className="p-6 bg-amber-50 rounded-2xl border border-amber-100 text-center mt-12">
              <AlertTriangle className="w-10 h-10 text-amber-500 mx-auto mb-3" />
              <h4 className="font-black text-amber-900 mb-2">AI Analysis Unavailable</h4>
              <p className="text-sm text-amber-700 font-medium">
                We detected {institution} but couldn't generate AI rewrites right now. Try again later.
              </p>
            </div>
          )}

          {status === "success" && (tier === "tier2" || tier === "tier3") && suggestion && (
            <div className="space-y-6">

              {/* Analysis Header */}
              <div className="p-5 bg-amber-50 rounded-2xl border border-amber-100">
                <div className="flex items-start gap-3 mb-3">
                  <AlertTriangle className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />
                  <div>
                    <h4 className="font-bold text-amber-900 text-sm">AI Detected: {institution}</h4>
                    <p className="text-xs font-medium text-amber-700 mt-1 leading-relaxed">
                      Many great engineers from non-IIT/NIT colleges miss opportunities due to unconscious bias. Let's reorder your signals.
                    </p>
                  </div>
                </div>
              </div>

              {/* Rationale & Scoring */}
              <div className="grid grid-cols-2 gap-4">
                <div className="p-4 bg-gray-50 rounded-xl border border-gray-100">
                  <div className="flex items-center gap-2 text-indigo-600 mb-2">
                    <TrendingUp className="w-4 h-4" />
                    <span className="text-xs font-black uppercase tracking-wider">Recruiter Attention</span>
                  </div>
                  <div className="text-2xl font-black text-gray-900">
                    +{suggestion?.attentionGain ?? 28}%
                  </div>
                  <p className="text-[10px] text-gray-500 font-medium mt-1">Estimated impact gain</p>
                </div>
                <div className="p-4 bg-gray-50 rounded-xl border border-gray-100">
                   <div className="flex items-center gap-2 text-rose-500 mb-2">
                    <Zap className="w-4 h-4" />
                    <span className="text-xs font-black uppercase tracking-wider">Signal Density</span>
                  </div>
                  <p className="text-[11px] text-gray-700 font-medium leading-tight">
                    {suggestion?.signalDensity || "40% space spent on low-signal content. Re-prioritizing projects."}
                  </p>
                </div>
              </div>

              <div className="p-4 bg-indigo-50/50 rounded-xl border border-indigo-100/50">
                <p className="text-xs text-indigo-800 font-medium leading-relaxed italic">
                  "{suggestion.rationale}"
                </p>
              </div>

              {/* Diffs */}
              <div className="space-y-4 pt-4 border-t border-gray-100">
                <h4 className="text-sm font-black text-gray-900 mb-4 uppercase tracking-widest">Recommended Optimizations</h4>

                {suggestion.summaryRewrite && (
                  <div className="border border-gray-200 rounded-xl overflow-hidden">
                    <div className="px-4 py-3 bg-gray-50 border-b border-gray-200 flex justify-between items-center">
                      <span className="text-xs font-bold text-gray-600 uppercase tracking-widest">Summary Focus</span>
                      <Button size="sm" onClick={() => applyField('summary')} disabled={applying.includes('summary')} className="h-7 text-xs bg-indigo-600 text-white rounded-lg">
                        {applying.includes('summary') ? "Applying..." : "Apply"}
                      </Button>
                    </div>
                    <div className="p-4 bg-white text-sm text-gray-700">
                      {suggestion.summaryRewrite}
                    </div>
                  </div>
                )}

                {suggestion.educationDeEmphasis && (
                  <div className="border border-gray-200 rounded-xl overflow-hidden">
                    <div className="px-4 py-3 bg-gray-50 border-b border-gray-200 flex justify-between items-center">
                      <span className="text-xs font-bold text-gray-600 uppercase tracking-widest">Education De-emphasis</span>
                      <Button size="sm" onClick={() => applyField('education')} disabled={applying.includes('education')} className="h-7 text-xs bg-indigo-600 text-white rounded-lg">
                        {applying.includes('education') ? "Applying..." : "Apply"}
                      </Button>
                    </div>
                    <div className="p-4 bg-white text-sm text-gray-700 flex gap-4 items-center">
                      <div className="flex-1 opacity-50 line-through text-xs">{institution}</div>
                      <ArrowRight className="w-4 h-4 text-gray-400 shrink-0" />
                      <div className="flex-1 font-medium text-indigo-700 bg-indigo-50 p-2 rounded-lg text-xs">{suggestion.educationDeEmphasis}</div>
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}

        </div>

        {/* Footer */}
        {(status === "success" && (tier === "tier2" || tier === "tier3") && suggestion) && (
          <div className="p-6 border-t border-gray-100 bg-white shrink-0">
            <Button onClick={applyAll} disabled={applying.length > 0} className="w-full h-12 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl shadow-lg shadow-indigo-200 mb-3">
              {applying.length > 0 ? "Applying Optimizations..." : "Apply All Optimizations"}
            </Button>
            <p className="text-[10px] text-center text-gray-400 font-medium">
              This optimization keeps all your information factually accurate. It changes emphasis, not content.
            </p>
          </div>
        )}

      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import styles from "./ContributionWizard.module.css";

// ─────────────────────────────────────────────────────────────────────────────
// ContributionWizard
// 5-step guided contribution flow for interview experiences, questions,
// salary data, and recruiter patterns.
// ─────────────────────────────────────────────────────────────────────────────

type ContributionType = "experience" | "question" | "salary" | "recruiter_pattern" | "correction";

interface WizardStep {
  id: number;
  label: string;
  description: string;
}

const STEPS: WizardStep[] = [
  { id: 1, label: "Company & Role", description: "Tell us where you interviewed" },
  { id: 2, label: "Type",           description: "What are you sharing?" },
  { id: 3, label: "Details",        description: "The actual intelligence" },
  { id: 4, label: "Verify",         description: "Optional: boost trust score" },
  { id: 5, label: "Submit",         description: "Review and submit" },
];

const TYPE_OPTIONS: { value: ContributionType; label: string; icon: string; description: string; points: number }[] = [
  { value: "experience",        label: "Interview Experience", icon: "📝", description: "Full round-by-round breakdown of your recent interview", points: 100 },
  { value: "question",          label: "Interview Question",   icon: "🧩", description: "A specific question you were asked in any round", points: 50 },
  { value: "salary",            label: "Salary / CTC",        icon: "💰", description: "Anonymized offer data: base, ESOPs, joining bonus", points: 75 },
  { value: "recruiter_pattern", label: "Recruiter Pattern",   icon: "🎯", description: "Response rate, ghosting, timeline from a specific recruiter", points: 60 },
  { value: "correction",        label: "Data Correction",     icon: "✏️",  description: "Fix incorrect information already on CareerOS", points: 30 },
];

const INDIA_COMPANIES_QUICK = [
  "Razorpay", "PhonePe", "Flipkart", "Swiggy", "Zomato",
  "Meesho", "Amazon India", "Groww", "CRED", "Microsoft India",
  "Google India", "Paytm", "Urban Company", "Zepto", "BrowserStack",
  "Freshworks", "Zoho", "InMobi", "Ola", "Unacademy",
];

const DIFFICULTY_OPTIONS = ["easy", "medium", "hard", "expert"];
const ROUND_TYPES = ["Online Assessment", "Machine Coding", "DSA / Problem Solving", "System Design", "Behavioral / HR", "Hiring Manager", "Bar Raiser", "Founders Round"];
const OUTCOMES = ["selected", "rejected", "waitlisted", "withdrew", "pending"];
const LEVELS = ["Fresher / SDE 1", "SDE 2 (2-5 yrs)", "SDE 3 / Senior", "Staff / Principal"];

interface FormState {
  // Step 1
  companyName: string;
  companyCustom: string;
  roleTitle: string;
  level: string;
  location: string;
  occurredAt: string;
  // Step 2
  type: ContributionType | "";
  // Step 3
  // — experience
  outcome: string;
  totalRounds: number;
  timelineDays: number;
  rounds: Array<{ type: string; difficulty: string; duration: number; notes: string }>;
  overallDifficulty: string;
  // — question
  questionText: string;
  questionType: string;
  questionDifficulty: string;
  questionRound: string;
  // — salary
  salaryBase: string;
  salaryTotal: string;
  salaryEsop: string;
  salaryBonus: string;
  salaryCurrency: string;
  // — recruiter
  recruiterName: string;
  recruiterResponseRate: string;
  recruiterDays: string;
  recruiterGhosted: boolean;
  recruiterNotes: string;
}

const DEFAULT_FORM: FormState = {
  companyName: "", companyCustom: "", roleTitle: "", level: "", location: "Bengaluru, India", occurredAt: "",
  type: "",
  outcome: "", totalRounds: 4, timelineDays: 0,
  rounds: [{ type: "Online Assessment", difficulty: "medium", duration: 60, notes: "" }],
  overallDifficulty: "medium",
  questionText: "", questionType: "dsa", questionDifficulty: "medium", questionRound: "Technical",
  salaryBase: "", salaryTotal: "", salaryEsop: "", salaryBonus: "", salaryCurrency: "INR",
  recruiterName: "", recruiterResponseRate: "50", recruiterDays: "7", recruiterGhosted: false, recruiterNotes: "",
};

interface ContributionWizardProps {
  onSuccess?: (contribution: { id: string; type: string; status: string; points: number }) => void;
  onClose?: () => void;
  initialCompany?: string;
}

export function ContributionWizard({ onSuccess, onClose, initialCompany }: ContributionWizardProps) {
  const [step, setStep] = useState(1);
  const [form, setForm] = useState<FormState>({ ...DEFAULT_FORM, companyName: initialCompany ?? "" });
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [verifyEmail, setVerifyEmail] = useState(false);

  const effectiveCompany = form.companyName === "__custom__" ? form.companyCustom : form.companyName;
  const selectedType = TYPE_OPTIONS.find((t) => t.value === form.type);
  const canProceed = stepValid(step, form, effectiveCompany);

  function update(patch: Partial<FormState>) {
    setForm((prev) => ({ ...prev, ...patch }));
  }

  function updateRound(index: number, patch: Partial<{ type: string; difficulty: string; duration: number; notes: string }>) {
    const rounds = [...form.rounds];
    rounds[index] = { ...rounds[index]!, ...patch };
    update({ rounds });
  }

  function addRound() {
    update({ rounds: [...form.rounds, { type: "Technical", difficulty: "medium", duration: 60, notes: "" }] });
  }

  function removeRound(index: number) {
    update({ rounds: form.rounds.filter((_, i) => i !== index) });
  }

  async function submit() {
    setSubmitting(true);
    setError(null);
    try {
      const payload = buildPayload(form, effectiveCompany);
      const res = await fetch("/api/v1/interview-intelligence/contributions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.error ?? "Submission failed. Please try again.");
      }
      const data = await res.json();
      onSuccess?.({
        id: data.data?.id,
        type: form.type,
        status: data.data?.status,
        points: selectedType?.points ?? 50,
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className={styles.wizard}>
      {/* Progress */}
      <div className={styles.progress}>
        {STEPS.map((s) => (
          <div
            key={s.id}
            className={`${styles.stepDot} ${step === s.id ? styles.stepActive : ""} ${step > s.id ? styles.stepDone : ""}`}
          >
            {step > s.id ? "✓" : s.id}
          </div>
        ))}
        <div className={styles.progressBar} style={{ width: `${((step - 1) / (STEPS.length - 1)) * 100}%` }} />
      </div>

      <div className={styles.stepHeader}>
        <h2 className={styles.stepTitle}>{STEPS[step - 1]?.label}</h2>
        <p className={styles.stepSubtitle}>{STEPS[step - 1]?.description}</p>
      </div>

      {/* Step content */}
      <div className={styles.stepContent}>

        {/* ── STEP 1: Company & Role ── */}
        {step === 1 && (
          <div className={styles.fields}>
            <label className={styles.label}>Company *</label>
            <div className={styles.quickPicks}>
              {INDIA_COMPANIES_QUICK.slice(0, 8).map((c) => (
                <button
                  key={c}
                  type="button"
                  className={`${styles.quickPick} ${form.companyName === c ? styles.quickPickActive : ""}`}
                  onClick={() => update({ companyName: c })}
                >
                  {c}
                </button>
              ))}
              <button
                type="button"
                className={`${styles.quickPick} ${form.companyName === "__custom__" ? styles.quickPickActive : ""}`}
                onClick={() => update({ companyName: "__custom__" })}
              >
                Other…
              </button>
            </div>
            {form.companyName === "__custom__" && (
              <input
                className={styles.input}
                placeholder="Company name"
                value={form.companyCustom}
                onChange={(e) => update({ companyCustom: e.target.value })}
              />
            )}

            <label className={styles.label}>Role / Position *</label>
            <input
              className={styles.input}
              placeholder="e.g. Software Development Engineer 2"
              value={form.roleTitle}
              onChange={(e) => update({ roleTitle: e.target.value })}
            />

            <label className={styles.label}>Level</label>
            <select className={styles.select} value={form.level} onChange={(e) => update({ level: e.target.value })}>
              <option value="">Select level</option>
              {LEVELS.map((l) => <option key={l} value={l}>{l}</option>)}
            </select>

            <label className={styles.label}>Interview date (approx.)</label>
            <input
              type="month"
              className={styles.input}
              value={form.occurredAt}
              onChange={(e) => update({ occurredAt: e.target.value })}
            />
          </div>
        )}

        {/* ── STEP 2: Type ── */}
        {step === 2 && (
          <div className={styles.typeGrid}>
            {TYPE_OPTIONS.map((t) => (
              <button
                key={t.value}
                type="button"
                className={`${styles.typeCard} ${form.type === t.value ? styles.typeCardActive : ""}`}
                onClick={() => update({ type: t.value })}
              >
                <span className={styles.typeIcon}>{t.icon}</span>
                <div>
                  <div className={styles.typeLabel}>{t.label}</div>
                  <div className={styles.typeDesc}>{t.description}</div>
                </div>
                <div className={styles.typePoints}>+{t.points} pts</div>
              </button>
            ))}
          </div>
        )}

        {/* ── STEP 3: Details ── */}
        {step === 3 && form.type === "experience" && (
          <div className={styles.fields}>
            <label className={styles.label}>Outcome *</label>
            <div className={styles.quickPicks}>
              {OUTCOMES.map((o) => (
                <button key={o} type="button"
                  className={`${styles.quickPick} ${form.outcome === o ? styles.quickPickActive : ""}`}
                  onClick={() => update({ outcome: o })}
                >
                  {o.charAt(0).toUpperCase() + o.slice(1)}
                </button>
              ))}
            </div>

            <label className={styles.label}>Overall difficulty</label>
            <div className={styles.quickPicks}>
              {DIFFICULTY_OPTIONS.map((d) => (
                <button key={d} type="button"
                  className={`${styles.quickPick} ${form.overallDifficulty === d ? styles.quickPickActive : ""}`}
                  onClick={() => update({ overallDifficulty: d })}
                >
                  {d.charAt(0).toUpperCase() + d.slice(1)}
                </button>
              ))}
            </div>

            <label className={styles.label}>Timeline (days from apply to offer/reject)</label>
            <input type="number" className={styles.input} min={1} max={365}
              value={form.timelineDays || ""}
              placeholder="e.g. 21"
              onChange={(e) => update({ timelineDays: parseInt(e.target.value) || 0 })}
            />

            <label className={styles.label}>Rounds breakdown</label>
            {form.rounds.map((r, i) => (
              <div key={i} className={styles.roundRow}>
                <span className={styles.roundIndex}>R{i + 1}</span>
                <select className={styles.selectSm} value={r.type}
                  onChange={(e) => updateRound(i, { type: e.target.value })}>
                  {ROUND_TYPES.map((rt) => <option key={rt} value={rt}>{rt}</option>)}
                </select>
                <select className={styles.selectSm} value={r.difficulty}
                  onChange={(e) => updateRound(i, { difficulty: e.target.value })}>
                  {DIFFICULTY_OPTIONS.map((d) => <option key={d} value={d}>{d}</option>)}
                </select>
                <input type="number" className={styles.inputSm} placeholder="min" min={15} max={360}
                  value={r.duration || ""}
                  onChange={(e) => updateRound(i, { duration: parseInt(e.target.value) || 60 })}
                />
                <button type="button" className={styles.removeRound} onClick={() => removeRound(i)}>×</button>
              </div>
            ))}
            <button type="button" className={styles.addRoundBtn} onClick={addRound}>
              + Add round
            </button>
          </div>
        )}

        {step === 3 && form.type === "question" && (
          <div className={styles.fields}>
            <label className={styles.label}>Question text *</label>
            <textarea
              className={styles.textarea}
              placeholder="Paste the exact question or describe it in detail. e.g. 'Design a distributed rate limiter for Razorpay's payment API handling 10M RPM.'"
              rows={4}
              value={form.questionText}
              onChange={(e) => update({ questionText: e.target.value })}
            />

            <label className={styles.label}>Question type</label>
            <div className={styles.quickPicks}>
              {["dsa", "system_design", "machine_coding", "behavioral", "lld", "aptitude"].map((qt) => (
                <button key={qt} type="button"
                  className={`${styles.quickPick} ${form.questionType === qt ? styles.quickPickActive : ""}`}
                  onClick={() => update({ questionType: qt })}
                >
                  {qt.replace("_", " ").toUpperCase()}
                </button>
              ))}
            </div>

            <label className={styles.label}>Difficulty</label>
            <div className={styles.quickPicks}>
              {DIFFICULTY_OPTIONS.map((d) => (
                <button key={d} type="button"
                  className={`${styles.quickPick} ${form.questionDifficulty === d ? styles.quickPickActive : ""}`}
                  onClick={() => update({ questionDifficulty: d })}
                >
                  {d.charAt(0).toUpperCase() + d.slice(1)}
                </button>
              ))}
            </div>

            <label className={styles.label}>Which round was this asked in?</label>
            <select className={styles.select} value={form.questionRound}
              onChange={(e) => update({ questionRound: e.target.value })}>
              {ROUND_TYPES.map((rt) => <option key={rt} value={rt}>{rt}</option>)}
            </select>
          </div>
        )}

        {step === 3 && form.type === "salary" && (
          <div className={styles.fields}>
            <div className={styles.salaryNote}>
              🔒 All salary data is fully anonymized. Only percentiles are displayed publicly.
            </div>
            <label className={styles.label}>Base salary (₹/year) *</label>
            <input className={styles.input} type="number" placeholder="e.g. 2400000"
              value={form.salaryBase} onChange={(e) => update({ salaryBase: e.target.value })} />

            <label className={styles.label}>Total CTC (₹/year) *</label>
            <input className={styles.input} type="number" placeholder="e.g. 3500000"
              value={form.salaryTotal} onChange={(e) => update({ salaryTotal: e.target.value })} />

            <label className={styles.label}>ESOP / RSU value (₹ over 4 years)</label>
            <input className={styles.input} type="number" placeholder="e.g. 5000000"
              value={form.salaryEsop} onChange={(e) => update({ salaryEsop: e.target.value })} />

            <label className={styles.label}>Joining bonus (₹)</label>
            <input className={styles.input} type="number" placeholder="e.g. 200000"
              value={form.salaryBonus} onChange={(e) => update({ salaryBonus: e.target.value })} />
          </div>
        )}

        {step === 3 && form.type === "recruiter_pattern" && (
          <div className={styles.fields}>
            <label className={styles.label}>Recruiter name (optional, not displayed publicly)</label>
            <input className={styles.input} placeholder="First name only, e.g. Priya"
              value={form.recruiterName} onChange={(e) => update({ recruiterName: e.target.value })} />

            <label className={styles.label}>Response rate (estimate)</label>
            <input className={styles.input} type="range" min={0} max={100}
              value={form.recruiterResponseRate}
              onChange={(e) => update({ recruiterResponseRate: e.target.value })} />
            <span className={styles.rangeLabel}>{form.recruiterResponseRate}%</span>

            <label className={styles.label}>Avg days to respond</label>
            <input className={styles.input} type="number" min={0} max={90} placeholder="e.g. 5"
              value={form.recruiterDays} onChange={(e) => update({ recruiterDays: e.target.value })} />

            <label className={styles.label}>
              <input type="checkbox" checked={form.recruiterGhosted}
                onChange={(e) => update({ recruiterGhosted: e.target.checked })}
              />{" "}
              Ghosted after final round
            </label>

            <label className={styles.label}>Notes (optional)</label>
            <textarea className={styles.textarea} rows={3} placeholder="Any other observations about the recruiter / process"
              value={form.recruiterNotes} onChange={(e) => update({ recruiterNotes: e.target.value })} />
          </div>
        )}

        {/* ── STEP 4: Verify ── */}
        {step === 4 && (
          <div className={styles.fields}>
            <div className={styles.verifyHero}>
              <span className={styles.verifyEmoji}>🔐</span>
              <h3 className={styles.verifyTitle}>Boost your contribution's trust score</h3>
              <p className={styles.verifySubtitle}>
                Verified contributions are weighted 2× in our ranking system and receive a gold badge.
                This is optional — your contribution will still be accepted without verification.
              </p>
            </div>

            <div className={styles.verifyOptions}>
              <button
                type="button"
                className={`${styles.verifyOption} ${verifyEmail ? styles.verifyOptionActive : ""}`}
                onClick={() => setVerifyEmail(!verifyEmail)}
              >
                <span className={styles.verifyOptionIcon}>📧</span>
                <div>
                  <div className={styles.verifyOptionLabel}>Verify via company email</div>
                  <div className={styles.verifyOptionDesc}>
                    If you have access to your @{effectiveCompany.toLowerCase().replace(/[^a-z]/g, "")}.com email,
                    we can instantly verify your insider status.
                  </div>
                </div>
                <span className={styles.verifyBadge}>+Tier 1</span>
              </button>

              <div className={`${styles.verifyOption} ${styles.verifyOptionDisabled}`}>
                <span className={styles.verifyOptionIcon}>📄</span>
                <div>
                  <div className={styles.verifyOptionLabel}>Verify via offer letter</div>
                  <div className={styles.verifyOptionDesc}>
                    Upload a hash of your offer letter (document never stored). Coming soon.
                  </div>
                </div>
                <span className={styles.verifyBadgeSoon}>Soon</span>
              </div>
            </div>

            <div className={styles.skipNote}>
              Skipping verification is fine — community voting will still validate your contribution over time.
            </div>
          </div>
        )}

        {/* ── STEP 5: Review & Submit ── */}
        {step === 5 && (
          <div className={styles.review}>
            <div className={styles.reviewCard}>
              <div className={styles.reviewRow}>
                <span className={styles.reviewLabel}>Company</span>
                <span className={styles.reviewValue}>{effectiveCompany}</span>
              </div>
              <div className={styles.reviewRow}>
                <span className={styles.reviewLabel}>Role</span>
                <span className={styles.reviewValue}>{form.roleTitle}</span>
              </div>
              <div className={styles.reviewRow}>
                <span className={styles.reviewLabel}>Type</span>
                <span className={styles.reviewValue}>{selectedType?.icon} {selectedType?.label}</span>
              </div>
              <div className={styles.reviewRow}>
                <span className={styles.reviewLabel}>Points earned</span>
                <span className={styles.reviewPoints}>+{selectedType?.points ?? 50} pts</span>
              </div>
            </div>

            <div className={styles.communityNote}>
              <span>🤝</span>
              <p>
                By submitting, you agree to CareerOS's community contribution guidelines.
                Your data helps thousands of India engineers navigate hiring better.
              </p>
            </div>

            {error && <div className={styles.error}>{error}</div>}
          </div>
        )}
      </div>

      {/* Navigation */}
      <div className={styles.nav}>
        {step > 1 && (
          <button type="button" className={styles.btnBack} onClick={() => setStep((s) => s - 1)}>
            ← Back
          </button>
        )}
        <div className={styles.navRight}>
          {onClose && (
            <button type="button" className={styles.btnCancel} onClick={onClose}>
              Cancel
            </button>
          )}
          {step < STEPS.length ? (
            <button
              type="button"
              className={styles.btnNext}
              disabled={!canProceed}
              onClick={() => setStep((s) => s + 1)}
            >
              Continue →
            </button>
          ) : (
            <button
              type="button"
              className={styles.btnSubmit}
              disabled={submitting}
              onClick={submit}
            >
              {submitting ? "Submitting…" : "🚀 Submit Contribution"}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────────────────────

function stepValid(step: number, form: FormState, company: string): boolean {
  if (step === 1) return company.trim().length > 0 && form.roleTitle.trim().length > 0;
  if (step === 2) return form.type !== "";
  if (step === 3) {
    if (form.type === "experience") return form.outcome !== "";
    if (form.type === "question") return form.questionText.trim().length >= 20;
    if (form.type === "salary") return form.salaryBase !== "" && form.salaryTotal !== "";
    return true;
  }
  return true;
}

function buildPayload(form: FormState, company: string) {
  const base = {
    type: form.type,
    companyName: company,
    roleTitle: form.roleTitle || undefined,
  };

  if (form.type === "experience") {
    return {
      ...base,
      payload: {
        outcome: form.outcome,
        overallDifficulty: form.overallDifficulty,
        timelineDays: form.timelineDays || undefined,
        level: form.level || undefined,
        occurredAt: form.occurredAt || undefined,
        rounds: form.rounds,
      },
    };
  }

  if (form.type === "question") {
    return {
      ...base,
      payload: {
        question: form.questionText,
        type: form.questionType,
        difficulty: form.questionDifficulty,
        round: form.questionRound,
      },
    };
  }

  if (form.type === "salary") {
    return {
      ...base,
      payload: {
        baseAnnual: parseInt(form.salaryBase) || undefined,
        totalCtc: parseInt(form.salaryTotal) || undefined,
        esop4yr: form.salaryEsop ? parseInt(form.salaryEsop) : undefined,
        joiningBonus: form.salaryBonus ? parseInt(form.salaryBonus) : undefined,
        currency: "INR",
        level: form.level || undefined,
        occurredAt: form.occurredAt || undefined,
      },
    };
  }

  if (form.type === "recruiter_pattern") {
    return {
      ...base,
      payload: {
        recruiterName: form.recruiterName || undefined,
        responseRatePct: parseInt(form.recruiterResponseRate),
        avgResponseDays: parseInt(form.recruiterDays) || undefined,
        ghostedAfterFinalRound: form.recruiterGhosted,
        notes: form.recruiterNotes || undefined,
      },
    };
  }

  return { ...base, payload: {} };
}

"use client";

import { useState } from "react";
import { Sparkles, MessageSquare, Send, CheckCircle2 } from "lucide-react";
import { Modal } from "@/components/ui/modal";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";

interface InterviewContributionModalProps {
  isOpen: boolean;
  onClose: () => void;
  defaultCompany?: string;
  defaultRole?: string;
  onSuccess?: () => void;
}

export function InterviewContributionModal({
  isOpen,
  onClose,
  defaultCompany = "",
  defaultRole = "",
  onSuccess,
}: InterviewContributionModalProps) {
  const [company, setCompany] = useState(defaultCompany);
  const [role, setRole] = useState(defaultRole);
  const [round, setRound] = useState("dsa");
  const [question, setQuestion] = useState("");
  const [difficulty, setDifficulty] = useState("medium");
  const [outcome, setOutcome] = useState("pending");
  const [timeline, setTimeline] = useState("");
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!company.trim() || !question.trim()) {
      setError("Please fill in the company name and the questions asked.");
      return;
    }
    setLoading(true);
    setError(null);

    try {
      const res = await fetch("/api/v1/interview-intelligence/contributions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          type: "question",
          companyName: company.trim(),
          roleTitle: role.trim() || undefined,
          payload: {
            question: question.trim(),
            round,
            difficulty,
            outcome,
            timeline: timeline.trim() || "Recent",
          },
        }),
      });

      if (!res.ok) {
        throw new Error("Failed to submit contribution. Please try again.");
      }

      setSubmitted(true);
      if (onSuccess) onSuccess();
    } catch (err: any) {
      setError(err.message || "An unexpected error occurred.");
    } finally {
      setLoading(false);
    }
  };

  const handleClose = () => {
    setSubmitted(false);
    setQuestion("");
    onClose();
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={handleClose}
      title={submitted ? "Contribution Successful" : "Help Future Candidates Prepare"}
      description={
        submitted
          ? "Your submission makes CareerOS the living memory of India's tech ecosystem."
          : "Share your interview rounds. Help next-gen engineers bypass placement and recruitment tier bias."
      }
      className="max-w-xl"
    >
      {submitted ? (
        <div className="flex flex-col items-center justify-center p-6 text-center gap-4">
          <div className="flex h-14 w-14 items-center justify-center rounded-full bg-emerald-500/10 text-emerald-500 animate-bounce">
            <CheckCircle2 className="h-8 w-8" />
          </div>
          <div className="grid gap-2">
            <h3 className="text-lg font-bold text-foreground">Premium Intel Unlocked!</h3>
            <p className="text-sm text-muted-foreground leading-relaxed">
              Reciprocity Active: We have unlocked detailed questions, prep plans, and solutions for all companies.
            </p>
          </div>
          <Button onClick={handleClose} className="mt-4 w-full">
            Back to InterviewAI
          </Button>
        </div>
      ) : (
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="grid gap-1.5">
              <label htmlFor="company" className="text-xs font-semibold text-foreground uppercase tracking-wider">
                Company Name *
              </label>
              <Input
                id="company"
                value={company}
                onChange={(e) => setCompany(e.target.value)}
                placeholder="e.g. Swiggy, PhonePe"
                required
              />
            </div>
            <div className="grid gap-1.5">
              <label htmlFor="role" className="text-xs font-semibold text-foreground uppercase tracking-wider">
                Role / Title
              </label>
              <Input
                id="role"
                value={role}
                onChange={(e) => setRole(e.target.value)}
                placeholder="e.g. SDE-2 Frontend"
              />
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4">
            <div className="grid gap-1.5">
              <label htmlFor="round" className="text-xs font-semibold text-foreground uppercase tracking-wider">
                Round Type
              </label>
              <select
                id="round"
                value={round}
                onChange={(e) => setRound(e.target.value)}
                className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-ring"
              >
                <option value="online_assessment">OA / Test</option>
                <option value="dsa">DSA Coding</option>
                <option value="machine_coding">Machine Coding</option>
                <option value="system_design">System Design (HLD)</option>
                <option value="lld">Low-Level Design (LLD)</option>
                <option value="behavioral">Behavioral</option>
                <option value="hiring_manager">Hiring Manager</option>
                <option value="hr">HR</option>
              </select>
            </div>
            <div className="grid gap-1.5">
              <label htmlFor="difficulty" className="text-xs font-semibold text-foreground uppercase tracking-wider">
                Difficulty
              </label>
              <select
                id="difficulty"
                value={difficulty}
                onChange={(e) => setDifficulty(e.target.value)}
                className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-ring"
              >
                <option value="easy">Easy</option>
                <option value="medium">Medium</option>
                <option value="hard">Hard</option>
              </select>
            </div>
            <div className="grid gap-1.5">
              <label htmlFor="outcome" className="text-xs font-semibold text-foreground uppercase tracking-wider">
                Outcome
              </label>
              <select
                id="outcome"
                value={outcome}
                onChange={(e) => setOutcome(e.target.value)}
                className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm text-foreground focus:outline-none focus:ring-2 focus:ring-ring"
              >
                <option value="pending">Pending</option>
                <option value="offer">Offer Received</option>
                <option value="rejected">No Offer</option>
              </select>
            </div>
          </div>

          <div className="grid gap-1.5">
            <label htmlFor="timeline" className="text-xs font-semibold text-foreground uppercase tracking-wider">
              Timeline (When did it happen?)
            </label>
            <Input
              id="timeline"
              value={timeline}
              onChange={(e) => setTimeline(e.target.value)}
              placeholder="e.g. May 2026, Q2 2026"
            />
          </div>

          <div className="grid gap-1.5">
            <label htmlFor="question" className="text-xs font-semibold text-foreground uppercase tracking-wider">
              Questions / Problems Asked *
            </label>
            <Textarea
              id="question"
              value={question}
              onChange={(e) => setQuestion(e.target.value)}
              placeholder="e.g. Construct an in-memory PubSub system with delivery guarantees, or: implement an optimized dynamic programming solution for the coin change problem."
              className="min-h-[120px]"
              required
            />
            <p className="text-[10px] text-muted-foreground leading-normal mt-1">
              Please avoid including highly specific project names or proprietary secrets to protect candidate confidentiality.
            </p>
          </div>

          {error && <p className="text-xs text-destructive">{error}</p>}

          <div className="flex justify-end gap-3 pt-3 border-t border-border">
            <Button type="button" variant="ghost" onClick={handleClose}>
              Cancel
            </Button>
            <Button type="submit" isLoading={loading} className="gap-2">
              <Send className="h-4 w-4" />
              Submit and Unlock Intel
            </Button>
          </div>
        </form>
      )}
    </Modal>
  );
}

"use client";

import React from "react";
import styles from "./RoundIntelligenceCard.module.css";

// ─────────────────────────────────────────────────────────────────────────────
// RoundIntelligenceCard
// Displays per-round data: type, duration, difficulty, top topics, pass rate.
// Consumes data from getCompanyTerminal() → experiences → rounds
// ─────────────────────────────────────────────────────────────────────────────

export interface RoundData {
  roundNumber: number;
  type: string;          // "Online Assessment" | "Machine Coding" | "DSA" | "System Design" | "HR"
  title: string;
  durationMinutes?: number | null;
  difficulty: string;    // "easy" | "medium" | "hard" | "expert" | "unknown"
  topics: string[];      // most-asked topics in this round
  passRate?: number | null; // 0-1, from selection patterns
  tipCount: number;       // number of experience reports for this round
  signals?: string[];     // key signals reported by candidates
}

interface RoundIntelligenceCardProps {
  round: RoundData;
  index: number;
  companyName: string;
}

const DIFFICULTY_LABEL: Record<string, { label: string; color: string }> = {
  easy:    { label: "Easy",    color: "#22c55e" },
  medium:  { label: "Medium",  color: "#f59e0b" },
  hard:    { label: "Hard",    color: "#ef4444" },
  expert:  { label: "Expert",  color: "#9333ea" },
  unknown: { label: "Varies",  color: "#6b7280" },
};

const ROUND_ICON: Record<string, string> = {
  "online assessment": "📝",
  "machine coding":    "💻",
  "dsa":               "🔢",
  "technical":         "⚙️",
  "system design":     "🏗️",
  "hld":               "🏗️",
  "lld":               "🧩",
  "behavioral":        "🧠",
  "hr":                "🤝",
  "hiring manager":    "👔",
  "bar raiser":        "⚖️",
  "founders":          "🚀",
};

function getRoundIcon(type: string): string {
  const normalized = type.toLowerCase();
  for (const [key, icon] of Object.entries(ROUND_ICON)) {
    if (normalized.includes(key)) return icon;
  }
  return "📋";
}

export function RoundIntelligenceCard({ round, index, companyName }: RoundIntelligenceCardProps) {
  const difficultyInfo = DIFFICULTY_LABEL[round.difficulty] ?? DIFFICULTY_LABEL["unknown"]!;
  const icon = getRoundIcon(round.type);
  const passPercent = round.passRate != null ? Math.round(round.passRate * 100) : null;

  return (
    <div className={styles.card} style={{ animationDelay: `${index * 80}ms` }}>
      {/* Round number badge */}
      <div className={styles.roundBadge}>
        <span className={styles.roundNumber}>R{round.roundNumber}</span>
      </div>

      {/* Header */}
      <div className={styles.header}>
        <span className={styles.icon}>{icon}</span>
        <div className={styles.headerText}>
          <h3 className={styles.title}>{round.title}</h3>
          <span className={styles.type}>{round.type}</span>
        </div>
      </div>

      {/* Stats row */}
      <div className={styles.statsRow}>
        {round.durationMinutes && (
          <div className={styles.stat}>
            <span className={styles.statIcon}>⏱</span>
            <span className={styles.statValue}>{round.durationMinutes}m</span>
          </div>
        )}
        <div className={styles.stat}>
          <span
            className={styles.difficultyDot}
            style={{ background: difficultyInfo.color }}
          />
          <span className={styles.statValue} style={{ color: difficultyInfo.color }}>
            {difficultyInfo.label}
          </span>
        </div>
        {passPercent !== null && (
          <div className={styles.stat}>
            <span className={styles.statIcon}>✅</span>
            <span className={styles.statValue}>{passPercent}% pass</span>
          </div>
        )}
        {round.tipCount > 0 && (
          <div className={styles.stat}>
            <span className={styles.statIcon}>👥</span>
            <span className={styles.statValue}>{round.tipCount} reports</span>
          </div>
        )}
      </div>

      {/* Top topics */}
      {round.topics.length > 0 && (
        <div className={styles.topics}>
          {round.topics.slice(0, 5).map((topic) => (
            <span key={topic} className={styles.topicTag}>
              {topic}
            </span>
          ))}
        </div>
      )}

      {/* Key signals */}
      {round.signals && round.signals.length > 0 && (
        <div className={styles.signals}>
          {round.signals.slice(0, 3).map((signal, i) => (
            <div key={i} className={styles.signal}>
              <span className={styles.signalDot}>›</span>
              <span>{signal}</span>
            </div>
          ))}
        </div>
      )}

      {/* India-specific context pill */}
      <div className={styles.indiaPill}>
        🇮🇳 India-verified intel
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// RoundIntelligenceList
// Wraps multiple cards with section header
// ─────────────────────────────────────────────────────────────────────────────

interface RoundIntelligenceListProps {
  rounds: RoundData[];
  companyName: string;
}

export function RoundIntelligenceList({ rounds, companyName }: RoundIntelligenceListProps) {
  if (rounds.length === 0) return null;

  return (
    <section className={styles.section}>
      <div className={styles.sectionHeader}>
        <h2 className={styles.sectionTitle}>
          🎯 Round-by-Round Intelligence
        </h2>
        <p className={styles.sectionSubtitle}>
          Based on verified candidate reports for {companyName} India
        </p>
      </div>
      <div className={styles.grid}>
        {rounds.map((round, i) => (
          <RoundIntelligenceCard
            key={round.roundNumber}
            round={round}
            index={i}
            companyName={companyName}
          />
        ))}
      </div>
    </section>
  );
}

"use client";

import { useState, useCallback, useMemo } from "react";
import { Plus, Trash2 } from "lucide-react";
import { AnalyzeButton } from "./AnalyzeButton";

interface JDInputProps {
  onAnalyze: (jds: string[]) => Promise<void>;
  step: "idle" | "parsing" | "analyzing" | "computing" | "success";
}

// Lightweight heuristic parser for live preview
const COMMON_SKILLS = [
  "React", "Node.js", "Python", "AWS", "TypeScript", "JavaScript",
  "Docker", "Kubernetes", "Next.js", "SQL", "MongoDB", "PostgreSQL",
  "GraphQL", "REST API", "CI/CD", "Git", "Azure", "GCP", "Vue", "Angular",
  "System Design", "Agile", "Java", "C++", "Go"
];

function extractPreviewSkills(text: string): string[] {
  if (!text) return [];
  const lower = text.toLowerCase();
  return COMMON_SKILLS.filter(s => lower.includes(s.toLowerCase()));
}

export function JDInput({ onAnalyze, step }: JDInputProps) {
  const [jds, setJds] = useState<string[]>(["", "", ""]);

  const update = (i: number, val: string) => {
    setJds((prev) => prev.map((v, idx) => (idx === i ? val : v)));
  };

  const addSlot = () => {
    if (jds.length >= 10) return;
    setJds((prev) => [...prev, ""]);
  };

  const removeSlot = (i: number) => {
    if (jds.length <= 1) return;
    setJds((prev) => prev.filter((_, idx) => idx !== i));
  };

  const handleSubmit = useCallback(() => {
    const filled = jds.map((j) => j.trim()).filter(Boolean);
    if (filled.length === 0) return;
    onAnalyze(filled);
  }, [jds, onAnalyze]);

  const filledCount = jds.filter((j) => j.trim()).length;
  const isValid = filledCount >= 3;

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-lg font-bold text-gray-900">Job Descriptions</h2>
          <p className="text-sm text-gray-500 mt-0.5">
            Paste 3–10 JDs to build a real market picture — more = better accuracy.
          </p>
        </div>
        <button
          onClick={addSlot}
          disabled={jds.length >= 10}
          className="flex items-center gap-1.5 rounded-xl border border-dashed border-indigo-300 bg-indigo-50/60 px-4 py-2 text-sm font-semibold text-indigo-600 hover:bg-indigo-50 transition-colors disabled:opacity-40"
        >
          <Plus className="h-4 w-4" /> Add JD
        </button>
      </div>

      {/* Textarea Grid */}
      <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
        {jds.map((jd, i) => (
          <div key={i} className="relative group">
            <textarea
              value={jd}
              onChange={(e) => update(i, e.target.value)}
              placeholder={`Job Description ${i + 1}\n\nPaste the full JD here...`}
              rows={9}
              className="w-full resize-none rounded-2xl border border-gray-200 bg-white px-4 py-3.5 text-sm text-gray-700 placeholder:text-gray-400 focus:outline-none focus:ring-2 focus:ring-indigo-400 shadow-sm transition-shadow"
            />
            {jds.length > 1 && (
              <button
                onClick={() => removeSlot(i)}
                className="absolute top-2.5 right-2.5 p-1.5 rounded-lg text-gray-300 hover:text-red-400 hover:bg-red-50 opacity-0 group-hover:opacity-100 transition-all"
              >
                <Trash2 className="h-3.5 w-3.5" />
              </button>
            )}
            {/* Quick Preview extracted skills */}
            {jd.trim() && extractPreviewSkills(jd).length > 0 && (
              <div className="absolute bottom-3 left-4 text-xs font-medium text-indigo-600 bg-indigo-50 px-2 py-1 rounded-md">
                Detected: {extractPreviewSkills(jd).slice(0, 3).join(", ")}
                {extractPreviewSkills(jd).length > 3 && "..."}
              </div>
            )}

            {/* Character count */}
            {jd.trim() && (
              <span className="absolute bottom-4 right-4 text-[10px] text-gray-300">
                {jd.length} chars
              </span>
            )}
          </div>
        ))}
      </div>

      {/* CTA */}
      <div className="flex items-center justify-between pt-2">
        <p className={`text-sm ${isValid ? "text-emerald-600 font-medium" : "text-amber-500 font-medium"}`}>
          {isValid 
            ? `${filledCount} of ${jds.length} filled — ready to analyze` 
            : `Add at least ${3 - filledCount} more job(s) for accurate insights`}
        </p>
        <AnalyzeButton 
          onClick={handleSubmit} 
          disabled={!isValid} 
          step={step} 
        />
      </div>
    </div>
  );
}

