              <h4 className="text-sm font-medium text-primary">Reply Detected</h4>
              <p className="text-xs text-muted-foreground mt-0.5">{localCampaign.lastReplyAt ? format(new Date(localCampaign.lastReplyAt), "MMM d, yyyy h:mm a") : "Sequence stopped"}</p>
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

"use client";

import React, { useEffect, useRef, useCallback, useState } from "react";
import type { CareerGraph, GraphNode, GraphEdge, GraphNodeKind } from "@/lib/career-graph/types";

const NODE_COLORS: Record<GraphNodeKind, string> = {
  SKILL: "#6366f1", EXPERIENCE: "#10b981", PROJECT: "#f59e0b",
  CERTIFICATION: "#8b5cf6", EDUCATION: "#3b82f6", APPLICATION: "#ef4444",
  INTERVIEW: "#ec4899", COMPANY: "#14b8a6", RECRUITER: "#f97316",
  CAREER_GOAL: "#84cc16", SALARY_TARGET: "#22d3ee", JOB_MATCH: "#a78bfa",
  SKILL_GAP: "#fb923c", OFFER: "#fbbf24",
};

const NODE_RADIUS: Record<GraphNodeKind, number> = {
  SKILL: 13, EXPERIENCE: 22, PROJECT: 17, CERTIFICATION: 15, EDUCATION: 19,
  APPLICATION: 19, INTERVIEW: 17, COMPANY: 23, RECRUITER: 15,
  CAREER_GOAL: 20, SALARY_TARGET: 17, JOB_MATCH: 15, SKILL_GAP: 15, OFFER: 21,
};

interface SimNode extends GraphNode { x: number; y: number; vx: number; vy: number; }
interface SimEdge extends GraphEdge { source: SimNode; target: SimNode; }

function runSim(nodes: SimNode[], edges: SimEdge[], W: number, H: number) {
  const cx = W / 2, cy = H / 2;
  const ITER = 150, REP = 5000, SL = 130, SK = 0.035, DAMP = 0.82, G = 0.025;
  for (let i = 0; i < ITER; i++) {
    for (let a = 0; a < nodes.length; a++) {
      for (let b = a + 1; b < nodes.length; b++) {
        const na = nodes[a]!, nb = nodes[b]!;
        const dx = nb.x - na.x, dy = nb.y - na.y;
        const d = Math.sqrt(dx * dx + dy * dy) || 1;
        const f = REP / (d * d);
        na.vx -= (dx / d) * f; na.vy -= (dy / d) * f;
        nb.vx += (dx / d) * f; nb.vy += (dy / d) * f;
      }
    }
    for (const e of edges) {
      const dx = e.target.x - e.source.x, dy = e.target.y - e.source.y;
      const d = Math.sqrt(dx * dx + dy * dy) || 1;
      const f = (d - SL) * SK * e.weight;
      e.source.vx += (dx / d) * f; e.source.vy += (dy / d) * f;
      e.target.vx -= (dx / d) * f; e.target.vy -= (dy / d) * f;
    }
    for (const n of nodes) {
      n.vx += (cx - n.x) * G; n.vy += (cy - n.y) * G;
      n.vx *= DAMP; n.vy *= DAMP;
      n.x += n.vx; n.y += n.vy;
      n.x = Math.max(50, Math.min(W - 50, n.x));
      n.y = Math.max(50, Math.min(H - 50, n.y));
    }
  }
}

interface Props {
  graph: CareerGraph;
  onNodeClick?: (node: GraphNode) => void;
  width?: number;
  height?: number;
  filterKinds?: GraphNodeKind[];
}

export function CareerGraphCanvas({ graph, onNodeClick, width = 1080, height = 580, filterKinds }: Props) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const simNodesRef = useRef<SimNode[]>([]);
  const simEdgesRef = useRef<SimEdge[]>([]);
  const hoveredRef = useRef<SimNode | null>(null);
  const dragRef = useRef<SimNode | null>(null);
  const animRef = useRef<number | null>(null);
  const offsetRef = useRef({ x: 0, y: 0 });
  const scaleRef = useRef(1);
  const isPanRef = useRef(false);
  const panStartRef = useRef({ x: 0, y: 0, ox: 0, oy: 0 });
  const tickRef = useRef(0);

  const build = useCallback(() => {
    const filtered = filterKinds ? graph.nodes.filter(n => filterKinds.includes(n.kind)) : graph.nodes;
    const nodeMap = new Map<string, SimNode>();
    const cx = width / 2, cy = height / 2;
    const simNodes: SimNode[] = filtered.map(n => {
      const a = Math.random() * 2 * Math.PI, r = 60 + Math.random() * 220;
      const sn: SimNode = { ...n, x: cx + Math.cos(a) * r, y: cy + Math.sin(a) * r, vx: 0, vy: 0 };
      nodeMap.set(n.id, sn);
      return sn;
    });
    const simEdges: SimEdge[] = graph.edges
      .map(e => { const s = nodeMap.get(e.sourceNodeId), t = nodeMap.get(e.targetNodeId); return s && t ? { ...e, source: s, target: t } as SimEdge : null; })
      .filter((e): e is SimEdge => e !== null);
    runSim(simNodes, simEdges, width, height);
    simNodesRef.current = simNodes;
    simEdgesRef.current = simEdges;
  }, [graph, filterKinds, width, height]);

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const ox = offsetRef.current.x, oy = offsetRef.current.y, sc = scaleRef.current;
    tickRef.current += 0.02;
    const t = tickRef.current;

    ctx.clearRect(0, 0, width, height);
    ctx.fillStyle = "#050508";
    ctx.fillRect(0, 0, width, height);

    // Grid
    ctx.strokeStyle = "rgba(255,255,255,0.025)";
    ctx.lineWidth = 0.5;
    const gridSize = 40 * sc;
    for (let x = (ox % gridSize); x < width; x += gridSize) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, height); ctx.stroke(); }
    for (let y = (oy % gridSize); y < height; y += gridSize) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(width, y); ctx.stroke(); }

    ctx.save();
    ctx.translate(ox, oy);
    ctx.scale(sc, sc);

    // Animated edges
    for (const edge of simEdgesRef.current) {
      const alpha = 0.06 + edge.weight * 0.18;
      const color = NODE_COLORS[edge.source.kind] ?? "#6366f1";

      // Animated dash
      ctx.setLineDash([6, 8]);
      ctx.lineDashOffset = -t * 8;
      ctx.beginPath();
      ctx.moveTo(edge.source.x, edge.source.y);
      ctx.lineTo(edge.target.x, edge.target.y);
      ctx.strokeStyle = `${color}${Math.round(alpha * 255).toString(16).padStart(2, "0")}`;
      ctx.lineWidth = (0.8 + edge.weight * 1.4) / sc;
      ctx.stroke();
      ctx.setLineDash([]);

      // Arrow head
      const dx = edge.target.x - edge.source.x, dy = edge.target.y - edge.source.y;
      const len = Math.sqrt(dx * dx + dy * dy) || 1;
      const ux = dx / len, uy = dy / len;
      const tr = (NODE_RADIUS[edge.target.kind] ?? 14) * (0.7 + edge.target.weight * 0.5);
      const ax = edge.target.x - ux * (tr + 4), ay = edge.target.y - uy * (tr + 4);
      const perpX = -uy * 4, perpY = ux * 4;
      ctx.beginPath();
      ctx.moveTo(ax, ay);
      ctx.lineTo(ax - ux * 8 + perpX, ay - uy * 8 + perpY);
      ctx.lineTo(ax - ux * 8 - perpX, ay - uy * 8 - perpY);
      ctx.closePath();
      ctx.fillStyle = `${color}88`;
      ctx.fill();
    }

    // Nodes
    for (const node of simNodesRef.current) {
      const color = NODE_COLORS[node.kind] ?? "#6b7280";
      const r = (NODE_RADIUS[node.kind] ?? 13) * (0.7 + node.weight * 0.55);
      const isHovered = hoveredRef.current?.id === node.id;
      const isDragged = dragRef.current?.id === node.id;

      // Pulse ring for skill gaps
      if (node.kind === "SKILL_GAP") {
        const pulse = 1 + 0.3 * Math.sin(t * 2 + node.x);
        ctx.beginPath(); ctx.arc(node.x, node.y, r * pulse * 1.5, 0, Math.PI * 2);
        ctx.fillStyle = `${color}15`; ctx.fill();
      }

      // Glow
      if (isHovered || isDragged) {
        const g = ctx.createRadialGradient(node.x, node.y, 0, node.x, node.y, r * 3);
        g.addColorStop(0, `${color}44`); g.addColorStop(1, "transparent");
        ctx.beginPath(); ctx.arc(node.x, node.y, r * 3, 0, Math.PI * 2);
        ctx.fillStyle = g; ctx.fill();
      }

      // Circle
      ctx.beginPath(); ctx.arc(node.x, node.y, r, 0, Math.PI * 2);
      ctx.fillStyle = isHovered ? color : `${color}cc`; ctx.fill();
      ctx.strokeStyle = isHovered ? "#ffffff88" : `${color}55`;
      ctx.lineWidth = (isHovered ? 2.5 : 1) / sc; ctx.stroke();

      // Inner icon indicator
      if (r > 12) {
        ctx.fillStyle = "rgba(255,255,255,0.6)";
        ctx.font = `${Math.max(8, r * 0.65)}px sans-serif`;
        ctx.textAlign = "center"; ctx.textBaseline = "middle";
        const icons: Record<string, string> = {
          SKILL: "⚡", EXPERIENCE: "💼", PROJECT: "🏗", CERTIFICATION: "🏅",
          EDUCATION: "🎓", APPLICATION: "📬", INTERVIEW: "🎯", COMPANY: "🏢",
          RECRUITER: "👤", CAREER_GOAL: "🚀", SALARY_TARGET: "💰", JOB_MATCH: "🔍",
          SKILL_GAP: "⚠", OFFER: "⭐",
        };
        ctx.fillText(icons[node.kind] ?? "•", node.x, node.y);
      }

      // Label
      if (r > 11 || isHovered) {
        ctx.fillStyle = isHovered ? "#ffffff" : "rgba(255,255,255,0.7)";
        ctx.font = `${isHovered ? "600" : "400"} ${isHovered ? 11 : 9}px Inter, sans-serif`;
        ctx.textAlign = "center"; ctx.textBaseline = "top";
        const lbl = node.label.length > 16 ? node.label.slice(0, 14) + "…" : node.label;
        ctx.fillText(lbl, node.x, node.y + r + 4);
      }
    }

    ctx.restore();

    // Zoom indicator
    ctx.fillStyle = "rgba(255,255,255,0.25)";
    ctx.font = "10px Inter, sans-serif";
    ctx.textAlign = "right";
    ctx.fillText(`${Math.round(sc * 100)}%`, width - 12, height - 10);
  }, [width, height]);

  useEffect(() => {
    build();
    const loop = () => { draw(); animRef.current = requestAnimationFrame(loop); };
    animRef.current = requestAnimationFrame(loop);
    return () => { if (animRef.current) cancelAnimationFrame(animRef.current); };
  }, [build, draw]);

  const toWorld = (cx: number, cy: number) => ({
    x: (cx - offsetRef.current.x) / scaleRef.current,
    y: (cy - offsetRef.current.y) / scaleRef.current,
  });

  const getNodeAt = (wx: number, wy: number): SimNode | null => {
    for (const node of simNodesRef.current) {
      const r = (NODE_RADIUS[node.kind] ?? 13) * (0.7 + node.weight * 0.55);
      const dx = node.x - wx, dy = node.y - wy;
      if (dx * dx + dy * dy <= r * r) return node;
    }
    return null;
  };

  const getCanvasXY = (e: React.MouseEvent) => {
    const rect = canvasRef.current!.getBoundingClientRect();
    return { x: (e.clientX - rect.left) * (width / rect.width), y: (e.clientY - rect.top) * (height / rect.height) };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const { x, y } = getCanvasXY(e);
    if (dragRef.current) {
      const w = toWorld(x, y);
      dragRef.current.x = w.x; dragRef.current.y = w.y;
      dragRef.current.vx = 0; dragRef.current.vy = 0;
      return;
    }
    if (isPanRef.current) {
      offsetRef.current.x = panStartRef.current.ox + (x - panStartRef.current.x);
      offsetRef.current.y = panStartRef.current.oy + (y - panStartRef.current.y);
      return;
    }
    const w = toWorld(x, y);
    hoveredRef.current = getNodeAt(w.x, w.y);
    canvasRef.current!.style.cursor = hoveredRef.current ? "pointer" : "grab";
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    const { x, y } = getCanvasXY(e);
    const w = toWorld(x, y);
    const node = getNodeAt(w.x, w.y);
    if (node) { dragRef.current = node; canvasRef.current!.style.cursor = "grabbing"; }
    else {
      isPanRef.current = true;
      panStartRef.current = { x, y, ox: offsetRef.current.x, oy: offsetRef.current.y };
      canvasRef.current!.style.cursor = "grabbing";
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
    const { x, y } = getCanvasXY(e);
    const w = toWorld(x, y);
    if (dragRef.current) {
      const node = getNodeAt(w.x, w.y);
      if (node && onNodeClick) onNodeClick(node);
      dragRef.current = null;
    }
    isPanRef.current = false;
    canvasRef.current!.style.cursor = "grab";
  };

  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    const { x, y } = getCanvasXY(e as unknown as React.MouseEvent);
    const delta = e.deltaY > 0 ? 0.9 : 1.1;
    const newScale = Math.max(0.3, Math.min(3, scaleRef.current * delta));
    offsetRef.current.x = x - (x - offsetRef.current.x) * (newScale / scaleRef.current);
    offsetRef.current.y = y - (y - offsetRef.current.y) * (newScale / scaleRef.current);
    scaleRef.current = newScale;
  };

  return (
    <canvas
      ref={canvasRef}
      width={width}
      height={height}
      onMouseMove={handleMouseMove}
      onMouseDown={handleMouseDown}
      onMouseUp={handleMouseUp}
      onMouseLeave={() => { dragRef.current = null; isPanRef.current = false; hoveredRef.current = null; }}
      onWheel={handleWheel}
      style={{ width: "100%", height: "auto", display: "block", cursor: "grab", borderRadius: "1.5rem" }}
    />
  );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import dynamic from "next/dynamic";
import type { CareerGraph, GraphNode, GraphNodeKind, GraphSummary, CareerGraphAnalytics } from "@/lib/career-graph/types";
import { NodeDetailPanel, GraphLegend, GraphStatsBar } from "./GraphControls";
import { GraphGapPanel, type GapAnalysis } from "./GraphGapPanel";
import { GraphAnalyticsPanel } from "./GraphAnalyticsPanel";
import { GitBranch, BarChart3, Search, RefreshCw, Cpu } from "lucide-react";

const CareerGraphCanvas = dynamic(
  () => import("./CareerGraphCanvas").then((m) => m.CareerGraphCanvas),
  { ssr: false, loading: () => <div className="h-[580px] flex items-center justify-center text-slate-500 text-sm">Initialising graph…</div> }
);

type Tab = "graph" | "analytics" | "gaps";
type LoadState = "idle" | "loading" | "success" | "error";

const ALL_KINDS: GraphNodeKind[] = [
  "SKILL","EXPERIENCE","PROJECT","CERTIFICATION","EDUCATION",
  "APPLICATION","INTERVIEW","COMPANY","RECRUITER","CAREER_GOAL",
  "SALARY_TARGET","JOB_MATCH","SKILL_GAP","OFFER",
];

export function CareerGraphPage() {
  const [tab, setTab] = useState<Tab>("graph");
  const [graph, setGraph] = useState<CareerGraph | null>(null);
  const [summary, setSummary] = useState<GraphSummary | null>(null);
  const [analytics, setAnalytics] = useState<CareerGraphAnalytics | null>(null);
  const [gapAnalysis, setGapAnalysis] = useState<GapAnalysis | null>(null);
  const [loadState, setLoadState] = useState<LoadState>("idle");
  const [rebuilding, setRebuilding] = useState(false);
  const [analyzingGaps, setAnalyzingGaps] = useState(false);
  const [selectedNode, setSelectedNode] = useState<GraphNode | null>(null);
  const [activeKinds, setActiveKinds] = useState<GraphNodeKind[]>(ALL_KINDS);

  const fetchGraph = useCallback(async () => {
    setLoadState("loading");
    try {
      const [gRes, sRes] = await Promise.all([
        fetch("/api/v1/career-graph"),
        fetch("/api/v1/career-graph/summary"),
      ]);
      if (!gRes.ok || !sRes.ok) throw new Error("fetch failed");
      const [{ graph: g }, { summary: s }] = await Promise.all([gRes.json(), sRes.json()]);
      setGraph(g);
      setSummary(s);
      setLoadState("success");
    } catch {
      setLoadState("error");
    }
  }, []);

  const fetchAnalytics = useCallback(async () => {
    try {
      const res = await fetch("/api/v1/career-graph/analytics");
      if (res.ok) {
        const d = await res.json();
        setAnalytics(d.analytics ?? d);
      }
    } catch {}
  }, []);

  const runGapAnalysis = async () => {
    setAnalyzingGaps(true);
    try {
      const res = await fetch("/api/v1/career-graph/gap-detection");
      if (res.ok) {
        const d = await res.json();
        setGapAnalysis(d.analysis);
        setTab("gaps");
      }
    } catch {}
    setAnalyzingGaps(false);
  };

  const triggerRebuild = async () => {
    setRebuilding(true);
    try {
      await fetch("/api/v1/career-graph", { method: "POST" });
      await Promise.all([fetchGraph(), fetchAnalytics()]);
    } finally {
      setRebuilding(false);
    }
  };

  const handleTabChange = (t: Tab) => {
    setTab(t);
    if (t === "analytics" && !analytics) fetchAnalytics();
    if (t === "gaps" && !gapAnalysis) runGapAnalysis();
  };

  useEffect(() => { fetchGraph(); }, [fetchGraph]);

  const toggleKind = (kind: GraphNodeKind) =>
    setActiveKinds(prev => prev.includes(kind) ? prev.filter(k => k !== kind) : [...prev, kind]);

  const filteredKinds = activeKinds.length === ALL_KINDS.length ? undefined : activeKinds;

  return (
    <div className="min-h-screen bg-[#030307] text-slate-100 p-6 md:p-8 max-w-7xl mx-auto space-y-6 font-sans">

      {/* ── HEADER ── */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 border-b border-slate-800 pb-6">
        <div className="space-y-2">
          <div className="inline-flex items-center gap-2 rounded-full border border-indigo-500/20 bg-indigo-950/30 px-3 py-1 text-xs font-semibold text-indigo-300">
            <GitBranch className="h-3.5 w-3.5" /> Career Intelligence Graph
          </div>
          <h1 className="text-4xl font-black tracking-tight bg-gradient-to-r from-white to-indigo-400 bg-clip-text text-transparent">
            Career Graph
          </h1>
          <p className="text-slate-400 text-sm">
            {summary ? `${summary.totalNodes} nodes · ${summary.totalEdges} connections · ${Math.round(summary.completenessScore)}% complete` : "Your career intelligence network"}
          </p>
        </div>
        <div className="flex items-center gap-3 flex-wrap">
          <button onClick={runGapAnalysis} disabled={analyzingGaps}
            className="flex items-center gap-2 bg-purple-950/40 border border-purple-500/30 hover:bg-purple-950/60 text-purple-300 font-bold text-xs uppercase px-4 py-2.5 rounded-xl transition-all">
            <Search className={`h-3.5 w-3.5 ${analyzingGaps ? "animate-spin" : ""}`} />
            {analyzingGaps ? "Analyzing..." : "Detect Gaps"}
          </button>
          <button onClick={triggerRebuild} disabled={rebuilding}
            className="flex items-center gap-2 bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white font-bold text-xs uppercase px-4 py-2.5 rounded-xl shadow-lg transition-all">
            <RefreshCw className={`h-3.5 w-3.5 ${rebuilding ? "animate-spin" : ""}`} />
            {rebuilding ? "Rebuilding..." : "Rebuild Graph"}
          </button>
        </div>
      </div>

      {/* ── STATS ── */}
      {summary && (
        <div className="flex flex-wrap gap-3">
          {[
            { label: "Nodes", value: summary.totalNodes, color: "#6366f1" },
            { label: "Edges", value: summary.totalEdges, color: "#10b981" },
            { label: "Completeness", value: `${Math.round(summary.completenessScore)}%`, color: "#f59e0b" },
            { label: "Last Updated", value: new Date(summary.lastUpdated).toLocaleDateString(undefined, { month: "short", day: "numeric" }), color: "#6b7280" },
          ].map(({ label, value, color }) => (
            <div key={label} className="bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 flex items-center gap-2">
              <span className="text-base font-black" style={{ color }}>{value}</span>
              <span className="text-xs text-slate-500 font-medium">{label}</span>
            </div>
          ))}
        </div>
      )}

      {/* ── TABS ── */}
      <div className="flex gap-2 border-b border-slate-800 pb-0">
        {([
          { id: "graph" as Tab, label: "Graph View", icon: <GitBranch className="h-3.5 w-3.5" /> },
          { id: "analytics" as Tab, label: "Analytics", icon: <BarChart3 className="h-3.5 w-3.5" /> },
          { id: "gaps" as Tab, label: "Gap Detection", icon: <Cpu className="h-3.5 w-3.5" /> },
        ]).map(({ id, label, icon }) => (
          <button key={id} onClick={() => handleTabChange(id)}
            className={`flex items-center gap-1.5 px-4 py-2.5 text-xs font-extrabold uppercase tracking-wide border-b-2 transition-all -mb-px ${
              tab === id
                ? "border-indigo-500 text-indigo-300"
                : "border-transparent text-slate-500 hover:text-slate-300"
            }`}>
            {icon}{label}
          </button>
        ))}
      </div>

      {/* ── GRAPH TAB ── */}
      {tab === "graph" && (
        <div className="space-y-4">
          {/* Legend */}
          {summary && Object.keys(summary.nodesByKind).length > 0 && (
            <GraphLegend
              nodesByKind={summary.nodesByKind as Partial<Record<GraphNodeKind, number>>}
              activeKinds={activeKinds}
              onToggle={toggleKind}
            />
          )}

          {loadState === "loading" && (
            <div className="bg-slate-950 border border-slate-800 rounded-3xl h-[580px] flex flex-col items-center justify-center gap-4">
              <RefreshCw className="h-8 w-8 text-indigo-400 animate-spin" />
              <p className="text-slate-400 text-sm">Loading Career Graph…</p>
            </div>
          )}

          {loadState === "error" && (
            <div className="bg-slate-950 border border-dashed border-slate-800 rounded-3xl p-16 flex flex-col items-center gap-4">
              <p className="text-rose-400 text-sm">Failed to load graph.</p>
              <button onClick={fetchGraph} className="bg-indigo-600 text-white text-xs font-bold px-4 py-2 rounded-xl">Retry</button>
            </div>
          )}

          {loadState === "success" && graph && graph.nodes.length > 0 ? (
            <div className="relative bg-slate-950 border border-slate-800 rounded-3xl overflow-hidden shadow-2xl">
              <CareerGraphCanvas
                graph={graph}
                onNodeClick={setSelectedNode}
                {...(filteredKinds ? { filterKinds: filteredKinds } : {})}
                width={1080}
                height={580}
              />
              <NodeDetailPanel node={selectedNode} onClose={() => setSelectedNode(null)} />
            </div>
          ) : loadState === "success" ? (
            <div className="bg-slate-950 border border-dashed border-slate-800 rounded-3xl p-20 flex flex-col items-center text-center gap-4">
              <div className="h-16 w-16 rounded-full bg-slate-900 border border-slate-800 flex items-center justify-center">
                <GitBranch className="h-8 w-8 text-slate-600" />
              </div>
              <h3 className="text-lg font-bold text-white">Graph is empty</h3>
              <p className="text-xs text-slate-500 max-w-sm leading-relaxed">Upload a resume or apply to a job to start building your Career Intelligence Graph.</p>
              <button onClick={triggerRebuild} disabled={rebuilding}
                className="bg-gradient-to-r from-indigo-600 to-purple-600 text-white font-bold text-xs uppercase px-5 py-2.5 rounded-xl">
                {rebuilding ? "Building..." : "Build from existing data"}
              </button>
            </div>
          ) : null}
        </div>
      )}

      {/* ── ANALYTICS TAB ── */}
      {tab === "analytics" && (
        <div>
          {analytics ? (
            <GraphAnalyticsPanel analytics={analytics} />
          ) : (
            <div className="bg-slate-950 border border-dashed border-slate-800 rounded-3xl p-16 flex flex-col items-center gap-4">
              <BarChart3 className="h-10 w-10 text-slate-600" />
              <h3 className="text-base font-bold text-white">Loading Analytics…</h3>
              <button onClick={fetchAnalytics} className="bg-indigo-600 text-white text-xs font-bold px-4 py-2 rounded-xl">Load Analytics</button>
            </div>
          )}
        </div>
      )}

      {/* ── GAP DETECTION TAB ── */}
      {tab === "gaps" && (
        <div>
          {analyzingGaps && (
            <div className="bg-slate-950 border border-slate-800 rounded-3xl p-16 flex flex-col items-center gap-4">
              <Cpu className="h-10 w-10 text-purple-400 animate-pulse" />
              <p className="text-slate-300 text-sm font-medium">AI analyzing your career graph for gaps and opportunities…</p>
            </div>
          )}
          {!analyzingGaps && gapAnalysis ? (
            <GraphGapPanel analysis={gapAnalysis} />
          ) : !analyzingGaps ? (
            <div className="bg-slate-950 border border-dashed border-slate-800 rounded-3xl p-16 flex flex-col items-center gap-4">
              <Search className="h-10 w-10 text-slate-600" />
              <h3 className="text-base font-bold text-white">No Gap Analysis Yet</h3>
              <p className="text-xs text-slate-500 max-w-sm text-center">Run AI gap detection to find missing skills, hidden opportunities, and relationship insights.</p>
              <button onClick={runGapAnalysis}
                className="bg-gradient-to-r from-purple-600 to-indigo-600 text-white font-bold text-xs uppercase px-5 py-2.5 rounded-xl">
                Run Gap Detection
              </button>
            </div>
          ) : null}
        </div>
      )}
    </div>
  );
}

