  COMPANY: "Company",
  RECRUITER: "Recruiter",
  CAREER_GOAL: "Career Goal",
  SALARY_TARGET: "Salary Target",
  JOB_MATCH: "Job Match",
  SKILL_GAP: "Skill Gap",
  OFFER: "Offer",
