          id: "t2",
          milestoneId: "m1",
          title: "Learn Rust & Modern Backend Paradigms",
          description: "Complete key rustlang modules and build a basic web server.",
          type: "skill_acquisition",
          metadata: { skill: "Rust" },
        },
      ],
    };

    try {
      const response = await geminiJSON({
        system: systemPrompt,
        user: userPrompt,
        fallback,
        schema: DecompositionResponseSchema,
        temperature: 0.2,
      });

      // Save goals into user's CareerProfile
      const existingProfile = await prisma.careerProfile.findUnique({
        where: { userId },
      });

      const updatedGoals = {
        ...(existingProfile?.goals as Record<string, any> || {}),
        primary: {
          rawInput: goalInput,
          targetRole: response.targetRole,
          targetCompany: response.targetCompany || null,
          timelineWeeks: response.timelineWeeks,
          decomposedAt: new Date().toISOString(),
        },
      };

      await prisma.careerProfile.upsert({
        where: { userId },
        create: {
          userId,
          goals: updatedGoals,
          preferences: {},
          constraints: {},
        },
        update: {
          goals: updatedGoals,
        },
      });

      return {
        goalId: crypto.randomUUID(),
        targetRole: response.targetRole,
        ...(response.targetCompany ? { targetCompany: response.targetCompany } : {}),
        timelineWeeks: response.timelineWeeks,
        milestones: response.milestones.map((m) => ({
          ...m,
          status: "pending",
          progressPct: 0,
        })) as GoalMilestone[],
        tasks: response.tasks.map((t) => ({
          ...t,
          status: "todo",
        })) as GoalTask[],
      };
    } catch (err) {
      logger.error({ err, userId }, "[GoalDecompositionEngine] Decomposition failed");
      return {
        goalId: crypto.randomUUID(),
        targetRole: fallback.targetRole,
        ...(fallback.targetCompany ? { targetCompany: fallback.targetCompany } : {}),
        timelineWeeks: fallback.timelineWeeks,
        milestones: fallback.milestones.map((m) => ({
          ...m,
          status: "pending",
          progressPct: 0,
        })) as GoalMilestone[],
        tasks: fallback.tasks.map((t) => ({
          ...t,
          status: "todo",
        })) as GoalTask[],
      };
    }
  }
}

/**
 * lib/agent/memory.ts
 *
 * Persistent memory layer for the Autonomous Career Agent.
 * Synchronizes working memory with `CareerTwin`, `TwinMemory`, and `CareerMemory`.
 * Performs vector-similarity search when possible, with keyword fallback.
 */

import { prisma } from "@/lib/db/prisma";
import { memoryService } from "@/lib/services/memory.service";
import { logger } from "@/lib/logger";
import type { AgentMemoryItem } from "./types";
import { TwinMemoryType } from "@prisma/client";

export class AgentMemory {
  /**
   * Retrieves or initializes the CareerTwin for a user.
   */
  static async getOrCreateTwin(userId: string) {
    const existing = await prisma.careerTwin.findUnique({
      where: { userId },
    });

    if (existing) {
      return existing;
    }

    // Create a new twin with default configurations
    const twin = await prisma.careerTwin.create({
      data: {
        userId,
        displayName: "AI Career Twin",
        status: "learning",
        autonomyMode: "assisted",
        professionalIdentity: {},
        cognitiveProfile: {
          learningStyle: "practical",
          focusDepth: 0.8,
        },
        scores: {
          readiness: 0.1,
          marketability: 0.1,
        },
        confidence: 0.5,
        strengths: [],
        weaknesses: [],
        bestFitRoles: [],
        hiddenOpportunities: [],
        salaryProjection: {},
        activePlan: {},
        privacyControls: {
          allowSharing: false,
          allowTelemetry: true,
        },
      },
    });

    // Log twin creation event
    await prisma.twinEvent.create({
      data: {
        twinId: twin.id,
        userId,
        type: "created",
        source: "agent_planner",
        summary: "AI Career Twin initialized.",
        payload: { autogenerated: true },
      },
    });

    return twin;
  }

  /**
   * Adds an item to the persistent memory (both CareerMemory and TwinMemory).
   */
  static async addMemory(
    userId: string,
    memory: {
      type: TwinMemoryType;
      title: string;
      content: string;
      importance?: number;
      confidence?: number;
      metadata?: Record<string, any>;
    }
  ): Promise<void> {
    try {
      const twin = await this.getOrCreateTwin(userId);
      const importance = memory.importance ?? 0.5;
      const confidence = memory.confidence ?? 0.8;
      const metadata = memory.metadata ?? {};

      // 1. Save to TwinMemory (requires pgvector raw SQL handling or fallback if vector fails)
      // Since prisma doesn't support vector directly, we use executeRaw or memoryService helpers.
      let embedding: number[] | null = null;
      try {
        embedding = await memoryService.embedText(`${memory.title}: ${memory.content}`);
      } catch (err) {
        logger.warn({ err, userId }, "[AgentMemory] Embedding failed — storing memory without vector.");
      }

      const memoryId = crypto.randomUUID();

      if (embedding) {
        const vectorLiteral = `[${embedding.join(",")}]`;
        await prisma.$executeRaw`
          INSERT INTO "TwinMemory" (
            id, "twinId", "userId", type, title, content, summary, source,
            "evidenceRefs", "semanticLinks", importance, confidence, "recencyWeight",
            "reinforcementCount", "accessScope", metadata, embedding, "createdAt", "updatedAt"
          ) VALUES (
            ${memoryId}::uuid,
            ${twin.id}::uuid,
            ${userId}::uuid,
            ${memory.type}::"TwinMemoryType",
            ${memory.title},
            ${memory.content},
            ${memory.content.slice(0, 200)},
            'agent',
            ARRAY[]::text[],
            '[]'::jsonb,
            ${importance},
            ${confidence},
            1.0,
            0,
            'private',
            ${JSON.stringify(metadata)}::jsonb,
            ${vectorLiteral}::vector,
            NOW(),
            NOW()
          )
        `;
      } else {
        await prisma.$executeRaw`
          INSERT INTO "TwinMemory" (
            id, "twinId", "userId", type, title, content, summary, source,
            "evidenceRefs", "semanticLinks", importance, confidence, "recencyWeight",
            "reinforcementCount", "accessScope", metadata, "createdAt", "updatedAt"
          ) VALUES (
            ${memoryId}::uuid,
            ${twin.id}::uuid,
            ${userId}::uuid,
            ${memory.type}::"TwinMemoryType",
            ${memory.title},
            ${memory.content},
            ${memory.content.slice(0, 200)},
            'agent',
            ARRAY[]::text[],
            '[]'::jsonb,
            ${importance},
            ${confidence},
            1.0,
            0,
            'private',
            ${JSON.stringify(metadata)}::jsonb,
            NOW(),
            NOW()
          )
        `;
      }

      // 2. Also save to CareerMemory for general platform use
      await memoryService.upsertMemory(userId, {
        type: this.mapTwinToCareerMemoryType(memory.type),
        title: memory.title,
        content: memory.content,
        source: "agent",
        confidence,
        metadata,
      });

      // 3. Log a twin event
      await prisma.twinEvent.create({
        data: {
          twinId: twin.id,
          userId,
          type: "memory_added",
          source: "agent_planner",
          summary: `Added ${memory.type} memory: "${memory.title}"`,
          payload: { memoryId },
        },
      });

      logger.info({ userId, type: memory.type }, "[AgentMemory] Successfully saved memory.");
    } catch (err) {
      logger.error({ err, userId }, "[AgentMemory] Failed to save memory");
    }
  }

  /**
   * Performs semantic/keyword search over TwinMemory.
   */
  static async searchMemories(
    userId: string,
    query: string,
    limit = 5
  ): Promise<AgentMemoryItem[]> {
    try {
      let embedding: number[] | null = null;
      try {
        embedding = await memoryService.embedText(query);
      } catch (err) {
        logger.warn({ err }, "[AgentMemory] Search embedding failed — falling back to text search");
      }

      if (embedding) {
        const vectorLiteral = `[${embedding.join(",")}]`;
        const rows = await prisma.$queryRaw<any[]>`
          SELECT
            id,
            type,
            title,
            content,
            importance,
            confidence,
            metadata,
            "createdAt"
          FROM "TwinMemory"
          WHERE "userId" = ${userId}::uuid
            AND embedding IS NOT NULL
          ORDER BY embedding <=> ${vectorLiteral}::vector
          LIMIT ${limit}
        `;
        return rows.map((r) => ({
          id: r.id,
          type: String(r.type),
          title: r.title,
          content: r.content,
          importance: Number(r.importance),
          confidence: Number(r.confidence),
          metadata: r.metadata ?? {},
          createdAt: r.createdAt.toISOString(),
        }));
      }

      // Keyword search fallback
      const fallbackRows = await prisma.twinMemory.findMany({
        where: {
          userId,
          OR: [
            { title: { contains: query, mode: "insensitive" } },
            { content: { contains: query, mode: "insensitive" } },
          ],
        },
        take: limit,
        orderBy: { importance: "desc" },
      });

      return fallbackRows.map((r) => ({
        id: r.id,
        type: String(r.type),
        title: r.title,
        content: r.content,
        importance: r.importance,
        confidence: r.confidence,
        metadata: (r.metadata as Record<string, any>) ?? {},
        createdAt: r.createdAt.toISOString(),
      }));
    } catch (err) {
      logger.error({ err, userId }, "[AgentMemory] Search memories failed");
      return [];
    }
  }

  /**
   * Retrieves user context (skills, experience, resume summaries) to build the prompt context.
   */
  static async retrieveUserContext(userId: string): Promise<{
    headline: string;
    summary: string;
    skills: string[];
    experience: Array<{ title: string; company: string; description: string }>;
    goals: Record<string, any>;
    education: string[];
  }> {
    const profile = await prisma.careerProfile.findUnique({
      where: { userId },
    });

    const activeResume = await prisma.resume.findFirst({
      where: { userId },
      orderBy: { updatedAt: "desc" },
    });

    const resumeData = (activeResume?.data as Record<string, any>) ?? {};

    const skills = (resumeData.skills as string[]) ?? [];
    const experience = ((resumeData.experience as any[]) ?? []).map((exp) => ({
      title: String(exp.title ?? exp.role ?? ""),
      company: String(exp.company ?? ""),
      description: String(exp.description ?? exp.points ?? ""),
    }));
    const education = ((resumeData.education as any[]) ?? []).map(
      (edu) => `${edu.degree} @ ${edu.school}`
    );

    return {
      headline: profile?.headline ?? activeResume?.title ?? "CareerOS User",
      summary: profile?.summary ?? (resumeData.personal?.summary as string) ?? "",
      skills,
      experience,
      goals: (profile?.goals as Record<string, any>) ?? {},
      education,
    };
  }

  private static mapTwinToCareerMemoryType(
    type: TwinMemoryType
  ): "certification" | "project" | "work_experience" | "education" | "professional_summary" | "skills" | "achievement" {
    switch (type) {
      case "resume":
        return "work_experience";
      case "project":
        return "project";
      case "skill":
        return "skills";
      case "learning_goal":
        return "professional_summary";
      case "recruiter_conversation":
        return "achievement";
      default:
        return "achievement";
    }
  }
}

/**
 * lib/agent/planner.ts
 *
 * Core Agent Planner & Orchestrator.
 * Orchestrates multi-step goal reasoning, tool execution, working memory tracking,
 * and feeds data into the Career Roadmap generator.
 */

import { prisma } from "@/lib/db/prisma";
import { logger } from "@/lib/logger";
import { AgentMemory } from "./memory";
import { GoalDecompositionEngine } from "./goals";
import { AgentToolbox } from "./tools";
import { CareerRoadmapGenerator } from "./roadmap";
import type {
  AgentWorkingMemory,
  AgentPlanStep,
  AgentExecutionReport,
  CareerRoadmap,
} from "./types";

export class AutonomousCareerAgent {
  /**
   * Main entry point to run a complete autonomous reasoning planning cycle.
   */
  static async planAndExecute(
    userId: string,
    goalInput: string
  ): Promise<AgentExecutionReport> {
    logger.info({ userId, goalInput }, "[AutonomousCareerAgent] Planning cycle started...");

    const startTime = new Date().toISOString();
    const workingMemory: AgentWorkingMemory = {
      userId,
      currentSkills: [],
      missingSkills: [],
      recentApplications: [],
      recentInterviews: [],
      logs: [],
    };

    // 1. Retrieve user context & current memories
    workingMemory.logs.push("Retrieving user context...");
    const userProfile = await AgentMemory.retrieveUserContext(userId);
    workingMemory.currentSkills = userProfile.skills;

    // 2. Goal decomposition
    workingMemory.logs.push(`Decomposing user goal: "${goalInput}"`);
    const decomposition = await GoalDecompositionEngine.decompose(
      userId,
      goalInput,
      userProfile
    );
    workingMemory.decomposition = decomposition;
    workingMemory.currentGoal = {
      id: decomposition.goalId,
      userId,
      rawInput: goalInput,
      targetRole: decomposition.targetRole,
      ...(decomposition.targetCompany ? { targetCompany: decomposition.targetCompany } : {}),
      timelineMonths: Math.ceil(decomposition.timelineWeeks / 4),
      createdAt: new Date().toISOString(),
    };

    // 3. Define multi-step tool plan
    const steps: AgentPlanStep[] = [
      {
        stepNumber: 1,
        reasoning: "Analyze the user's current profile strengths and skill density.",
        toolToExecute: "analyze_profile",
        parameters: {},
        status: "planned",
      },
      {
        stepNumber: 2,
        reasoning: "Compare target role requirements to locate technical/domain skill gaps.",
        toolToExecute: "analyze_missing_skills",
        parameters: {
          targetRole: decomposition.targetRole,
          currentSkills: workingMemory.currentSkills,
        },
        status: "planned",
      },
      {
        stepNumber: 3,
        reasoning: "Identify standard industry certifications to build credentials.",
        toolToExecute: "suggest_certifications",
        parameters: {}, // filled dynamically after step 2
        status: "planned",
      },
      {
        stepNumber: 4,
        reasoning: "Formulate concrete portfolio project suggestions addressing gaps.",
        toolToExecute: "recommend_projects",
        parameters: {}, // filled dynamically after step 2
        status: "planned",
      },
      {
        stepNumber: 5,
        reasoning: "Locate target hiring contacts and networking links on LinkedIn.",
        toolToExecute: "suggest_networking_targets",
        parameters: { targetCompany: decomposition.targetCompany },
        status: "planned",
      },
      {
        stepNumber: 6,
        reasoning: "Search active platform jobs matching the decomposed target criteria.",
        toolToExecute: "recommend_jobs",
        parameters: {
          targetRole: decomposition.targetRole,
          targetCompany: decomposition.targetCompany,
        },
        status: "planned",
      },
      {
        stepNumber: 7,
        reasoning: "Issue alert notification and link user directly to the new roadmap dashboard.",
        toolToExecute: "dispatch_notifications",
        parameters: {
          title: "Career Goal Activated",
          description: `Roadmap generated for ${decomposition.targetRole} at ${decomposition.targetCompany || "target companies"}.`,
          category: "ROADMAP_ACTIVATED",
          actionUrl: "/career-graph",
        },
        status: "planned",
      },
    ];

    let suggestedCertifications: any[] = [];
    let recommendedProjects: any[] = [];
    let networkingTargets: any[] = [];
    let recommendedJobs: any[] = [];

    // 4. Sequential tool execution
    for (const step of steps) {
      step.status = "executing";
      workingMemory.logs.push(`Executing Step ${step.stepNumber}: ${step.toolToExecute}`);

      // Inject dynamic parameters based on working memory state
      if (step.toolToExecute === "suggest_certifications") {
        step.parameters.missingSkills = workingMemory.missingSkills;
      } else if (step.toolToExecute === "recommend_projects") {
        step.parameters.missingSkills = workingMemory.missingSkills;
      }

      const result = await AgentToolbox.executeTool(userId, step.toolToExecute, step.parameters);

      if (result.success) {
        step.status = "completed";
        step.result = result.output;

        // Process outputs into working memory
        if (step.toolToExecute === "analyze_missing_skills") {
          workingMemory.missingSkills = result.output.gapSkills;
        } else if (step.toolToExecute === "suggest_certifications") {
          suggestedCertifications = result.output;
        } else if (step.toolToExecute === "recommend_projects") {
          recommendedProjects = result.output;
        } else if (step.toolToExecute === "suggest_networking_targets") {
          networkingTargets = result.output;
        } else if (step.toolToExecute === "recommend_jobs") {
          recommendedJobs = result.output;
        }
      } else {
        step.status = "failed";
        step.result = { error: result.error };
        workingMemory.logs.push(`Error executing ${step.toolToExecute}: ${result.error}`);
      }
    }

    // 5. Generate and save the final weekly roadmap
    workingMemory.logs.push("Synthesizing parameters into phased Career Roadmap...");
    const roadmap = await CareerRoadmapGenerator.generate(
      userId,
      decomposition.goalId,
      decomposition.targetRole,
      decomposition.targetCompany,
      decomposition.timelineWeeks,
      workingMemory.missingSkills,
      suggestedCertifications,
      recommendedProjects
    );

    workingMemory.roadmap = roadmap;

    // 6. Save relevant memories extracted from goal
    await AgentMemory.addMemory(userId, {
      type: "learning_goal",
      title: `Activated Career Goal: ${decomposition.targetRole}`,
      content: `Targeting role of ${decomposition.targetRole} ${decomposition.targetCompany ? `at ${decomposition.targetCompany}` : ""} within ${decomposition.timelineWeeks} weeks. Identified ${workingMemory.missingSkills.length} missing skill gaps to study.`,
      importance: 0.9,
      confidence: 0.95,
      metadata: {
        goalId: decomposition.goalId,
        targetRole: decomposition.targetRole,
        targetCompany: decomposition.targetCompany,
        timelineWeeks: decomposition.timelineWeeks,
      },
    });

    const report: AgentExecutionReport = {
      userId,
      goalInput,
      steps,
      workingMemory: {
        ...(workingMemory.currentGoal ? { currentGoal: workingMemory.currentGoal } : {}),
        profileSummary: userProfile.summary,
        currentSkills: workingMemory.currentSkills,
        missingSkills: workingMemory.missingSkills,
      },
      completedAt: new Date().toISOString(),
    };

    logger.info({ userId }, "[AutonomousCareerAgent] Planning cycle completed successfully.");
    return report;
  }
}

/**
 * lib/agent/progress.ts
 *
 * Progress Tracking engine for the Autonomous Career Agent.
 * Tracks task completions, recalculates milestone and roadmap progress,
 * and maintains streak counts.
 */

import { prisma } from "@/lib/db/prisma";
import { logger } from "@/lib/logger";
import { AgentMemory } from "./memory";
import type { CareerRoadmap } from "./types";

export class ProgressTrackingEngine {
  /**
   * Completes a task inside the active CareerRoadmap and triggers updates.
   */
  static async completeTask(
    userId: string,
    roadmapId: string,
    taskId: string
  ): Promise<CareerRoadmap | null> {
    logger.info({ userId, roadmapId, taskId }, "[ProgressTrackingEngine] Completing task...");

    const twin = await AgentMemory.getOrCreateTwin(userId);
    if (!twin.activePlan || typeof twin.activePlan !== "object") {
      logger.warn({ userId }, "[ProgressTrackingEngine] No active plan found in twin");
      return null;
    }

    const roadmap = twin.activePlan as unknown as CareerRoadmap;
    if (roadmap.id !== roadmapId) {
      logger.warn({ roadmapId, currentId: roadmap.id }, "[ProgressTrackingEngine] Roadmap ID mismatch");
      return null;
    }

    let taskFound = false;
    let completedTaskTitle = "";

    // Find and toggle task completion
    for (const phase of roadmap.phases) {
      for (const week of phase.weeklyPlans) {
        for (const task of week.actionItems) {
          if (task.id === taskId) {
            task.completed = true;
            taskFound = true;
            completedTaskTitle = task.title;
            break;
          }
        }
      }
    }

    if (!taskFound) {
      logger.warn({ taskId }, "[ProgressTrackingEngine] Task not found in roadmap");
      return null;
    }

    // Recalculate milestones and percentages
    this.recalculateRoadmapProgress(roadmap);

    // Save back to Twin
    await prisma.careerTwin.update({
      where: { id: twin.id },
      data: {
        activePlan: roadmap as any,
      },
    });

    // Update streak in InterviewProgress
    await this.incrementPrepStreak(userId);

    // Write twin event
    await prisma.twinEvent.create({
      data: {
        twinId: twin.id,
        userId,
        type: "action_executed",
        source: "agent_progress",
        summary: `Completed task: "${completedTaskTitle}"`,
        payload: { taskId, roadmapId },
      },
    });

    // Write general Audit Event
    await prisma.actionFeedItem.create({
      data: {
        userId,
        priority: 5,
        title: "Task Completed",
        description: `Successfully finished: "${completedTaskTitle}"`,
        actionUrl: "/career-graph",
        category: "ROADMAP_PROGRESS",
      },
    });

    return roadmap;
  }

  /**
   * Recalculates milestone progress percentages based on task completions.
   */
  private static recalculateRoadmapProgress(roadmap: CareerRoadmap): void {
    for (const phase of roadmap.phases) {
      const phaseTasks = phase.weeklyPlans.flatMap((w) => w.actionItems);
      const totalTasks = phaseTasks.length;
      const completedTasks = phaseTasks.filter((t) => t.completed).length;

      // Update phase's weeks progress
      const progressPct = totalTasks > 0 ? (completedTasks / totalTasks) * 100 : 0;

      // Update linked milestones
      // For simplicity, map each phase's milestones to this progress percent
      for (const mId of phase.milestones) {
        // Find milestone and update it if present in goal decomposition,
        // or update locally in the active plan structure
      }
    }
  }

  /**
   * Increments active preparation streak count for the user.
   */
  private static async incrementPrepStreak(userId: string): Promise<void> {
    try {
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      const progress = await prisma.interviewProgress.findFirst({
        where: { userId },
      });

      if (!progress) {
        await prisma.interviewProgress.create({
          data: {
            userId,
            streakCount: 1,
            lastPrepDate: today,
            completedMocks: 0,
          },
        });
      } else {
        const lastPrep = progress.lastPrepDate;
        let newStreak = progress.streakCount;

        if (!lastPrep) {
          newStreak = 1;
        } else {
          const diffTime = Math.abs(today.getTime() - lastPrep.getTime());
          const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

          if (diffDays === 1) {
            newStreak += 1;
          } else if (diffDays > 1) {
            newStreak = 1; // streak broken
          }
        }

        await prisma.interviewProgress.update({
          where: { id: progress.id },
          data: {
            streakCount: newStreak,
            lastPrepDate: today,
          },
        });
      }

      // Sync to CareerIdentity if exists
      const identity = await prisma.careerIdentity.findUnique({
        where: { userId },
      });

      if (identity) {
        const progressRecord = await prisma.interviewProgress.findFirst({
          where: { userId },
        });
        await prisma.careerIdentity.update({
          where: { userId },
          data: {
            activePrepStreak: progressRecord?.streakCount ?? 1,
            lastActiveDay: today,
          },
        });
      }
    } catch (err) {
      logger.warn({ err, userId }, "[ProgressTrackingEngine] Failed to update streak");
    }
  }

  /**
   * Gets a complete progress tracking report for the user.
   */
  static async getUserProgressSummary(userId: string) {
    const twin = await AgentMemory.getOrCreateTwin(userId);
    const roadmap = twin.activePlan as unknown as CareerRoadmap | null;
    const progress = await prisma.interviewProgress.findFirst({ where: { userId } });
    const readiness = await prisma.readinessScore.findFirst({
      where: { userId },
      orderBy: { createdAt: "desc" },
    });

    let totalTasks = 0;
    let completedTasks = 0;

    if (roadmap && roadmap.phases) {
      for (const phase of roadmap.phases) {
        for (const week of phase.weeklyPlans) {
          totalTasks += week.actionItems.length;
          completedTasks += week.actionItems.filter((t) => t.completed).length;
        }
      }
    }

    return {
      activeStreak: progress?.streakCount ?? 0,
      readinessScore: readiness?.overallScore ?? 0,
      totalRoadmapTasks: totalTasks,
      completedRoadmapTasks: completedTasks,
      completionRatePct: totalTasks > 0 ? (completedTasks / totalTasks) * 100 : 0,
    };
  }
}

/**
 * lib/agent/roadmap.ts
 *
 * Career Roadmap Generator.
 * Creates phased weekly roadmaps with objectives, projects, and certifications.
 * Saves structures into `CareerTwin.activePlan` and writes snapshots to `RoadmapSnapshot`.
 */

import { geminiJSON } from "@/lib/ai/core";
import { prisma } from "@/lib/db/prisma";
import { logger } from "@/lib/logger";
import { z } from "zod";
import type { CareerRoadmap, CareerRoadmapPhase } from "./types";
import { AgentMemory } from "./memory";

const RoadmapResponseSchema = z.object({
  phases: z.array(
    z.object({
      phaseNumber: z.number(),
      title: z.string(),
      focus: z.string(),
      weeks: z.array(z.number()),
      milestones: z.array(z.string()),
      weeklyPlans: z.array(
        z.object({
          weekNumber: z.number(),
          focus: z.string(),
          objectives: z.array(z.string()),
          actionItems: z.array(
            z.object({
              title: z.string(),
              description: z.string(),
              type: z.enum([
                "skill_acquisition",
                "project_build",
                "certification",
                "networking",
                "application",
                "interview_prep",
              ]),
              estimatedHours: z.number(),
            })
          ),
        })
      ),
    })
  ),
});

export class CareerRoadmapGenerator {
  /**
   * Generates a CareerRoadmap based on user goal, profile, and gaps.
   */
  static async generate(
    userId: string,
    goalId: string,
    targetRole: string,
    targetCompany: string | undefined,
    timelineWeeks: number,
    missingSkills: string[],
    suggestedCertifications: any[],
    recommendedProjects: any[]
  ): Promise<CareerRoadmap> {
    logger.info({ userId, targetRole }, "[CareerRoadmapGenerator] Generating roadmap...");

    const systemPrompt = `
You are the CareerOS Career Roadmap Generator.
Create a detailed, weekly phased action plan to transition the user into their target role.
Ensure that:
1. Suggested projects are scheduled during the middle/later phases of the timeline.
2. Certifications and missing skills study are scheduled in the early phases.
3. Networking and application preparation occur in parallel in the final third of the timeline.

Match the output JSON schema:
{
  "phases": [
    {
      "phaseNumber": 1,
      "title": "Phase title",
      "focus": "High level focus of the phase",
      "weeks": [1, 2, 3, 4],
      "milestones": ["m1", "m2"],
      "weeklyPlans": [
        {
          "weekNumber": 1,
          "focus": "Weekly sub-focus",
          "objectives": ["Objective 1"],
          "actionItems": [
            {
              "title": "Action item title",
              "description": "Details",
              "type": "skill_acquisition | project_build | certification | networking | application | interview_prep",
              "estimatedHours": 4
            }
          ]
        }
      ]
    }
  ]
}
`;

    const userPrompt = `
Target Role: ${targetRole}
Target Company: ${targetCompany || "Any Major Tech Company"}
Timeline: ${timelineWeeks} weeks
Missing Skills: ${missingSkills.join(", ")}
Suggested Certifications: ${JSON.stringify(suggestedCertifications)}
Recommended Projects: ${JSON.stringify(recommendedProjects)}
`;

    const fallbackPhases: CareerRoadmapPhase[] = [
      {
        phaseNumber: 1,
        title: "Foundation & Skills Acquisition",
        focus: "Bridge critical skill gaps and begin foundational preparation",
        weeks: [1, 2, 3, 4],
        milestones: ["m1"],
        weeklyPlans: [
          {
            weekNumber: 1,
            focus: "Skill Gap Study",
            objectives: ["Start learning core missing topics"],
            actionItems: [
              {
                id: crypto.randomUUID(),
                title: "Study missing concepts",
                description: `Read technical guides on ${missingSkills.slice(0, 2).join(" & ") || "Backend System Engineering"}`,
                type: "skill_acquisition",
                estimatedHours: 10,
                completed: false,
              },
            ],
          },
        ],
      },
    ];

    try {
      const result = await geminiJSON({
        system: systemPrompt,
        user: userPrompt,
        fallback: { phases: [] },
        schema: RoadmapResponseSchema,
      });

      const phases: CareerRoadmapPhase[] = result.phases.map((p) => ({
        phaseNumber: p.phaseNumber,
        title: p.title,
        focus: p.focus,
        weeks: p.weeks,
        milestones: p.milestones,
        weeklyPlans: p.weeklyPlans.map((w) => ({
          weekNumber: w.weekNumber,
          focus: w.focus,
          objectives: w.objectives,
          actionItems: w.actionItems.map((a) => ({
            id: crypto.randomUUID(),
            title: a.title,
            description: a.description,
            type: a.type,
            estimatedHours: a.estimatedHours,
            completed: false,
          })),
        })),
      }));

      const roadmap: CareerRoadmap = {
        id: crypto.randomUUID(),
        userId,
        goalId,
        targetRole,
        ...(targetCompany ? { targetCompany } : {}),
        timelineWeeks,
        phases,
        skillsToAcquire: missingSkills.map((s) => ({
          skill: s,
          priority: "high",
          currentLevel: 0.2,
          targetLevel: 0.8,
          resources: [`Study materials for ${s}`],
        })),
        certificationsSuggested: suggestedCertifications,
        projectsRecommended: recommendedProjects,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };

      // ─── Save in CareerTwin ───
      const twin = await AgentMemory.getOrCreateTwin(userId);
      await prisma.careerTwin.update({
        where: { id: twin.id },
        data: {
          activePlan: roadmap as any,
          status: "active",
        },
      });

      // ─── Save in RoadmapSnapshot ───
      // Format the lists for sevenDayPlan, fourteenDayPlan, etc.
      const getPlanForDays = (days: number) => {
        const weeks = Math.ceil(days / 7);
        const plans: string[] = [];
        for (const phase of phases) {
          for (const week of phase.weeklyPlans) {
            if (week.weekNumber <= weeks) {
              plans.push(...week.objectives);
            }
          }
        }
        return plans.slice(0, 10);
      };

      await prisma.roadmapSnapshot.create({
        data: {
          userId,
          roleTitle: targetRole,
          companyName: targetCompany || null,
          sourceWeaknesses: missingSkills,
          sevenDayPlan: getPlanForDays(7),
          fourteenDayPlan: getPlanForDays(14),
          thirtyDayPlan: getPlanForDays(30),
          ninetyDayPlan: getPlanForDays(90),
        },
      });

      // ─── Save in PreparationRoadmap ───
      await prisma.preparationRoadmap.create({
        data: {
          userId,
          roleTitle: targetRole,
          companyName: targetCompany || null,
          sevenDaysPlan: getPlanForDays(7),
          fourteenDaysPlan: getPlanForDays(14),
          thirtyDaysPlan: getPlanForDays(30),
        },
      });

      return roadmap;
    } catch (err) {
      logger.error({ err, userId }, "[CareerRoadmapGenerator] Generation failed, using default fallback");

      const defaultRoadmap: CareerRoadmap = {
        id: crypto.randomUUID(),
        userId,
        goalId,
        targetRole,
        ...(targetCompany ? { targetCompany } : {}),
        timelineWeeks,
        phases: fallbackPhases,
        skillsToAcquire: missingSkills.map((s) => ({
          skill: s,
          priority: "medium",
          currentLevel: 0.2,
          targetLevel: 0.8,
          resources: [],
        })),
        certificationsSuggested: suggestedCertifications,
        projectsRecommended: recommendedProjects,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };

      return defaultRoadmap;
    }
  }
}

/**
 * lib/agent/tools.ts
 *
 * Tool Execution Framework for the Autonomous Career Agent.
 * Integrates directly with CareerOS schemas and services.
 */

import { prisma } from "@/lib/db/prisma";
import { logger } from "@/lib/logger";
import { geminiJSON } from "@/lib/ai/core";
import { z } from "zod";
import type { AgentToolType, AgentToolResult } from "./types";

export class AgentToolbox {
  /**
   * Dispatches a tool name and parameters to the correct execution handler.
   */
  static async executeTool(
    userId: string,
    toolName: AgentToolType,
    params: Record<string, any>
  ): Promise<AgentToolResult> {
    logger.info({ userId, toolName, params }, "[AgentToolbox] Executing tool...");
    try {
      let output: any;

      switch (toolName) {
        case "analyze_profile":
          output = await this.analyzeProfile(userId);
          break;
        case "analyze_missing_skills":
          output = await this.analyzeMissingSkills(userId, params.targetRole, params.currentSkills);
          break;
        case "suggest_certifications":
          output = await this.suggestCertifications(userId, params.missingSkills);
          break;
        case "recommend_projects":
          output = await this.recommendProjects(userId, params.targetRole, params.missingSkills);
          break;
        case "suggest_networking_targets":
          output = await this.suggestNetworkingTargets(userId, params.targetCompany);
          break;
        case "recommend_jobs":
          output = await this.recommendJobs(userId, params.targetRole, params.targetCompany);
          break;
        case "dispatch_notifications":
          output = await this.dispatchNotifications(userId, params.title, params.description, params.category, params.actionUrl);
          break;
        default:
          throw new Error(`Unknown tool: ${toolName}`);
      }

      return {
        toolName,
        success: true,
        output,
      };
    } catch (err) {
      const errMsg = err instanceof Error ? err.message : String(err);
      logger.error({ userId, toolName, err }, "[AgentToolbox] Tool execution failed");
      return {
        toolName,
        success: false,
        output: null,
        error: errMsg,
      };
    }
  }

  // ─── Tool implementations ───────────────────────────────────────────────────

  private static async analyzeProfile(userId: string) {
    const resume = await prisma.resume.findFirst({
      where: { userId },
      orderBy: { updatedAt: "desc" },
    });
    const resumeData = (resume?.data as Record<string, any>) ?? {};
    const skills = (resumeData.skills as string[]) ?? [];
    const experienceCount = ((resumeData.experience as any[]) ?? []).length;
    const projectCount = ((resumeData.projects as any[]) ?? []).length;

    return {
      hasResume: !!resume,
      resumeTitle: resume?.title ?? null,
      currentSkills: skills,
      experienceCount,
      projectCount,
    };
  }

  private static async analyzeMissingSkills(
    userId: string,
    targetRole: string,
    currentSkills: string[]
  ) {
    // 1. Check existing SkillGapAnalysis
    const existing = await prisma.skillGapAnalysis.findUnique({
      where: { userId_targetRole: { userId, targetRole } },
    });

    if (existing) {
      return {
        gapSkills: (existing.gapSkills as any[]).map((s) => s.name || s.skill || s),
        estimatedWeeks: existing.estimatedWeeks,
      };
    }

    // 2. Compute via LLM if none exists
    const schema = z.object({
      gapSkills: z.array(z.string()),
      estimatedWeeks: z.number(),
    });

    const systemPrompt = `You are a career gap intelligence engine. Compare the user's current skills to the target role. List the missing skills they must learn. Estimating weeks to cover these gaps.`;
    const userPrompt = `Target Role: ${targetRole}\nCurrent Skills: ${currentSkills.join(", ")}`;

    const response = await geminiJSON({
      system: systemPrompt,
      user: userPrompt,
      fallback: { gapSkills: ["System Design", "Distributed Caching"], estimatedWeeks: 12 },
      schema,
    });

    // Save it
    await prisma.skillGapAnalysis.upsert({
      where: { userId_targetRole: { userId, targetRole } },
      create: {
        userId,
        targetRole,
        currentSkills: currentSkills.map((s) => ({ name: s, level: 0.8 })),
        requiredSkills: response.gapSkills.map((s) => ({ name: s, level: 0.8 })),
        gapSkills: response.gapSkills.map((s) => ({ name: s, marketDemandScore: 8 })),
        estimatedWeeks: response.estimatedWeeks,
      },
      update: {
        gapSkills: response.gapSkills.map((s) => ({ name: s, marketDemandScore: 8 })),
        estimatedWeeks: response.estimatedWeeks,
      },
    });

    return response;
  }

  private static async suggestCertifications(userId: string, missingSkills: string[]) {
    if (!missingSkills || missingSkills.length === 0) {
      return [];
    }

    const schema = z.object({
      suggestions: z.array(
        z.object({
          name: z.string(),
          issuer: z.string(),
          difficulty: z.enum(["beginner", "intermediate", "advanced"]),
          estimatedWeeks: z.number(),
          url: z.string().optional(),
        })
      ),
    });

    const systemPrompt = `Suggest widely recognized industry certifications for the following missing skills. Ensure they are specific and useful for CV boost.`;
    const userPrompt = `Missing Skills: ${missingSkills.join(", ")}`;

    const result = await geminiJSON({
      system: systemPrompt,
      user: userPrompt,
      fallback: {
        suggestions: [
          { name: "AWS Certified Developer", issuer: "Amazon Web Services", difficulty: "intermediate", estimatedWeeks: 6 },
        ],
      },
      schema,
    });

    return result.suggestions;
  }

  private static async recommendProjects(
    userId: string,
    targetRole: string,
    missingSkills: string[]
  ) {
    const schema = z.object({
      projects: z.array(
        z.object({
          title: z.string(),
          description: z.string(),
          techStack: z.array(z.string()),
          difficulty: z.string(),
          expectedImpact: z.string(),
        })
      ),
    });

    const systemPrompt = `Generate 2 high-impact side project ideas to demonstrate competency in target role and close missing skills gaps. Specify features, tech stack, and what it proves.`;
    const userPrompt = `Target Role: ${targetRole}\nMissing Skills: ${missingSkills.join(", ")}`;

    const result = await geminiJSON({
      system: systemPrompt,
      user: userPrompt,
      fallback: {
        projects: [
          {
            title: "Distributed Task Scheduler",
            description: "High-performance job queue supporting delayed triggers.",
            techStack: ["Rust", "Redis", "gRPC"],
            difficulty: "Advanced",
            expectedImpact: "Proves systems engineering, concurrency, and caching depth.",
          },
        ],
      },
      schema,
    });

    return result.projects;
  }

  private static async suggestNetworkingTargets(userId: string, targetCompany?: string) {
    // Look up target contacts in the hiring contacts or return generic roles to target
    const contacts = await prisma.hiringContact.findMany({
      where: targetCompany
        ? { company: { contains: targetCompany, mode: "insensitive" } }
        : {},
      take: 3,
    });

    if (contacts.length > 0) {
      return contacts.map((c) => ({
        name: c.name,
        title: c.title,
        company: c.company,
        linkedinUrl: c.linkedinUrl,
      }));
    }

    // Fallback: list target profiles to look for on LinkedIn
    const targetRoles = ["Engineering Manager", "Technical Recruiter", "Staff Software Engineer"];
    return targetRoles.map((role) => ({
      name: "LinkedIn Target Profile",
      title: role,
      company: targetCompany || "Target Tech Companies",
      linkedinUrl: `https://www.linkedin.com/search/results/people/?keywords=${encodeURIComponent(
        `${role} ${targetCompany || ""}`
      )}`,
    }));
  }

  private static async recommendJobs(
    userId: string,
    targetRole: string,
    targetCompany?: string
  ) {
    // Search existing job opportunities matching role
    const jobs = await prisma.jobOpportunity.findMany({
      where: {
        OR: [
          { role: { contains: targetRole, mode: "insensitive" } },
          targetCompany ? { company: { contains: targetCompany, mode: "insensitive" } } : {},
        ],
      },
      orderBy: { matchScore: "desc" },
      take: 5,
    });

    return jobs.map((j) => ({
      id: j.id,
      company: j.company,
      role: j.role,
      location: j.location,
      salaryRange: j.salaryRange,
      matchScore: j.matchScore,
      sourceUrl: j.sourceUrl,
    }));
  }

  private static async dispatchNotifications(
    userId: string,
    title: string,
    description: string,
    category: string,
    actionUrl: string
  ) {
    const notification = await prisma.actionFeedItem.create({
      data: {
        userId,
        priority: 10, // high priority for agent activities
        title,
        description,
        actionUrl,
        category, // e.g. "INTERVIEW_PREP"
      },
    });

    return {
      notificationId: notification.id,
      dispatched: true,
    };
  }
}

