export type AgentAutonomyMode = "manual" | "assisted" | "autonomous";

export interface AgentGoal {
  id: string;
  userId: string;
  rawInput: string;
  targetRole: string;
  targetCompany?: string;
  timelineMonths: number;
  salaryTarget?: {
