import { ResumeData } from "@/lib/storage";
import { normalizeResume } from "./normalizeResume";

export function extractKeywords(text: string): string[] {
  if (!text) return [];

  const words = text
    .toLowerCase()
    .replace(/[^\w\s]/g, " ")
    .split(/\s+/);

  const stopWords = new Set([
    "and", "the", "with", "for", "a", "an", "to", "of", "in", "is", "at", "by", "from",
    "or", "as", "be", "this", "that", "are", "it", "will", "your", "we", "you", "our",
    "have", "not", "but", "what", "all", "were", "when", "can", "if", "their"
  ]);

  return Array.from(
    new Set(words.filter(w => w.length >= 3 && !stopWords.has(w)))
  );
}

export function matchKeywords(resume: ResumeData, jobDescription: string) {
  const safe = normalizeResume(resume);

  const resumeText = [
    safe.personal?.summary || "",
    ...safe.skills,
    ...safe.experience.map(e => `${e.role} ${e.company} ${e.points}`)
  ].join(" ");

  const resumeKeywords = new Set(extractKeywords(resumeText));
  const jobKeywords = extractKeywords(jobDescription);

  if (jobKeywords.length === 0) {
    return { matched: [], missing: [], percentage: 0 };
  }

  const matched: string[] = [];
  const missing: string[] = [];

  jobKeywords.forEach(kw => {
    resumeKeywords.has(kw) ? matched.push(kw) : missing.push(kw);
  });

  return {
    matched,
    missing,
    percentage: Math.round((matched.length / jobKeywords.length) * 100)
  };
}

export function calculateLocalATSScore(resume: ResumeData, jobDescription?: string) {
  const r = normalizeResume(resume);

  let score = 100;
  const suggestions: string[] = [];

  if (!r.personal?.summary?.trim()) {
    score -= 10;
    suggestions.push("Add a professional summary.");
  }

  if (r.experience.length === 0) {
    score -= 20;
    suggestions.push("Add work experience.");
  }

  if (r.skills.length < 3) {
    score -= 10;
    suggestions.push("Add more skills.");
  }

  if (r.education.length === 0) {
    score -= 10;
    suggestions.push("Add education.");
  }

  const expText = r.experience
    .map(e => `${e.role} ${e.company} ${e.points}`)
    .join(" ");

  if (/\d+%?/.test(expText)) {
    score += 10;
  } else if (r.experience.length > 0) {
    suggestions.push("Add measurable results (e.g. +30%).");
  }

  if (r.experience.length >= 3) {
    score += 10;
  }

  let keywordMatchData = null;

  if (jobDescription?.trim()) {
    keywordMatchData = matchKeywords(r, jobDescription);

    score += Math.round((keywordMatchData.percentage / 100) * 20);

    if (keywordMatchData.percentage < 50) {
      suggestions.push(`Low keyword match (${keywordMatchData.percentage}%).`);
    } else if (keywordMatchData.percentage >= 80) {
      suggestions.push("Strong keyword alignment.");
    }
  } else {
    suggestions.push("Add job description for better scoring.");
  }

  return {
    score: Math.max(0, Math.min(100, score)),
    suggestions,
    keywordMatchData
  };
}

export async function calculateATSScore(resume: ResumeData, jobDescription?: string) {
  try {
    const response = await fetch("/api/ats", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ resumeData: resume, jobDescription })
    });

    if (!response.ok) throw new Error("API error");

    const data = await response.json();
    console.info("ATS RESPONSE:", data);

    // ✅ SUPPORT BOTH FORMATS (important)
    const result = data.atsResult || data;

    if (
      typeof result?.score === "number" &&
      Array.isArray(result?.suggestions)
    ) {
      return {
        score: Math.max(0, Math.min(100, result.score)),
        suggestions: result.suggestions,
        keywordMatchData: result.keywordMatchData || null
      };
    }

    throw new Error("Invalid AI response");
  } catch (err) {
    console.warn("Fallback ATS:", err);
    return calculateLocalATSScore(resume, jobDescription);
  }
}

import { prisma } from "@/lib/db/prisma";

export async function trackCapture(source: string, metadata: any = {}) {
  if (typeof window !== "undefined") {
    // Client-side: call the email-capture API and set localStorage
    const email = metadata.email;
    if (!email) return;

    try {
      const res = await fetch("/api/v1/email-capture", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ source, metadata, email }),
      });
      const data = await res.json();
      if (data.success) {
        localStorage.setItem("email_captured", "true");
        localStorage.setItem("captured_email", email);
      }
      return data;
    } catch (error) {
      console.error("[ANALYTICS] Failed to track capture client-side:", error);
      return { success: false, error };
    }
  }
}

export async function trackConversion(email: string, userId: string) {
  if (typeof window === "undefined") {
    // Server-side
    try {
      const existing = await prisma.emailCapture.findUnique({
        where: { email },
      });
      if (existing) {
        await prisma.emailCapture.update({
          where: { email },
          data: {
            convertedAt: new Date(),
            userId: userId,
          },
        });
        console.log(`[ANALYTICS] Converted guest lead: ${email} -> ${userId}`);
      }
    } catch (error) {
      console.error("[ANALYTICS] Failed to track conversion server-side:", error);
    }
  } else {
    // Client-side fallback API call
    try {
      await fetch("/api/v1/email-capture/convert", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, userId }),
      });
    } catch (error) {
      console.error("[ANALYTICS] Failed to track conversion client-side:", error);
    }
  }
}

export async function getCaptureRate() {
  if (typeof window !== "undefined") {
    throw new Error("getCaptureRate can only be called on the server");
  }

  try {
    const totalCaptured = await prisma.emailCapture.count();
    const totalConverted = await prisma.emailCapture.count({
      where: {
        convertedAt: { not: null },
      },
    });

    const rate = totalCaptured > 0 ? (totalConverted / totalCaptured) * 100 : 0;

    // Group by source stats
    const sources = await prisma.emailCapture.groupBy({
      by: ["source"],
      _count: {
        id: true,
      },
    });

    const convertedSources = await prisma.emailCapture.groupBy({
      by: ["source"],
      where: {
        convertedAt: { not: null },
      },
      _count: {
        id: true,
      },
    });

    const sourceStats = sources.map((s) => {
      const total = s._count.id;
      const convRecord = convertedSources.find((cs) => cs.source === s.source);
      const converted = convRecord ? convRecord._count.id : 0;
      return {
        source: s.source,
        total,
        converted,
        rate: total > 0 ? (converted / total) * 100 : 0,
      };
    });

    return {
      totalCaptured,
      totalConverted,
      overallRate: Number(rate.toFixed(2)),
      sourceStats,
    };
  } catch (error) {
    console.error("[ANALYTICS] Failed to compute capture rates:", error);
    return {
      totalCaptured: 0,
      totalConverted: 0,
      overallRate: 0,
      sourceStats: [],
    };
  }
}

/**
 * graph-analytics.service.ts
 * Derives CareerGraphAnalytics from the live graph + raw DB data.
 * Persists a snapshot for historical charting.
 */
import "server-only";
import { prisma } from "@/lib/db/prisma";
import { logger } from "@/lib/logger";
import { GraphService } from "./graph.service";
import type { CareerGraphAnalytics } from "./types";

export class GraphAnalyticsService {
  /**
   * Compute full analytics from graph + supplemental DB tables.
   * Persists a daily snapshot and returns the result.
   */
  static async compute(userId: string): Promise<CareerGraphAnalytics> {
    const [skillNodes, appNodes, offerNodes, gapNodes, goalNodes, salaryNodes, interviewNodes, companyNodes, recruiterNodes] =
      await Promise.all([
        GraphService.getNodesByKind(userId, "SKILL"),
        GraphService.getNodesByKind(userId, "APPLICATION"),
        GraphService.getNodesByKind(userId, "OFFER"),
        GraphService.getNodesByKind(userId, "SKILL_GAP"),
        GraphService.getNodesByKind(userId, "CAREER_GOAL"),
        GraphService.getNodesByKind(userId, "SALARY_TARGET"),
        GraphService.getNodesByKind(userId, "INTERVIEW"),
        GraphService.getNodesByKind(userId, "COMPANY"),
        GraphService.getNodesByKind(userId, "RECRUITER"),
      ]);

    // ── Skill Cloud ─────────────────────────────────────────────────────────
    const gapSkillNames = new Set(
      gapNodes.map((n) => (n.payload as { skill: string }).skill?.toLowerCase())
    );
    const skillCloud = skillNodes.map((n) => {
      const p = n.payload as {
        name: string;
        marketDemand: number;
      };
      return {
        skill: p.name,
        weight: n.weight,
        demand: p.marketDemand ?? 0.5,
        gap: gapSkillNames.has(p.name?.toLowerCase()),
      };
    }).sort((a, b) => b.weight - a.weight).slice(0, 40);

    // ── Application Funnel ───────────────────────────────────────────────────
    const funnel = {
      saved: 0,
      applied: 0,
      interview: 0,
      offer: 0,
      conversionRates: { toInterview: 0, toOffer: 0 },
    };

    // Pull counts from raw DB for accuracy
    const [savedCount, appliedCount, interviewCount, offerCount] = await Promise.all([
      prisma.jobOpportunity.count({ where: { userId } }),
      prisma.application.count({ where: { userId } }),
      prisma.application.count({ where: { userId, status: "interview" } }),
      prisma.application.count({ where: { userId, status: "offer" } }),
    ]);
    funnel.saved = savedCount;
    funnel.applied = appliedCount;
    funnel.interview = interviewCount;
    funnel.offer = offerCount;
    funnel.conversionRates.toInterview = appliedCount > 0 ? interviewCount / appliedCount : 0;
    funnel.conversionRates.toOffer = appliedCount > 0 ? offerCount / appliedCount : 0;

    // ── Salary Progression ───────────────────────────────────────────────────
    const salaryProgression: CareerGraphAnalytics["salaryProgression"] = [];

    // From offers
    for (const n of offerNodes) {
      const p = n.payload as { baseAmount: number; receivedAt: string; currency: string };
      salaryProgression.push({ date: p.receivedAt, amount: p.baseAmount, type: "offer" });
    }

    // From salary targets
    for (const n of salaryNodes) {
      const p = n.payload as { targetBase: number; currency: string };
      salaryProgression.push({ date: new Date().toISOString(), amount: p.targetBase, type: "target" });
    }

    // Market data from benchmarks
    const benchmarks = await prisma.anonymousBenchmark.findMany({ take: 1 });
    const benchmark = benchmarks[0];
    if (benchmark) {
      salaryProgression.push({
        date: new Date().toISOString(),
        amount: benchmark.avgDaysToOffer * 5000, // approximation
        type: "market",
      });
    }

    salaryProgression.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    // ── Skill Gap Heatmap ────────────────────────────────────────────────────
    const skillGapHeatmap = gapNodes.map((n) => {
      const p = n.payload as {
        skill: string;
        currentLevel: number;
        requiredLevel: number;
        priority: number;
      };
      return {
        skill: p.skill,
        current: p.currentLevel,
        required: p.requiredLevel,
        priority: p.priority,
      };
    }).sort((a, b) => b.priority - a.priority).slice(0, 20);

    // ── Career Velocity ──────────────────────────────────────────────────────
    const fourWeeksAgo = new Date(Date.now() - 28 * 24 * 60 * 60 * 1000);
    const recentApps = await prisma.application.count({
      where: { userId, createdAt: { gte: fourWeeksAgo } },
    });
    const recentInterviews = await prisma.interviewMockSession.count({
      where: { userId, status: "completed", createdAt: { gte: fourWeeksAgo } },
    });

    const prevMonthApps = await prisma.application.count({
      where: {
        userId,
        createdAt: {
          gte: new Date(Date.now() - 56 * 24 * 60 * 60 * 1000),
          lt: fourWeeksAgo,
        },
      },
    });

    const trend: "accelerating" | "steady" | "slowing" =
      recentApps > prevMonthApps * 1.15
        ? "accelerating"
        : recentApps < prevMonthApps * 0.85
        ? "slowing"
        : "steady";

    const careerVelocity = {
      applicationsPerWeek: recentApps / 4,
      interviewsPerMonth: recentInterviews,
      offersReceived: offerNodes.length,
      trend,
    };

    // ── Network Strength ─────────────────────────────────────────────────────
    const recruiterInteractionCount = await prisma.recruiterInteraction.count({ where: { userId } });
    const avgTrust =
      recruiterNodes.length > 0
        ? recruiterNodes.reduce((s, n) => s + ((n.payload as { trustScore: number }).trustScore ?? 0.5), 0) /
          recruiterNodes.length
        : 0;

    const networkStrength = {
      totalRecruiters: recruiterInteractionCount,
      activeCompanies: companyNodes.length,
      avgRecruiterTrustScore: parseFloat(avgTrust.toFixed(2)),
    };

    // ── Goal Progress ────────────────────────────────────────────────────────
    const goalProgress = goalNodes.map((n) => {
      const p = n.payload as { targetRole: string; status: string };
      return {
        goal: p.targetRole,
        progress: n.weight * 100,
        status: p.status ?? "active",
      };
    });

    const analytics: CareerGraphAnalytics = {
      skillCloud,
      applicationFunnel: funnel,
      salaryProgression,
      skillGapHeatmap,
      careerVelocity,
      networkStrength,
      goalProgress,
    };

    // Persist daily snapshot
    await this._persistSnapshot(userId, analytics);

    return analytics;
  }

  /**
   * Get historical snapshots for trend charting (last N days).
   */
  static async getHistory(userId: string, days = 30): Promise<
    Array<{ date: string; completenessScore: number; nodeCount: number; edgeCount: number }>
  > {
    const cutoff = new Date(Date.now() - days * 24 * 60 * 60 * 1000);
    const snapshots = await prisma.careerGraphSnapshot.findMany({
      where: { userId, snapshotDate: { gte: cutoff } },
      orderBy: { snapshotDate: "asc" },
    });

    return snapshots.map((s) => ({
      date: s.snapshotDate.toISOString(),
      completenessScore: s.completenessScore,
      nodeCount: s.nodeCount,
      edgeCount: s.edgeCount,
    }));
  }

  // ─── Internal ───────────────────────────────────────────────────────────────

  private static async _persistSnapshot(
    userId: string,
    analytics: CareerGraphAnalytics
  ): Promise<void> {
    try {
      const meta = await prisma.careerGraphMeta.findUnique({ where: { userId } });
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      await prisma.careerGraphSnapshot.upsert({
        where: { userId_snapshotDate: { userId, snapshotDate: today } },
        create: {
          userId,
          snapshotDate: today,
          graphVersion: meta?.graphVersion ?? 0,
          analytics: analytics as object,
          completenessScore: meta?.completenessScore ?? 0,
          nodeCount: meta?.totalNodes ?? 0,
          edgeCount: meta?.totalEdges ?? 0,
        },
        update: {
          analytics: analytics as object,
          completenessScore: meta?.completenessScore ?? 0,
          nodeCount: meta?.totalNodes ?? 0,
          edgeCount: meta?.totalEdges ?? 0,
        },
      });
    } catch (err) {
      logger.warn({ userId, err }, "[GraphAnalyticsService] Failed to persist snapshot");
    }
  }
}

/**
 * graph-builder.service.ts
 * Extracts graph nodes/edges from existing CareerOS data.
 * Called whenever a resume is uploaded, a job applied, etc.
 */
import "server-only";
import { prisma } from "@/lib/db/prisma";
import { logger } from "@/lib/logger";
import { GraphService } from "./graph.service";
import type { GraphNodeKind, GraphEdgeKind, GraphUpdateTrigger } from "./types";

// ─── Resume → Graph ───────────────────────────────────────────────────────────

async function buildFromResume(userId: string, resumeId: string): Promise<void> {
  const resume = await prisma.resume.findUnique({
    where: { id: resumeId, userId },
  });
  if (!resume) return;

  const data = resume.data as Record<string, unknown>;

  // Deactivate old nodes from this resume source
  await GraphService.deactivateBySource(userId, resumeId, "Resume");

  // ── Skills ──────────────────────────────────────────────────────────────────
  const skills = (data.skills as string[]) ?? [];
  const skillNodeIds: string[] = [];
  for (const skill of skills) {
    const nodeId = await GraphService.upsertNode(
      userId,
      "SKILL" as GraphNodeKind,
      skill,
      {
        name: skill,
        category: "general",
        proficiencyLevel: 0.6,
        yearsOfExperience: 0,
        lastUsed: null,
        marketDemand: 0.5,
        isVerified: false,
        sources: ["resume"],
      },
      { weight: 0.7, confidence: 0.8, sourceEntityId: resumeId, sourceEntityType: "Resume" }
    );
    skillNodeIds.push(nodeId);
  }

  // ── Experience ──────────────────────────────────────────────────────────────
  const experiences = (data.experience as Array<Record<string, unknown>>) ?? [];
  for (const exp of experiences) {
    const label = `${exp.title as string} @ ${exp.company as string}`;
    const expNodeId = await GraphService.upsertNode(
      userId,
      "EXPERIENCE" as GraphNodeKind,
      label,
      {
        company: exp.company as string,
        role: exp.title as string,
        startDate: exp.startDate as string,
        endDate: (exp.endDate as string) ?? null,
        isCurrent: !exp.endDate,
        location: (exp.location as string) ?? null,
        description: (exp.description as string) ?? "",
        achievements: (exp.achievements as string[]) ?? [],
        teamSize: null,
        skills: (exp.skills as string[]) ?? [],
      },
      { weight: 0.9, confidence: 0.85, sourceEntityId: resumeId, sourceEntityType: "Resume" }
    );

    // Company node
    if (exp.company) {
      const companyNodeId = await GraphService.upsertNode(
        userId,
        "COMPANY" as GraphNodeKind,
        exp.company as string,
        {
          name: exp.company as string,
          domain: null,
          industry: null,
          tier: null,
          hiringStatus: "unknown",
          trustScore: 0.5,
        },
        { weight: 0.6, confidence: 0.6 }
      );
      await GraphService.upsertEdge(userId, expNodeId, companyNodeId, "WORKED_AT" as GraphEdgeKind, { weight: 1 });
    }

    // Experience → Skills edges
    const expSkills = (exp.skills as string[]) ?? [];
    for (const skill of expSkills) {
      const sNodeId = await GraphService.upsertNode(
        userId,
        "SKILL" as GraphNodeKind,
        skill,
        {
          name: skill,
          category: "general",
          proficiencyLevel: 0.7,
          yearsOfExperience: 0,
          lastUsed: null,
          marketDemand: 0.5,
          isVerified: false,
          sources: ["resume", "experience"],
        },
        { weight: 0.7, confidence: 0.8, sourceEntityId: resumeId, sourceEntityType: "Resume" }
      );
      await GraphService.upsertEdge(userId, expNodeId, sNodeId, "USED_IN" as GraphEdgeKind, { weight: 0.8 });
    }
  }

  // ── Projects ────────────────────────────────────────────────────────────────
  const projects = (data.projects as Array<Record<string, unknown>>) ?? [];
  for (const proj of projects) {
    const projectNodeId = await GraphService.upsertNode(
      userId,
      "PROJECT" as GraphNodeKind,
      (proj.name as string) ?? "Untitled Project",
      {
        name: (proj.name as string) ?? "Untitled Project",
        description: (proj.description as string) ?? "",
        techStack: (proj.technologies as string[]) ?? [],
        url: (proj.url as string) ?? null,
        impact: (proj.impact as string) ?? null,
        startDate: (proj.startDate as string) ?? null,
        endDate: (proj.endDate as string) ?? null,
      },
      { weight: 0.75, confidence: 0.8, sourceEntityId: resumeId, sourceEntityType: "Resume" }
    );

    // Project → Skills edges
    const techStack = (proj.technologies as string[]) ?? [];
    for (const tech of techStack) {
      const sNodeId = await GraphService.upsertNode(
        userId,
        "SKILL" as GraphNodeKind,
        tech,
        {
          name: tech,
          category: "technical",
          proficiencyLevel: 0.6,
          yearsOfExperience: 0,
          lastUsed: null,
          marketDemand: 0.5,
          isVerified: false,
          sources: ["resume", "project"],
        },
        { weight: 0.6, confidence: 0.75, sourceEntityId: resumeId, sourceEntityType: "Resume" }
      );
      await GraphService.upsertEdge(userId, projectNodeId, sNodeId, "BUILT" as GraphEdgeKind, { weight: 0.7 });
    }
  }

  // ── Education ───────────────────────────────────────────────────────────────
  const education = (data.education as Array<Record<string, unknown>>) ?? [];
  for (const edu of education) {
    await GraphService.upsertNode(
      userId,
      "EDUCATION" as GraphNodeKind,
      `${edu.degree as string} @ ${edu.school as string}`,
      {
        institution: edu.school as string,
        degree: edu.degree as string,
        field: (edu.field as string) ?? "",
        gpa: (edu.gpa as number) ?? null,
        startYear: parseInt(edu.startYear as string) || 2020,
        endYear: edu.endYear ? parseInt(edu.endYear as string) : null,
        achievements: (edu.achievements as string[]) ?? [],
      },
      { weight: 0.6, confidence: 0.9, sourceEntityId: resumeId, sourceEntityType: "Resume" }
    );
  }
}

// ─── Application → Graph ──────────────────────────────────────────────────────

async function buildFromApplication(userId: string, applicationId: string): Promise<void> {
  const app = await prisma.application.findUnique({
    where: { id: applicationId, userId },
    include: { jobOpportunity: true },
  });
  if (!app) return;

  const appNodeId = await GraphService.upsertNode(
    userId,
    "APPLICATION" as GraphNodeKind,
    `${app.role} @ ${app.company}`,
    {
      company: app.company,
      role: app.role,
      status: app.status as "applied" | "interview" | "offer" | "rejected",
      appliedAt: (app.appliedAt ?? app.createdAt).toISOString(),
      source: app.jobOpportunity?.sourceUrl ?? null,
      matchScore: app.matchScore,
      jobOpportunityId: app.jobOpportunityId ?? null,
    },
    { weight: 0.8, confidence: 0.95, sourceEntityId: applicationId, sourceEntityType: "Application" }
  );

  // Company node
  const companyNodeId = await GraphService.upsertNode(
    userId,
    "COMPANY" as GraphNodeKind,
    app.company,
    {
      name: app.company,
      domain: null,
      industry: null,
      tier: null,
      hiringStatus: "unknown",
      trustScore: 0.5,
    },
    { weight: 0.6, confidence: 0.7 }
  );

  await GraphService.upsertEdge(userId, appNodeId, companyNodeId, "APPLIED_TO" as GraphEdgeKind, { weight: 0.9 });

  // Job match node if we have a job opportunity
  if (app.jobOpportunity) {
    const jd = app.jobOpportunity;
    const matchNodeId = await GraphService.upsertNode(
      userId,
      "JOB_MATCH" as GraphNodeKind,
      `Match: ${jd.role} @ ${jd.company}`,
      {
        jobOpportunityId: jd.id,
        company: jd.company,
        role: jd.role,
        matchScore: jd.matchScore,
        matchedAt: jd.createdAt.toISOString(),
        missingSkills: [],
        matchedSkills: [],
      },
      { weight: 0.7, confidence: 0.85, sourceEntityId: jd.id, sourceEntityType: "JobOpportunity" }
    );
    await GraphService.upsertEdge(userId, appNodeId, matchNodeId, "MATCHED_TO" as GraphEdgeKind, {
      weight: jd.matchScore / 100,
    });
  }
}

// ─── Interview → Graph ────────────────────────────────────────────────────────

async function buildFromInterview(userId: string, sessionId: string, outcome: string): Promise<void> {
  const session = await prisma.interviewMockSession.findUnique({
    where: { id: sessionId, userId },
    include: { company: true },
  });
  if (!session) return;

  const companyName = session.company?.name ?? "Unknown";

  const interviewNodeId = await GraphService.upsertNode(
    userId,
    "INTERVIEW" as GraphNodeKind,
    `Interview: ${session.roleTitle} @ ${companyName}`,
    {
      company: companyName,
      role: session.roleTitle,
      roundType: session.mode,
      scheduledAt: session.startedAt.toISOString(),
      completedAt: session.completedAt?.toISOString() ?? null,
      outcome: outcome as "passed" | "failed" | "pending" | "cancelled",
      feedback: null,
      score: (session.scores as Record<string, unknown>)?.overall as number ?? null,
    },
    { weight: 0.85, confidence: 0.9, sourceEntityId: sessionId, sourceEntityType: "InterviewMockSession" }
  );

  // Link interview to company
  const companyNodeId = await GraphService.upsertNode(
    userId,
    "COMPANY" as GraphNodeKind,
    companyName,
    {
      name: companyName,
      domain: null,
      industry: null,
      tier: null,
      hiringStatus: "unknown",
      trustScore: 0.5,
    },
    { weight: 0.5, confidence: 0.6 }
  );

  await GraphService.upsertEdge(userId, interviewNodeId, companyNodeId, "INTERVIEWED_AT" as GraphEdgeKind, { weight: 0.9 });
}

// ─── SkillGap → Graph ─────────────────────────────────────────────────────────

async function buildFromSkillGaps(userId: string): Promise<void> {
  const gaps = await prisma.skillGapAnalysis.findMany({
    where: { userId },
    orderBy: { updatedAt: "desc" },
    take: 10,
  });

  for (const gap of gaps) {
    const gapSkills = (gap.gapSkills as Array<Record<string, unknown>>) ?? [];
    for (const g of gapSkills) {
      const skillName = g.name as string;
      if (!skillName) continue;
      await GraphService.upsertNode(
        userId,
        "SKILL_GAP" as GraphNodeKind,
        `Gap: ${skillName} for ${gap.targetRole}`,
        {
          skill: skillName,
          targetRole: gap.targetRole,
          currentLevel: (g.currentLevel as number) ?? 0.2,
          requiredLevel: (g.requiredLevel as number) ?? 0.8,
          priority: (g.marketDemandScore as number) ?? 0.5,
          marketDemand: (g.marketDemandScore as number) ?? 0.5,
          estimatedWeeks: gap.estimatedWeeks,
          status: "open",
        },
        { weight: 0.8, confidence: 0.8, sourceEntityId: gap.id, sourceEntityType: "SkillGapAnalysis" }
      );
    }
  }
}

// ─── Negotiation / Offer → Graph ─────────────────────────────────────────────

async function buildFromOffers(userId: string): Promise<void> {
  const negotiations = await prisma.negotiationSession.findMany({
    where: { userId },
    orderBy: { createdAt: "desc" },
    take: 20,
  });

  for (const neg of negotiations) {
    const offerNodeId = await GraphService.upsertNode(
      userId,
      "OFFER" as GraphNodeKind,
      `Offer: ${neg.jobTitle} @ ${neg.companyName}`,
      {
        company: neg.companyName,
        role: neg.jobTitle,
        baseAmount: neg.offerBase,
        totalCtc: neg.finalOffer ?? neg.offerBase,
        currency: neg.currency,
        receivedAt: neg.createdAt.toISOString(),
        expiresAt: null,
        status: neg.outcome === "accepted" ? "accepted" : neg.outcome === "rejected" ? "rejected" : "pending",
      },
      { weight: 0.9, confidence: 0.95, sourceEntityId: neg.id, sourceEntityType: "NegotiationSession" }
    );

    const companyNodeId = await GraphService.upsertNode(
      userId,
      "COMPANY" as GraphNodeKind,
      neg.companyName,
      {
        name: neg.companyName,
        domain: null,
        industry: null,
        tier: null,
        hiringStatus: "unknown",
        trustScore: 0.5,
      },
      { weight: 0.6, confidence: 0.6 }
    );

    await GraphService.upsertEdge(userId, offerNodeId, companyNodeId, "OFFERED_BY" as GraphEdgeKind, { weight: 0.95 });
  }
}

// ─── CareerProfile → Goal + Salary nodes ─────────────────────────────────────

async function buildFromCareerProfile(userId: string): Promise<void> {
  const profile = await prisma.careerProfile.findUnique({ where: { userId } });
  if (!profile) return;

  // Career Goals
  let goalsArray: Array<Record<string, any>> = [];
  if (Array.isArray(profile.goals)) {
    goalsArray = profile.goals as Array<Record<string, any>>;
  } else if (profile.goals && typeof profile.goals === "object") {
    const g = profile.goals as Record<string, any>;
    if (g.targetRoles && Array.isArray(g.targetRoles)) {
      goalsArray = g.targetRoles.map(role => ({
        targetRole: role,
        targetCompany: Array.isArray(g.targetCompanies) && g.targetCompanies.length > 0 ? g.targetCompanies[0] : (g.targetCompany ?? null),
        timeline: g.timeline ?? null,
        priority: 0.8,
      }));
    } else {
      goalsArray = [g];
    }
  }

  for (const goal of goalsArray) {
    const targetRole = (goal.targetRole as string) ?? "";
    await GraphService.upsertNode(
      userId,
      "CAREER_GOAL" as GraphNodeKind,
      (goal.title as string) ?? `Goal: ${targetRole}`,
      {
        targetRole,
        targetCompany: (goal.targetCompany as string) ?? null,
        targetIndustry: (goal.targetIndustry as string) ?? null,
        timeline: (goal.timeline as string) ?? null,
        priority: (goal.priority as number) ?? 0.5,
        status: "active",
      },
      { weight: 0.85, confidence: 0.9, sourceEntityId: profile.id, sourceEntityType: "CareerProfile" }
    );
  }

  // Salary target
  const salary = profile.salaryExpectation as Record<string, unknown>;
  if (salary) {
    await GraphService.upsertNode(
      userId,
      "SALARY_TARGET" as GraphNodeKind,
      `Salary Target: ${salary.currency ?? "INR"} ${salary.targetBase ?? 0}`,
      {
        targetBase: (salary.targetBase as number) ?? 0,
        targetTotal: (salary.targetTotal as number) ?? 0,
        currency: (salary.currency as string) ?? "INR",
        timeline: (salary.timeline as string) ?? null,
        marketMin: (salary.marketMin as number) ?? null,
        marketMax: (salary.marketMax as number) ?? null,
        marketMedian: (salary.marketMedian as number) ?? null,
      },
      { weight: 0.8, confidence: 0.85, sourceEntityId: profile.id, sourceEntityType: "CareerProfile" }
    );
  }
}

// ─── Main Dispatcher ──────────────────────────────────────────────────────────

export class GraphBuilderService {
  /**
   * React to a platform event and update the Career Graph accordingly.
   * Always recomputes meta after mutations.
   */
  static async handleTrigger(userId: string, trigger: GraphUpdateTrigger): Promise<void> {
    try {
      switch (trigger.type) {
        case "RESUME_UPLOADED":
        case "RESUME_EDITED":
          await buildFromResume(userId, trigger.payload.resumeId);
          break;
        case "JOB_SAVED":
          // Handled implicitly when JOB_APPLIED fires; saved jobs update match nodes
          break;
        case "JOB_APPLIED":
          await buildFromApplication(userId, trigger.payload.applicationId);
          break;
        case "INTERVIEW_COMPLETED":
          await buildFromInterview(userId, trigger.payload.sessionId, trigger.payload.outcome);
          break;
        case "SKILL_ADDED":
          await GraphService.upsertNode(
            userId,
            "SKILL" as GraphNodeKind,
            trigger.payload.skill,
            {
              name: trigger.payload.skill,
              category: "general",
              proficiencyLevel: 0.5,
              yearsOfExperience: 0,
              lastUsed: new Date().toISOString(),
              marketDemand: 0.5,
              isVerified: false,
              sources: [trigger.payload.source],
            },
            { weight: 0.7, confidence: 0.85 }
          );
          break;
        case "CERTIFICATION_ADDED":
          await GraphService.upsertNode(
            userId,
            "CERTIFICATION" as GraphNodeKind,
            trigger.payload.certificationData.name,
            trigger.payload.certificationData,
            { weight: 0.8, confidence: 0.95 }
          );
          break;
        case "OFFER_RECEIVED":
          await GraphService.upsertNode(
            userId,
            "OFFER" as GraphNodeKind,
            `Offer: ${trigger.payload.offerData.role} @ ${trigger.payload.offerData.company}`,
            trigger.payload.offerData,
            { weight: 0.95, confidence: 0.95 }
          );
          break;
      }
    } catch (err) {
      logger.error({ userId, trigger, err }, "[GraphBuilderService] handleTrigger failed");
    } finally {
      await GraphService.recomputeMeta(userId);
    }
  }

  /**
   * Full graph rebuild from all available data sources.
   * Used on initial signup, on-demand refresh, or after a major data import.
   */
  static async fullRebuild(userId: string): Promise<void> {
    logger.info({ userId }, "[GraphBuilderService] Starting full graph rebuild");

    // Get most recent resume
    const latestResume = await prisma.resume.findFirst({
      where: { userId },
      orderBy: { updatedAt: "desc" },
    });
    if (latestResume) {
      await buildFromResume(userId, latestResume.id);
    }

    // All applications
    const applications = await prisma.application.findMany({
      where: { userId },
      orderBy: { createdAt: "desc" },
      take: 50,
    });
    for (const app of applications) {
      await buildFromApplication(userId, app.id);
    }

    // Completed interview sessions
    const sessions = await prisma.interviewMockSession.findMany({
      where: { userId, status: "completed" },
      orderBy: { createdAt: "desc" },
      take: 20,
    });
    for (const s of sessions) {
      await buildFromInterview(userId, s.id, "completed");
    }

    await buildFromSkillGaps(userId);
    await buildFromOffers(userId);
    await buildFromCareerProfile(userId);
    await GraphService.recomputeMeta(userId);

    logger.info({ userId }, "[GraphBuilderService] Full graph rebuild complete");
  }
}

/**
 * graph.service.ts
 * Core CRUD layer for CareerGraphNode and CareerGraphEdge.
 * All mutations emit a CareerGraphEvent for audit + replay.
 */
import "server-only";
import { prisma } from "@/lib/db/prisma";
import { logger } from "@/lib/logger";
import type {
  GraphNode,
  GraphEdge,
  CareerGraph,
  GraphSummary,
  GraphNodeKind,
  GraphEdgeKind,
  GraphNodePayload,
} from "./types";
import { CareerGraphEventType } from "@prisma/client";

// ─── Type mapping helpers ─────────────────────────────────────────────────────

function toGraphNode(row: {
  id: string;
  userId: string;
  kind: string;
  label: string;
  payload: unknown;
  weight: number;
  confidence: number;
  sourceEntityId: string | null;
  sourceEntityType: string | null;
  createdAt: Date;
  updatedAt: Date;
}): GraphNode {
  return {
    id: row.id,
    userId: row.userId,
    kind: row.kind as GraphNodeKind,
    label: row.label,
    payload: row.payload as GraphNodePayload,
    weight: row.weight,
    confidence: row.confidence,
    sourceEntityId: row.sourceEntityId,
    sourceEntityType: row.sourceEntityType,
    createdAt: row.createdAt.toISOString(),
    updatedAt: row.updatedAt.toISOString(),
  };
}

function toGraphEdge(row: {
  id: string;
  userId: string;
  sourceNodeId: string;
  targetNodeId: string;
  kind: string;
  weight: number;
  metadata: unknown;
  createdAt: Date;
}): GraphEdge {
  return {
    id: row.id,
    userId: row.userId,
    sourceNodeId: row.sourceNodeId,
    targetNodeId: row.targetNodeId,
    kind: row.kind as GraphEdgeKind,
    weight: row.weight,
    metadata: (row.metadata as Record<string, unknown>) ?? {},
    createdAt: row.createdAt.toISOString(),
  };
}

// ─── Graph Service ────────────────────────────────────────────────────────────

export class GraphService {
  /**
   * Fetch the complete Career Graph for a user.
   * Returns nodes + edges ready for visualization.
   */
  static async getGraph(userId: string): Promise<CareerGraph> {
    const [nodes, edges] = await Promise.all([
      prisma.careerGraphNode.findMany({
        where: { userId, isActive: true },
        orderBy: { updatedAt: "desc" },
      }),
      prisma.careerGraphEdge.findMany({
        where: { userId },
        orderBy: { createdAt: "desc" },
      }),
    ]);

    const meta = await prisma.careerGraphMeta.findUnique({ where: { userId } });

    return {
      userId,
      nodes: nodes.map(toGraphNode),
      edges: edges.map(toGraphEdge),
      computedAt: meta?.lastComputedAt.toISOString() ?? new Date().toISOString(),
      version: meta?.graphVersion ?? 0,
    };
  }

  /**
   * Get summary metadata without loading all nodes/edges.
   */
  static async getSummary(userId: string): Promise<GraphSummary> {
    const meta = await prisma.careerGraphMeta.findUnique({ where: { userId } });
    if (!meta) {
      return {
        totalNodes: 0,
        totalEdges: 0,
        nodesByKind: {} as Record<GraphNodeKind, number>,
        edgesByKind: {} as Record<GraphEdgeKind, number>,
        completenessScore: 0,
        lastUpdated: new Date().toISOString(),
      };
    }
    return {
      totalNodes: meta.totalNodes,
      totalEdges: meta.totalEdges,
      nodesByKind: (meta.nodesByKind as Record<GraphNodeKind, number>) ?? {},
      edgesByKind: (meta.edgesByKind as Record<GraphEdgeKind, number>) ?? {},
      completenessScore: meta.completenessScore,
      lastUpdated: meta.lastComputedAt.toISOString(),
    };
  }

  /**
   * Upsert a node — create if no matching sourceEntityId/kind, else update.
   * Returns the canonical node ID.
   */
  static async upsertNode(
    userId: string,
    kind: GraphNodeKind,
    label: string,
    payload: GraphNodePayload,
    opts: {
      weight?: number;
      confidence?: number;
      sourceEntityId?: string;
      sourceEntityType?: string;
    } = {}
  ): Promise<string> {
    const existing = opts.sourceEntityId
      ? await prisma.careerGraphNode.findFirst({
          where: {
            userId,
            kind,
            sourceEntityId: opts.sourceEntityId,
          },
        })
      : await prisma.careerGraphNode.findFirst({
          where: {
            userId,
            kind,
            label,
          },
        });

    if (existing) {
      await prisma.careerGraphNode.update({
        where: { id: existing.id },
        data: {
          label,
          payload: payload as object,
          weight: opts.weight ?? existing.weight,
          confidence: opts.confidence ?? existing.confidence,
          isActive: true,
          updatedAt: new Date(),
        },
      });
      await this._emitEvent(userId, "NODE_UPDATED", { nodeId: existing.id, kind });
      return existing.id;
    }

    const created = await prisma.careerGraphNode.create({
      data: {
        userId,
        kind,
        label,
        payload: payload as object,
        weight: opts.weight ?? 0.5,
        confidence: opts.confidence ?? 0.7,
        sourceEntityId: opts.sourceEntityId ?? null,
        sourceEntityType: opts.sourceEntityType ?? null,
        isActive: true,
      },
    });

    await this._emitEvent(userId, "NODE_ADDED", {
      nodeId: created.id,
      kind,
      sourceEntityId: opts.sourceEntityId,
    });

    return created.id;
  }

  /**
   * Upsert a directed edge between two nodes.
   */
  static async upsertEdge(
    userId: string,
    sourceNodeId: string,
    targetNodeId: string,
    kind: GraphEdgeKind,
    opts: { weight?: number; metadata?: Record<string, unknown> } = {}
  ): Promise<string> {
    const edge = await prisma.careerGraphEdge.upsert({
      where: {
        sourceNodeId_targetNodeId_kind: { sourceNodeId, targetNodeId, kind },
      },
      create: {
        userId,
        sourceNodeId,
        targetNodeId,
        kind,
        weight: opts.weight ?? 0.5,
        metadata: (opts.metadata ?? {}) as object,
      },
      update: {
        weight: opts.weight ?? 0.5,
        metadata: (opts.metadata ?? {}) as object,
      },
    });
    return edge.id;
  }

  /**
   * Soft-delete all nodes sourced from a specific entity (e.g. old resume).
   */
  static async deactivateBySource(
    userId: string,
    sourceEntityId: string,
    sourceEntityType: string
  ): Promise<void> {
    await prisma.careerGraphNode.updateMany({
      where: { userId, sourceEntityId, sourceEntityType },
      data: { isActive: false },
    });
  }

  /**
   * Recompute the CareerGraphMeta aggregate counts after mutations.
   */
  static async recomputeMeta(userId: string): Promise<void> {
    const [nodesByKindRaw, edgesByKindRaw, nodeCount, edgeCount] = await Promise.all([
      prisma.careerGraphNode.groupBy({
        by: ["kind"],
        where: { userId, isActive: true },
        _count: { id: true },
      }),
      prisma.careerGraphEdge.groupBy({
        by: ["kind"],
        where: { userId },
        _count: { id: true },
      }),
      prisma.careerGraphNode.count({ where: { userId, isActive: true } }),
      prisma.careerGraphEdge.count({ where: { userId } }),
    ]);

    const nodesByKind = Object.fromEntries(
      nodesByKindRaw.map((r) => [r.kind, r._count.id])
    );
    const edgesByKind = Object.fromEntries(
      edgesByKindRaw.map((r) => [r.kind, r._count.id])
    );

    // Completeness: score based on presence of key node types
    const requiredKinds = ["SKILL", "EXPERIENCE", "EDUCATION"] as const;
    const optionalKinds = ["PROJECT", "CERTIFICATION", "CAREER_GOAL", "SALARY_TARGET"] as const;
    const hasRequired = requiredKinds.filter((k) => (nodesByKind[k] ?? 0) > 0).length;
    const hasOptional = optionalKinds.filter((k) => (nodesByKind[k] ?? 0) > 0).length;
    const completenessScore = Math.round(
      (hasRequired / requiredKinds.length) * 60 +
        (hasOptional / optionalKinds.length) * 40
    );

    await prisma.careerGraphMeta.upsert({
      where: { userId },
      create: {
        userId,
        totalNodes: nodeCount,
        totalEdges: edgeCount,
        nodesByKind,
        edgesByKind,
        completenessScore,
        graphVersion: 1,
        lastComputedAt: new Date(),
      },
      update: {
        totalNodes: nodeCount,
        totalEdges: edgeCount,
        nodesByKind,
        edgesByKind,
        completenessScore,
        graphVersion: { increment: 1 },
        lastComputedAt: new Date(),
      },
    });

    await this._emitEvent(userId, "GRAPH_RECOMPUTED", {
      nodeCount,
      edgeCount,
      completenessScore,
    });

    logger.info({ userId, nodeCount, edgeCount, completenessScore }, "[GraphService] Meta recomputed");
  }

  /**
   * Get all nodes of a specific kind.
   */
  static async getNodesByKind(userId: string, kind: GraphNodeKind): Promise<GraphNode[]> {
    const rows = await prisma.careerGraphNode.findMany({
      where: { userId, kind, isActive: true },
      orderBy: { weight: "desc" },
    });
    return rows.map(toGraphNode);
  }

  /**
   * Get neighbors of a node (1-hop traversal).
   */
  static async getNeighbors(
    userId: string,
    nodeId: string,
    direction: "outgoing" | "incoming" | "both" = "both"
  ): Promise<{ node: GraphNode; edge: GraphEdge }[]> {
    const edges = await prisma.careerGraphEdge.findMany({
      where: {
        userId,
        ...(direction === "outgoing"
          ? { sourceNodeId: nodeId }
          : direction === "incoming"
          ? { targetNodeId: nodeId }
          : { OR: [{ sourceNodeId: nodeId }, { targetNodeId: nodeId }] }),
      },
      include: {
        sourceNode: true,
        targetNode: true,
      },
    });

    return edges.map((e) => {
      const neighborRow =
        e.sourceNodeId === nodeId ? e.targetNode : e.sourceNode;
      return {
        node: toGraphNode(neighborRow),
        edge: toGraphEdge(e),
      };
    });
  }

  // ─── Internal helpers ───────────────────────────────────────────────────────

  private static async _emitEvent(
    userId: string,
    eventType: keyof typeof CareerGraphEventType,
    payload: Record<string, unknown>
  ): Promise<void> {
    try {
      await prisma.careerGraphEvent.create({
        data: {
          userId,
          eventType: eventType as CareerGraphEventType,
          payload: payload as any,
        },
      });
    } catch (err) {
      logger.warn({ userId, eventType, err }, "[GraphService] Failed to emit event");
    }
  }
}

import { prisma } from "@/lib/db/prisma";

import { getCachedCoachPrompt, setCachedCoachPrompt } from "@/lib/coach/cache";
import { inferCollegeTier } from "@/lib/coach/college-tier";
import { getMarketContextForRole } from "@/lib/coach/market-context";
import {
  assembleContextSections,
  buildMockInterviewAppendix,
  getCoachName,
  personalityBlock,
} from "@/lib/coach/prompts";
import { analyzeRejectionPatterns } from "@/lib/coach/rejection-patterns";
import { computeResumeAbTest } from "@/lib/coach/resume-ab-test";
import type { MockInterviewMetadata } from "@/lib/coach/types";
import { enrichMockMetadataWithCompany } from "@/lib/coach/mock-interview-server";
import { parseMockMetadata } from "@/lib/coach/mock-interview";

function firstName(name: string | null | undefined, email: string): string {
  if (name?.trim()) return name.trim().split(/\s+/)[0]!;
  return email.split("@")[0] ?? "there";
}

function summarizeResume(data: unknown, title: string, version: number): string {
  if (!data || typeof data !== "object") return `${title} (v${version}): no structured data`;
  const d = data as Record<string, unknown>;
  const personal = (d.personal as Record<string, unknown>) ?? {};
  const experience = Array.isArray(d.experience) ? d.experience : [];
  const skills = Array.isArray(d.skills) ? d.skills : [];

  const bullets = experience.slice(0, 3).map((exp) => {
    if (!exp || typeof exp !== "object") return "";
    const e = exp as Record<string, unknown>;
    const points = String(e.points ?? "").slice(0, 200);
    return `- ${e.role ?? "Role"} at ${e.company ?? "Company"}: ${points}`;
  });

  return [
    `${title} (version ${version})`,
    `Headline summary: ${String(personal.summary ?? "").slice(0, 300)}`,
    `Top experience:\n${bullets.filter(Boolean).join("\n") || "none"}`,
    `Skills: ${skills.slice(0, 15).join(", ") || "none listed"}`,
  ].join("\n");
}

function jsonGoals(goals: unknown): { targetRoles: string[]; urgency?: string } {
  if (!goals || typeof goals !== "object" || Array.isArray(goals)) return { targetRoles: [] };
  const g = goals as Record<string, unknown>;
  const roles = Array.isArray(g.targetRoles)
    ? g.targetRoles.map(String)
    : typeof g.targetRole === "string"
      ? [g.targetRole]
      : [];
  const result: { targetRoles: string[]; urgency?: string } = { targetRoles: roles };
  if (typeof g.urgency === "string") result.urgency = g.urgency;
  return result;
}

export async function buildCoachSystemPrompt(
  userId: string,
  sessionOptions?: { mode?: string; metadata?: unknown }
): Promise<string> {
  const cached = await getCachedCoachPrompt(userId);
  const coachName = getCoachName();

  let mockAppendix = "";
  if (sessionOptions?.mode === "mock_interview") {
    let meta = parseMockMetadata(sessionOptions.metadata) ?? {
      phase: "setup" as const,
      questionIndex: 0,
      scores: [],
    };
    meta = await enrichMockMetadataWithCompany(meta);
    mockAppendix = buildMockInterviewAppendix(meta);
  }

  if (cached && !mockAppendix) return cached;

  const [user, careerProfile, resumes, applications, existingInsight] = await Promise.all([
    prisma.user.findUnique({
      where: { id: userId },
      select: { name: true, email: true, plan: true },
    }),
    prisma.careerProfile.findUnique({ where: { userId } }),
    prisma.resume.findMany({
      where: { userId },
      orderBy: { updatedAt: "desc" },
      take: 2,
      select: { id: true, title: true, version: true, data: true },
    }),
    prisma.application.findMany({
      where: { userId },
      orderBy: { updatedAt: "desc" },
      take: 20,
    }),
    prisma.coachInsight.findUnique({ where: { userId } }),
  ]);

  const memories: any[] = [];

  const email = user?.email ?? "user@example.com";
  const userFirstName = firstName(user?.name, email);

  let rejectionAnalysis = existingInsight?.rejection as ReturnType<typeof analyzeRejectionPatterns> | null;
  if (!rejectionAnalysis || typeof rejectionAnalysis !== "object") {
    rejectionAnalysis = analyzeRejectionPatterns(applications);
    await prisma.coachInsight.upsert({
      where: { userId },
      create: {
        userId,
        rejection: rejectionAnalysis as object,
        updatedAt: new Date(),
      },
      update: {
        rejection: rejectionAnalysis as object,
        updatedAt: new Date(),
      },
    });
  }

  const abTests = computeResumeAbTest(
    applications,
    resumes.map((r) => ({ id: r.id, title: r.title, version: r.version }))
  );

  const latestResumeData = resumes[0]?.data;
  const education =
    latestResumeData && typeof latestResumeData === "object"
      ? (latestResumeData as Record<string, unknown>).education
      : null;
  const college = inferCollegeTier(education);

  const goals = jsonGoals(careerProfile?.goals);
  const targetRole = goals.targetRoles[0] ?? null;
  const marketContext = await getMarketContextForRole(targetRole);

  const salary =
    careerProfile?.salaryExpectation && typeof careerProfile.salaryExpectation === "object"
      ? JSON.stringify(careerProfile.salaryExpectation)
      : "Not set";

  const applicationLines = applications
    .slice(0, 20)
    .map(
      (a) =>
        `- ${a.company} / ${a.role}: ${a.status} (match ${a.matchScore}%)${a.appliedAt ? `, applied ${a.appliedAt.toISOString().slice(0, 10)}` : ""}`
    )
    .join("\n");

  const abLines =
    abTests.length > 0
      ? abTests
          .map(
            (r) =>
              `- "${r.resumeTitle}" v${r.version}: ${r.applications} apps, ${Math.round(r.interviewRate * 100)}% interview rate${r.isWinner ? " [BEST PERFORMER]" : ""}`
          )
          .join("\n")
      : "No resume A/B data yet — user hasn't applied with multiple resume versions.";

  const memoryLines =
    memories.length > 0
      ? memories.map((m) => `- [${m.type}] ${m.title}: ${m.content.slice(0, 200)}`).join("\n")
      : "No career memories stored yet.";

  const contextBody = assembleContextSections({
    Profile: [
      `Email: ${email}`,
      `Plan: ${user?.plan ?? "free"}`,
      careerProfile?.headline ? `Headline: ${careerProfile.headline}` : "",
      goals.targetRoles.length ? `Target roles: ${goals.targetRoles.join(", ")}` : "Target roles: not set",
      goals.urgency ? `Job search urgency: ${goals.urgency}` : "",
      `Salary expectation: ${salary}`,
    ]
      .filter(Boolean)
      .join("\n"),
    "Resume versions (latest 2)": resumes.length
      ? resumes.map((r) => summarizeResume(r.data, r.title, r.version)).join("\n\n")
      : "No resumes on file.",
    "Application history (last 20)": applicationLines || "No applications yet.",
    "Rejection pattern analysis": [
      rejectionAnalysis.patternSummary,
      `Rejection rate: ${Math.round(rejectionAnalysis.rejectionRate * 100)}%`,
      `Last 30 days rejections: ${rejectionAnalysis.rejectionsLast30Days}`,
      rejectionAnalysis.likelyCauses.length
        ? `Likely causes: ${rejectionAnalysis.likelyCauses.join("; ")}`
        : "",
      rejectionAnalysis.topRejectedCompanies.length
        ? `Top rejected companies: ${rejectionAnalysis.topRejectedCompanies.map((c) => `${c.company} (${c.count})`).join(", ")}`
        : "",
    ]
      .filter(Boolean)
      .join("\n"),
    "Resume A/B test results": abLines,
    "Education / college tier": `${college.summary}\nSchools: ${college.schools.join(", ") || "unknown"}\nTier: ${college.tier}`,
    "Career memories": memoryLines,
    "Market conditions": marketContext,
  });

  const prompt = `${personalityBlock(coachName, userFirstName)}

Here is everything you know about ${userFirstName}:

${contextBody}
${mockAppendix}`;

  if (!mockAppendix) {
    await setCachedCoachPrompt(userId, prompt);
  }

  return prompt;
}

export async function refreshRejectionInsight(userId: string): Promise<void> {
  const applications = await prisma.application.findMany({
    where: { userId },
    orderBy: { updatedAt: "desc" },
    take: 20,
  });
  const rejectionAnalysis = analyzeRejectionPatterns(applications);
  await prisma.coachInsight.upsert({
    where: { userId },
    create: {
      userId,
      rejection: rejectionAnalysis as object,
      updatedAt: new Date(),
    },
    update: {
      rejection: rejectionAnalysis as object,
      updatedAt: new Date(),
    },
  });
}

/**
 * detectProfile — Auto-detects the user's career profile from resume data.
 *
 * No dropdown. No user input. Pure signal inference.
 */

const TECH_KEYWORDS = [
  "react", "next.js", "nextjs", "angular", "vue", "svelte",
  "typescript", "javascript", "python", "java", "golang", "rust",
  "node", "django", "flask", "fastapi", "spring",
  "sql", "postgresql", "mongodb", "redis", "graphql",
  "aws", "gcp", "azure", "docker", "kubernetes", "terraform",
  "git", "ci/cd", "devops", "machine learning", "ai", "llm",
];

const NON_TECH_KEYWORDS = [
  "marketing", "sales", "hr", "human resources", "finance", "accounting",
  "operations", "supply chain", "logistics", "customer success",
  "business development", "content", "seo", "social media",
  "product management", "project management", "consulting",
];

const LEADERSHIP_TITLES = [
  "manager", "director", "head of", "vp", "vice president",
  "lead", "principal", "staff", "architect", "cto", "ceo", "founder",
  "senior", "sr.", "sr ",
];

export interface DetectedProfile {
  level: "Fresher" | "Mid-Level" | "Senior";
  domain: "Tech" | "Non-Tech" | "Mixed";
  yearsOfExperience: number;
  inferredRole: string;
  tagline: string;
}

type ResumeExperienceSignal = {
  role?: string;
  company?: string;
  startDate?: string;
  endDate?: string;
};

type ResumeProfileInput = {
  experience?: unknown;
  skills?: unknown;
};

function calcYearsFromExperience(experience: ResumeExperienceSignal[]): number {
  let totalMonths = 0;
  const now = new Date();

  for (const exp of experience) {
    const start = exp.startDate ? new Date(exp.startDate) : null;
    const end = exp.endDate
      ? exp.endDate.toLowerCase() === "present"
        ? now
        : new Date(exp.endDate)
      : now;

    if (start && !isNaN(start.getTime()) && !isNaN(end.getTime())) {
      const diff =
        (end.getFullYear() - start.getFullYear()) * 12 +
        (end.getMonth() - start.getMonth());
      if (diff > 0) totalMonths += diff;
    }
  }

  return Math.round(totalMonths / 12);
}

function inferDomain(
  skills: string[],
  experience: { role?: string; company?: string }[]
): "Tech" | "Non-Tech" | "Mixed" {
  const blob = [
    ...skills,
    ...experience.map((e) => `${e.role || ""} ${e.company || ""}`),
  ]
    .join(" ")
    .toLowerCase();

  const techScore = TECH_KEYWORDS.filter((kw) => blob.includes(kw)).length;
  const nonTechScore = NON_TECH_KEYWORDS.filter((kw) => blob.includes(kw)).length;

  if (techScore > nonTechScore * 1.5) return "Tech";
  if (nonTechScore > techScore * 1.5) return "Non-Tech";
  return "Mixed";
}

function inferRole(
  experience: { role?: string }[],
  skills: string[]
): string {
  // Use the most recent role title
  const latestRole = experience[0]?.role;
  if (latestRole && latestRole.trim()) return latestRole.trim();

  // Fall back to skill-based heuristic
  const skillBlob = skills.join(" ").toLowerCase();
  if (skillBlob.includes("react") || skillBlob.includes("next")) return "Frontend Developer";
  if (skillBlob.includes("python") || skillBlob.includes("django")) return "Backend Developer";
  if (skillBlob.includes("devops") || skillBlob.includes("kubernetes")) return "DevOps Engineer";
  if (skillBlob.includes("data") || skillBlob.includes("machine learning")) return "Data Scientist";
  if (skillBlob.includes("marketing")) return "Marketing Specialist";
  if (skillBlob.includes("hr") || skillBlob.includes("recruiter")) return "HR Professional";

  return "Professional";
}

function inferLevel(
  years: number,
  experience: { role?: string }[]
): "Fresher" | "Mid-Level" | "Senior" {
  const roleBlob = experience.map((e) => e.role || "").join(" ").toLowerCase();
  const hasLeadershipTitle = LEADERSHIP_TITLES.some((t) => roleBlob.includes(t));

  if (hasLeadershipTitle || years >= 5) return "Senior";
  if (years >= 2) return "Mid-Level";
  return "Fresher";
}

function buildTagline(
  level: DetectedProfile["level"],
  domain: DetectedProfile["domain"],
  role: string
): string {
  if (level === "Fresher") {
    return `Optimized for Entry-Level ${domain === "Tech" ? "Tech" : ""} Roles`;
  }
  if (level === "Senior") {
    return `Optimized for Senior ${role} Opportunities`;
  }
  return `Optimized for ${role} Positions`;
}

export function detectProfile(resume: ResumeProfileInput): DetectedProfile {
  const experience: ResumeExperienceSignal[] = Array.isArray(resume?.experience)
    ? resume.experience.map((item) => item && typeof item === "object" ? item as ResumeExperienceSignal : {})
    : [];
  const rawSkills: unknown = resume?.skills ?? [];
  const skills: string[] = Array.isArray(rawSkills) ? rawSkills : String(rawSkills).split(",");

  const yearsOfExperience = calcYearsFromExperience(experience);
  const domain = inferDomain(skills, experience);
  const inferredRole = inferRole(experience, skills);
  const level = inferLevel(yearsOfExperience, experience);
  const tagline = buildTagline(level, domain, inferredRole);

  return { level, domain, yearsOfExperience, inferredRole, tagline };
}

export interface OnboardingAnalysis {
  score: number;
  fixes: string[];
  strongSkills: string[];
  weakSignals: string[];
}

export function analyzeOnboardingResume(resume: ResumeProfileInput): OnboardingAnalysis {
  const profile = detectProfile(resume);
  const rawSkills: unknown = (resume as any)?.skills ?? [];
  const skills: string[] = Array.isArray(rawSkills) 
    ? rawSkills.map(s => String(s))
    : String(rawSkills).split(",").map(s => s.trim()).filter(Boolean);

  const experience: any[] = Array.isArray((resume as any)?.experience) ? (resume as any).experience : [];
  const education: any[] = Array.isArray((resume as any)?.education) ? (resume as any).education : [];

  // Check for metrics in experience descriptions
  let hasMetrics = false;
  let textBlob = "";
  for (const exp of experience) {
    const pts = Array.isArray(exp.points)
      ? exp.points
      : typeof exp.points === "string"
        ? exp.points.split("\n")
        : [];
    const roleText = (exp.role || "") + " " + (exp.company || "") + " " + pts.join(" ");
    textBlob += " " + roleText;
    if (/[0-9]+%|[0-9]+\s*x|[0-9]+\s*ms|lakh|crore|million|billion|\$[0-9]+/i.test(roleText)) {
      hasMetrics = true;
    }
  }

  // Check for active portfolio or github links
  let hasLinks = false;
  const personal = (resume as any)?.personal || {};
  if (personal.website || personal.linkedin || /github\.com/i.test(textBlob)) {
    hasLinks = true;
  }

  // Check for education tier (non-tier-1 check if possible)
  let isTier1 = false;
  for (const edu of education) {
    const inst = String(edu.institution || "").toLowerCase();
    if (inst.includes("iit") || inst.includes("nit") || inst.includes("bits") || inst.includes("iiit") || inst.includes("technology") || inst.includes("engineering")) {
      isTier1 = true;
    }
  }

  // Calculate dynamic ATS score
  let score = 68;
  if (skills.length > 5) score += 5;
  if (skills.length > 10) score += 3;
  if (experience.length > 0) score += 8;
  if (hasMetrics) score += 8;
  if (hasLinks) score += 5;
  if (isTier1) score += 3;

  // Cap score between 45 and 92
  score = Math.max(45, Math.min(92, score));

  // Determine fixes and weak signals
  const fixes: string[] = [];
  const weakSignals: string[] = [];

  // Tech vs Non-Tech
  if (profile.domain === "Tech") {
    // Check for core modern tech stack terms
    const hasModernTools = ["docker", "kubernetes", "aws", "gcp", "ci/cd", "observability", "datadog", "redis", "postgres", "sql"].some(tool => 
      textBlob.toLowerCase().includes(tool) || skills.some(s => s.toLowerCase().includes(tool))
    );

    if (!hasMetrics) {
      fixes.push("Add quantitative impact metrics (e.g. latency reduced by 40%, API costs cut by $12k) to your experience points.");
      weakSignals.push("Missing scale and optimization metrics");
    } else {
      fixes.push("Refine bullet points to use the Action-Context-Result framework for technical impact.");
    }

    if (!hasModernTools) {
      fixes.push("Specify infrastructure, containerization, or deployment tools you used (e.g. Docker, CI/CD, AWS).");
      weakSignals.push("Lack of deployment and DevOps signals");
    } else {
      fixes.push("Categorize technical skills (e.g. Frontend, Backend, Database) to help recruiters scan in under 5 seconds.");
    }

    if (!hasLinks) {
      fixes.push("Add direct links to your GitHub or live project demos so engineering managers can verify code quality.");
      weakSignals.push("No verification links for projects");
    }
  } else {
    // Non-tech / Mixed
    if (!hasMetrics) {
      fixes.push("Quantify your business achievements (e.g. pipeline closed, growth rate, team size managed).");
      weakSignals.push("No revenue or conversion impact signals");
    }
    fixes.push("Add specific industry tools and methodologies (e.g. SQL, Tableau, Agile) instead of generic soft skills.");
    fixes.push("Reformat layout to lead with a summary of business outcomes rather than tasks.");
    weakSignals.push("Task-oriented description instead of outcome-oriented");
    weakSignals.push("Missing key data analysis tools");
  }

  // Fill in default placeholders if we don't have enough fixes/signals
  if (fixes.length < 3) {
    fixes.push("Ensure your summary highlights your unique value proposition in under 3 sentences.");
  }
  if (fixes.length < 3) {
    fixes.push("Fix date formats to be consistent (e.g., YYYY-MM to Present).");
  }
  if (weakSignals.length < 3) {
    weakSignals.push("Weak keyword density for target Indian market roles");
  }
  if (weakSignals.length < 3) {
    weakSignals.push("Education section leads before work experience");
  }

  // Top skills (max 4)
  const strongSkills = skills.slice(0, 4);
  if (strongSkills.length === 0) {
    strongSkills.push("Software Engineering", "Problem Solving");
  }

  return {
    score,
    fixes: fixes.slice(0, 3),
    strongSkills,
    weakSignals: weakSignals.slice(0, 3)
  };
}

import { prisma } from "@/lib/db/prisma";
import { CanonicalJob, JobOpportunity } from "@prisma/client";
import crypto from "crypto";

export interface NormalizedProviderJob {
  title: string;
  company: string;
  location?: string | null;
  remote?: boolean;
  employmentType?: string | null;
  source: string;
  sourceUrl: string;
  externalId?: string;
  description: string;
  postedAt?: Date;
}

export class JobDeduplicator {
  /**
   * Generates a stable hash for the exact normalized signature of a job
   */
  private static generateHash(company: string, title: string, location?: string): string {
    const data = `${this.normalizeCompany(company)}|${this.normalizeTitle(title)}|${this.normalizeLocation(location || "")}`;
    return crypto.createHash("sha256").update(data).digest("hex");
  }

  public static normalizeCompany(name: string): string {
    return name
      .toLowerCase()
      .replace(/\s+(inc|ltd|llc|corp|co|gmbh|pvt)\.?$/i, "")
      .replace(/[^a-z0-9]/g, "")
      .trim();
  }

  public static normalizeTitle(title: string): string {
    return title
      .toLowerCase()
      .replace(/\(.*?\)/g, "") // remove anything in parentheses
      .replace(/\[.*?\]/g, "") // remove brackets
      .replace(/\b(remote|hybrid|onsite|wfh)\b/g, "") // remove work styles
      .replace(/[^a-z0-9\s]/g, " ") // replace special chars with space
      .replace(/\s+/g, " ") // collapse spaces
      .trim();
  }

  public static normalizeLocation(location: string): string {
    return location
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  /**
   * Jaccard similarity for trigrams
   */
  public static trigramSimilarity(s1: string, s2: string): number {
    const getTrigrams = (str: string) => {
      const trigrams = new Set<string>();
      for (let i = 0; i < str.length - 2; i++) {
        trigrams.add(str.slice(i, i + 3));
      }
      return trigrams;
    };
    const t1 = getTrigrams(s1);
    const t2 = getTrigrams(s2);

    if (t1.size === 0 && t2.size === 0) return 1;

    let intersection = 0;
    t1.forEach((t) => {
      if (t2.has(t)) intersection++;
    });

    const union = t1.size + t2.size - intersection;
    return intersection / union;
  }

  /**
   * Jaccard similarity for token overlap
   */
  public static tokenOverlap(s1: string, s2: string): number {
    const setA = new Set(s1.split(/\s+/));
    const setB = new Set(s2.split(/\s+/));

    let intersection = 0;
    setA.forEach((t) => {
      if (setB.has(t)) intersection++;
    });

    const union = new Set([...setA, ...setB]).size;
    if (union === 0) return 1;
    return intersection / union;
  }

  /**
   * Process a single provider job through the 3-layer deduplication pipeline
   */
  public static async processJob(job: NormalizedProviderJob): Promise<CanonicalJob> {
    const normCompany = this.normalizeCompany(job.company);
    const normTitle = this.normalizeTitle(job.title);
    const normLocation = this.normalizeLocation(job.location || "");
    const hash = this.generateHash(job.company, job.title, job.location || undefined);

    // Layer 1: Exact Match (Hash or Exact URL)
    const exactMatch = await prisma.canonicalJob.findFirst({
      where: {
        OR: [
          { canonicalHash: hash },
        ]
      },
    });

    if (exactMatch) {
      return this.updateCanonicalJob(exactMatch, job, 1.0, "exact_hash", { reason: "Matching canonical hash" });
    }

    // Layer 2: Normalized Match
    const companyCandidates = await prisma.canonicalJob.findMany({
      where: {
        normalizedCompany: normCompany,
      },
      orderBy: { lastSeenAt: "desc" },
      take: 50, // bounding for performance
    });

    for (const candidate of companyCandidates) {
      // Very strict normalization check
      if (candidate.normalizedTitle === normTitle && candidate.normalizedLocation === normLocation) {
        return this.updateCanonicalJob(candidate, job, 0.95, "normalized_match", {
          titleSimilarity: 1.0,
          locationSimilarity: 1.0,
        });
      }
    }

    // Layer 3: Semantic Similarity
    for (const candidate of companyCandidates) {
      const titleSim = this.trigramSimilarity(candidate.normalizedTitle, normTitle);
      const tokenSim = this.tokenOverlap(candidate.normalizedTitle, normTitle);

      const combinedTitleSim = (titleSim + tokenSim) / 2;

      let locationSim = 1.0;
      if (candidate.normalizedLocation && normLocation) {
        locationSim = this.tokenOverlap(candidate.normalizedLocation, normLocation);
      }

      // Threshold-based merging (Conservative, prefer false negatives)
      if (combinedTitleSim > 0.85 && locationSim > 0.7) {
        return this.updateCanonicalJob(candidate, job, combinedTitleSim, "semantic_overlap", {
          titleSimilarity: combinedTitleSim,
          locationSimilarity: locationSim,
          trigram_title: titleSim,
          token_title: tokenSim,
        });
      }
    }

    // No match found - create new CanonicalJob
    return prisma.canonicalJob.create({
      data: {
        canonicalHash: hash,
        normalizedTitle: normTitle,
        normalizedCompany: normCompany,
        normalizedLocation: normLocation || null,
        primarySource: job.source,
        sourceCount: 1,
        confidenceScore: 0.5, // Initial confidence
        mergeConfidence: null,
        mergeStrategy: "new_canonical",
        firstSeenAt: new Date(),
        lastSeenAt: new Date(),
      }
    });
  }

  private static async updateCanonicalJob(
    canonicalJob: CanonicalJob,
    newJob: NormalizedProviderJob,
    mergeConfidence: number,
    mergeStrategy: string,
    mergeMetadata: any
  ): Promise<CanonicalJob> {
    // Increase source count, update last seen, boost confidence
    const newConfidence = Math.min((canonicalJob.confidenceScore || 0.5) + 0.15, 1.0);
    const newCount = canonicalJob.sourceCount + 1;

    return prisma.canonicalJob.update({
      where: { id: canonicalJob.id },
      data: {
        sourceCount: newCount,
        confidenceScore: newConfidence,
        lastSeenAt: new Date(),
        mergeConfidence,
        mergeStrategy,
        mergeMetadata,
      }
    });
  }
}

import { logger } from "@/lib/logger";
import {
  JobProviderContract,
  NormalizedProviderJob,
  ProviderResponse,
} from "./provider.types";

type ProviderRecord = Record<string, unknown>;

function asRecord(value: unknown): ProviderRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? value as ProviderRecord : {};
}

function stringValue(value: unknown, fallback = ""): string {
  return typeof value === "string" ? value : value == null ? fallback : String(value);
}

function nullableString(value: unknown): string | null {
  const text = stringValue(value).trim();
  return text ? text : null;
}

function numberValue(value: unknown): number | null {
  const parsed = typeof value === "number" ? value : Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function stringArray(value: unknown): string[] {
  return Array.isArray(value) ? value.map(String).filter(Boolean) : [];
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : "Provider fetch failed";
}

abstract class BaseJobProvider implements JobProviderContract {
  abstract readonly name: string;
  abstract readonly baseUrl: string;
  abstract readonly rateLimitMs: number;

  protected async fetchWithTimeout(url: string, timeoutMs = 10000): Promise<Response> {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const res = await fetch(url, {
        signal: controller.signal,
        headers: { "User-Agent": "CareerOS-JobBot/1.0" },
      });
      return res;
    } finally {
      clearTimeout(timer);
    }
  }

  async healthCheck(): Promise<boolean> {
    try {
      const res = await this.fetchWithTimeout(this.baseUrl, 5000);
      return res.ok;
    } catch {
      return false;
    }
  }

  protected buildResponse(
    data: NormalizedProviderJob[],
    rawCount: number,
    durationMs: number,
    error?: string
  ): ProviderResponse<NormalizedProviderJob> {
    return {
      ok: !error,
      data,
      provider: this.name,
      fetchedAt: new Date(),
      durationMs,
      rawCount,
      normalizedCount: data.length,
      deduplicatedCount: rawCount - data.length,
      ...(error ? { error } : {}),
    };
  }

  abstract fetchJobs(
    query: string,
    location?: string,
    limit?: number
  ): Promise<ProviderResponse<NormalizedProviderJob>>;
}

// -----------------------------------------------------------------------
// Remotive — Remote job board with free public API
// -----------------------------------------------------------------------
export class RemotiveProvider extends BaseJobProvider {
  readonly name = "Remotive";
  readonly baseUrl = "https://remotive.com";
  readonly rateLimitMs = 2000;

  async fetchJobs(
    query: string,
    _location?: string,
    limit = 20
  ): Promise<ProviderResponse<NormalizedProviderJob>> {
    const start = Date.now();
    const url = `https://remotive.com/api/remote-jobs?search=${encodeURIComponent(query)}&limit=${limit}`;

    try {
      const res = await this.fetchWithTimeout(url);
      if (!res.ok) throw new Error(`HTTP ${res.status}: ${res.statusText}`);

      const json = await res.json() as { jobs?: ProviderRecord[] };
      const rawJobs = json.jobs ?? [];
      const jobs: NormalizedProviderJob[] = rawJobs.map((j) => ({
        externalId: stringValue(j.id),
        title: stringValue(j.title),
        company: stringValue(j.company_name),
        location: nullableString(j.candidate_required_location),
        remote: true,
        salaryMin: null,
        salaryMax: null,
        currency: "USD",
        employmentType: nullableString(j.job_type),
        experienceLevel: null,
        skills: stringArray(j.tags),
        source: this.name,
        sourceUrl: stringValue(j.url),
        postedAt: new Date(stringValue(j.publication_date)),
        description: stringValue(j.description),
      }));

      logger.info({ provider: this.name, count: jobs.length }, "[Provider] jobs fetched");
      return this.buildResponse(jobs, rawJobs.length, Date.now() - start);
    } catch (error: unknown) {
      const message = errorMessage(error);
      logger.error({ provider: this.name, error: message }, "[Provider] fetch failed");
      return this.buildResponse([], 0, Date.now() - start, message);
    }
  }
}

