import { prisma } from "@/lib/db/prisma";
import { JobOpportunity, ConnectionPath, Application, HiringContact, EmailCampaign, EmailDraft } from "@prisma/client";

export interface OpportunityConfidence {
  score: number; // 0-100
  tier: "High" | "Medium" | "Low";
  reasons: string[];
}

export interface OpportunityGraph {
  job: JobOpportunity;
  application: (Application & { emailCampaign?: (EmailCampaign & { emails: EmailDraft[] }) | null }) | null;
  connections: ConnectionPath[];
  hiringContacts: HiringContact[];
  workflows: any[];
  confidence: OpportunityConfidence;
  status: string; // "Matched" | "Tailoring" | "Ready to apply" | "Applying" | "Awaiting approval" | "Submitted" | "Following up" | "Interviewing" | "Closed"
}

export class OpportunityGraphService {
  async getOpportunityGraph(userId: string, jobOpportunityId: string): Promise<OpportunityGraph | null> {
    const job = await prisma.jobOpportunity.findUnique({
      where: { id: jobOpportunityId },
    });

    if (!job || job.userId !== userId) {
      return null;
    }

    const [connections, hiringContacts, application] = await Promise.all([
      prisma.connectionPath.findMany({ where: { userId, jobOpportunityId }, orderBy: { strength: "desc" } }),
      prisma.hiringContact.findMany({ where: { jobOpportunities: { some: { id: jobOpportunityId } } } }),
      prisma.application.findFirst({
        where: { userId, jobOpportunityId },
        include: { emailCampaign: { include: { emails: { orderBy: { sequence: "asc" } } } } },
      }),
    ]);

    return {
      job,
      application,
      connections,
      hiringContacts,
      workflows: [],
      confidence: this.calculateConfidence(job, connections),
      status: this.determineStatus(job, application),
    };
  }

  private calculateConfidence(job: JobOpportunity, connections: ConnectionPath[]): OpportunityConfidence {
    let score = 50;
    const reasons: string[] = [];

    // Base match score (up to +30)
    const matchPoints = (job.matchScore / 100) * 30;
    score += matchPoints;
    if (job.matchScore > 80) reasons.push("Strong background match");

    // Ghost score (up to -40)
    if (job.ghostScore > 60) {
      score -= 40;
      reasons.push("High probability of being a ghost job");
    } else if (job.ghostScore > 25) {
      score -= 15;
      reasons.push("Suspicious job posting");
    } else {
      score += 10;
      reasons.push("Verified active opportunity");
    }

    // Networking (up to +20)
    if (connections.length > 0) {
      const topConnection = connections[0];
      if (topConnection && topConnection.confidenceTier === "verified") {
        score += 20;
        reasons.push("Verified network connection found");
      } else {
        score += 10;
        reasons.push("Potential networking paths identified");
      }
    }

    score = Math.min(100, Math.max(0, Math.round(score)));

    let tier: "High" | "Medium" | "Low" = "Low";
    if (score >= 75) tier = "High";
    else if (score >= 40) tier = "Medium";

    return { score, tier, reasons };
  }

  private determineStatus(job: JobOpportunity, application: Application | null): string {
    if (!application) return "Matched";

    if (application.status === "applied") return "Submitted";
    if (application.status === "interview") return "Interviewing";
    if (application.status === "rejected") return "Closed";

    if (application.generatedResume || application.coverLetter) {
      return "Ready to apply";
    }

    return "Tailoring";
  }
}

import "server-only";
import { prisma } from "@/lib/db/prisma";
import { getRedisClient } from "@/lib/redis";
import { clamp, normalizeText } from "./utils";

// ─────────────────────────────────────────────────────────────────────────────
// CONTRADICTION DETECTION ENGINE
//
// Detects when new intelligence contradicts established patterns.
//
// Types of contradictions:
//   SOFT: Unusual but plausible — reduce confidence, flag for monitoring
//   HARD: Statistically impossible with existing evidence — escalate immediately
//
// Detection methods:
//   1. Pattern Drift (mean shift detection)
//   2. Sudden Spike Detection (outlier vs baseline)
//   3. Narrative Reversal (round presence/absence flip)
//   4. Timeline Anomaly (impossible/implausible dates)
//   5. Salary Anomaly (>3σ from distribution)
// ─────────────────────────────────────────────────────────────────────────────

export type ContradictionType =
  | "pattern_drift"
  | "sudden_spike"
  | "narrative_reversal"
  | "timeline_anomaly"
  | "salary_anomaly"
  | "round_count_drift"
  | "difficulty_flip";

export type ContradictionSeverity = "soft" | "hard" | "none";

export interface ContradictionResult {
  severity: ContradictionSeverity;
  type: ContradictionType | null;
  score: number;            // 0–1 (1 = maximum contradiction)
  penalty: number;          // subtracted from surface score (0–1)
  details: string;
  shouldEscalate: boolean;
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. PATTERN DRIFT DETECTION
// Compares recent window vs historical baseline for a metric.
// Z-score: (recent_mean - historical_mean) / historical_std
// Drift > 2.0 → SOFT | Drift > 3.5 → HARD
// ─────────────────────────────────────────────────────────────────────────────

interface MetricSample {
  value: number;
  recordedAt: Date;
}

function computeZScore(recent: number[], historical: number[]): number {
  if (historical.length < 3) return 0;
  const mean = historical.reduce((a, b) => a + b, 0) / historical.length;
  const variance = historical.reduce((sum, v) => sum + (v - mean) ** 2, 0) / historical.length;
  const std = Math.sqrt(variance);
  if (std < 0.001) return 0;
  const recentMean = recent.length > 0 ? recent.reduce((a, b) => a + b, 0) / recent.length : mean;
  return Math.abs(recentMean - mean) / std;
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. DETECT DIFFICULTY FLIP for a company
// ─────────────────────────────────────────────────────────────────────────────
async function detectDifficultyFlip(companyId: string): Promise<ContradictionResult> {
  const DIFFICULTY_MAP: Record<string, number> = { easy: 0.25, medium: 0.50, hard: 0.75, expert: 1.00, unknown: 0.50 };
  const thirtyDaysAgo = new Date(Date.now() - 30 * 86_400_000);
  const ninetyDaysAgo = new Date(Date.now() - 90 * 86_400_000);

  const [recent, historical] = await Promise.all([
    prisma.questionFrequency.findMany({
      where: { companyId, updatedAt: { gte: thirtyDaysAgo } },
      include: { question: { select: { difficulty: true } } },
      take: 50,
    }),
    prisma.questionFrequency.findMany({
      where: { companyId, updatedAt: { gte: ninetyDaysAgo, lt: thirtyDaysAgo } },
      include: { question: { select: { difficulty: true } } },
      take: 100,
    }),
  ]);

  const recentScores = recent.map((f) => DIFFICULTY_MAP[f.question.difficulty] ?? 0.50);
  const historicalScores = historical.map((f) => DIFFICULTY_MAP[f.question.difficulty] ?? 0.50);
  const zScore = computeZScore(recentScores, historicalScores);

  if (zScore > 3.5) return {
    severity: "hard", type: "difficulty_flip",
    score: clamp(zScore / 5), penalty: 0.40,
    details: `Difficulty distribution shifted significantly (z=${zScore.toFixed(2)})`,
    shouldEscalate: true,
  };
  if (zScore > 2.0) return {
    severity: "soft", type: "pattern_drift",
    score: clamp(zScore / 5), penalty: 0.15,
    details: `Difficulty drift detected (z=${zScore.toFixed(2)})`,
    shouldEscalate: false,
  };

  return { severity: "none", type: null, score: 0, penalty: 0, details: "", shouldEscalate: false };
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. DETECT ROUND COUNT DRIFT
// ─────────────────────────────────────────────────────────────────────────────
async function detectRoundCountDrift(companyId: string): Promise<ContradictionResult> {
  const sixtyDaysAgo = new Date(Date.now() - 60 * 86_400_000);

  const experiences = await prisma.interviewExperience.findMany({
    where: { companyId, moderationStatus: "approved" },
    select: { roundsCount: true, createdAt: true },
    orderBy: { createdAt: "desc" },
    take: 30,
  });

  if (experiences.length < 5) {
    return { severity: "none", type: null, score: 0, penalty: 0, details: "", shouldEscalate: false };
  }

  const recent = experiences.filter((e) => e.createdAt >= sixtyDaysAgo).map((e) => e.roundsCount ?? 4);
  const historical = experiences.filter((e) => e.createdAt < sixtyDaysAgo).map((e) => e.roundsCount ?? 4);
  const zScore = computeZScore(recent, historical);

  if (zScore > 3.0) return {
    severity: "hard", type: "round_count_drift",
    score: clamp(zScore / 4), penalty: 0.30,
    details: `Round count changed significantly — recent avg ${recent.length > 0 ? (recent.reduce((a, b) => a + b, 0) / recent.length).toFixed(1) : "N/A"} vs historical ${historical.length > 0 ? (historical.reduce((a, b) => a + b, 0) / historical.length).toFixed(1) : "N/A"}`,
    shouldEscalate: true,
  };
  if (zScore > 1.5) return {
    severity: "soft", type: "pattern_drift",
    score: clamp(zScore / 4), penalty: 0.10,
    details: `Round count shifted (z=${zScore.toFixed(2)})`,
    shouldEscalate: false,
  };

  return { severity: "none", type: null, score: 0, penalty: 0, details: "", shouldEscalate: false };
}

// ─────────────────────────────────────────────────────────────────────────────
// 4. DETECT SALARY ANOMALY
// A new salary submission is >3σ from existing distribution → suspicious
// ─────────────────────────────────────────────────────────────────────────────
async function detectSalaryAnomaly(companyId: string, newBaseAnnual: number): Promise<ContradictionResult> {
  const insights = await prisma.salaryInsight.findMany({
    where: { companyId, confidence: { gte: 0.4 } },
    select: { baseMedian: true, baseMin: true, baseMax: true, sampleSize: true },
    take: 20,
  });

  if (insights.length < 3) {
    return { severity: "none", type: null, score: 0, penalty: 0, details: "", shouldEscalate: false };
  }

  const medians = insights.map((i) => i.baseMedian ?? 0).filter((v) => v > 0);
  if (medians.length < 2) {
    return { severity: "none", type: null, score: 0, penalty: 0, details: "", shouldEscalate: false };
  }
  const mean = medians.reduce((a, b) => a + b, 0) / medians.length;
  const std = Math.sqrt(medians.reduce((sum, v) => sum + (v - mean) ** 2, 0) / medians.length);

  const zScore = std > 0 ? Math.abs(newBaseAnnual - mean) / std : 0;

  if (zScore > 3.0) return {
    severity: "hard", type: "salary_anomaly",
    score: clamp(zScore / 5), penalty: 0.50,
    details: `Salary ₹${(newBaseAnnual / 100000).toFixed(1)}L is ${zScore.toFixed(1)}σ from market median`,
    shouldEscalate: true,
  };
  if (zScore > 2.0) return {
    severity: "soft", type: "salary_anomaly",
    score: clamp(zScore / 5), penalty: 0.20,
    details: `Salary appears inflated vs market data (z=${zScore.toFixed(1)})`,
    shouldEscalate: false,
  };

  return { severity: "none", type: null, score: 0, penalty: 0, details: "", shouldEscalate: false };
}

// ─────────────────────────────────────────────────────────────────────────────
// 5. SUDDEN SPIKE DETECTION
// A topic appears 5× more frequently than its 30-day baseline
// ─────────────────────────────────────────────────────────────────────────────
async function detectSuddenSpike(companyId: string, topic: string): Promise<ContradictionResult> {
  const redis = getRedisClient();
  const cacheKey = `contradiction:spike:${companyId}:${topic}`;

  if (redis) {
    const cached = await redis.get<ContradictionResult>(cacheKey).catch(() => null);
    if (cached) return cached;
  }

  const now = new Date();
  const fourteenDaysAgo = new Date(Date.now() - 14 * 86_400_000);
  const previousPeriodStart = new Date(Date.now() - 44 * 86_400_000);

  const [recentCount, historicalCount] = await Promise.all([
    prisma.questionFrequency.count({
      where: { companyId, updatedAt: { gte: fourteenDaysAgo } },
    }),
    prisma.questionFrequency.count({
      where: { companyId, updatedAt: { gte: previousPeriodStart, lt: fourteenDaysAgo } },
    }),
  ]);

  const weeklyHistoricalAvg = historicalCount / 2; // Two 14-day periods in the 28-day historical window
  const spikeRatio = weeklyHistoricalAvg > 0 ? recentCount / weeklyHistoricalAvg : 0;

  const result: ContradictionResult = spikeRatio > 5.0
    ? { severity: "soft", type: "sudden_spike", score: clamp(spikeRatio / 10), penalty: 0.10,
        details: `Question frequency spiked ${spikeRatio.toFixed(1)}× above baseline — verify authenticity`, shouldEscalate: false }
    : { severity: "none", type: null, score: 0, penalty: 0, details: "", shouldEscalate: false };

  await redis?.set(cacheKey, result, { ex: 3600 }).catch(() => undefined);
  return result;
}

// ─────────────────────────────────────────────────────────────────────────────
// MASTER CONTRADICTION EVALUATOR
// ─────────────────────────────────────────────────────────────────────────────
export async function evaluateContradiction(params: {
  companyId: string;
  topic?: string | undefined;
  newSalary?: number | undefined;
}): Promise<ContradictionResult> {
  const results = await Promise.all([
    detectDifficultyFlip(params.companyId),
    detectRoundCountDrift(params.companyId),
    params.newSalary ? detectSalaryAnomaly(params.companyId, params.newSalary) : Promise.resolve<ContradictionResult>({ severity: "none", type: null, score: 0, penalty: 0, details: "", shouldEscalate: false }),
    params.topic ? detectSuddenSpike(params.companyId, params.topic) : Promise.resolve<ContradictionResult>({ severity: "none", type: null, score: 0, penalty: 0, details: "", shouldEscalate: false }),
  ]);

  // Return the worst result
  const worst = results.reduce((best, current) =>
    current.score > best.score ? current : best,
    results[0]!
  );

  // Persist alert if significant
  if (worst.severity !== "none" && worst.score > 0.25) {
    await prisma.contradictionAlert.upsert({
      where: {
        entityType_entityId_type: {
          entityType: "Company",
          entityId: params.companyId,
          type: worst.type ?? "pattern_drift",
        },
      },
      create: {
        entityType: "Company",
        entityId: params.companyId,
        type: worst.type ?? "pattern_drift",
        severity: worst.severity,
        score: worst.score,
        details: worst.details,
        shouldEscalate: worst.shouldEscalate,
      },
      update: {
        score: worst.score,
        details: worst.details,
        severity: worst.severity,
        shouldEscalate: worst.shouldEscalate,
        resolvedAt: null, // re-open if previously resolved
        updatedAt: new Date(),
      },
    });

    // Push to moderation escalation queue if hard contradiction
    if (worst.shouldEscalate) {
      const redis = getRedisClient();
      await redis?.lpush("moderation:contradiction_queue", JSON.stringify({
        companyId: params.companyId,
        type: worst.type,
        score: worst.score,
        details: worst.details,
        timestamp: new Date().toISOString(),
      })).catch(() => undefined);
    }
  }

  return worst;
}

import "server-only";
import { prisma } from "@/lib/db/prisma";
import { getRedisClient } from "@/lib/redis";
import { clamp } from "./utils";

// ─────────────────────────────────────────────────────────────────────────────
// RECRUITER PATTERN INTELLIGENCE ENGINE
//
// Tracks and surfaces recruiter behavior changes at the company level:
//   - Round count evolution
//   - DSA / System Design / Machine Coding emphasis shifts
//   - Timeline compression or elongation
//   - Ghosting rate changes
//   - Salary compression signals
//   - Hiring velocity (freeze, slow, high)
// ─────────────────────────────────────────────────────────────────────────────

export interface RecruiterTrendReport {
  companyId: string;
  companyName: string;
  slug: string;
  generatedAt: Date;

  // Round evolution
  avgRoundsRecent: number | null;
  avgRoundsHistorical: number | null;
  roundCountTrend: "increasing" | "decreasing" | "stable" | "unknown";

  // Difficulty evolution
  difficultyTrend: "getting_harder" | "getting_easier" | "stable" | "unknown";
  recentDifficultyScore: number | null;
  historicalDifficultyScore: number | null;

  // Timeline evolution
  avgTimelineDaysRecent: number | null;
  avgTimelineDaysHistorical: number | null;
  timelineTrend: "faster" | "slower" | "stable" | "unknown";

  // Hiring velocity
  hiringVelocity: "freeze" | "slow" | "normal" | "high" | "unknown";
  recentContributionCount: number;

  // Round type emphasis
  machineCodingEmphasis: number;   // 0–1 fraction of rounds that are machine coding
  systemDesignEmphasis: number;
  dsaEmphasis: number;
  behavioralEmphasis: number;

  // Ghosting signal
  ghostingRatePct: number | null;

  // Key insight (human-readable summary)
  topInsight: string;
  signals: string[];
  confidence: "high" | "medium" | "low";
}

const DIFFICULTY_SCORE: Record<string, number> = {
  easy: 0.25, medium: 0.50, hard: 0.75, expert: 1.00, unknown: 0.50,
};

const ROUND_TYPE_MAP: Record<string, keyof Pick<RecruiterTrendReport, "machineCodingEmphasis" | "systemDesignEmphasis" | "dsaEmphasis" | "behavioralEmphasis">> = {
  machine_coding: "machineCodingEmphasis",
  system_design:  "systemDesignEmphasis",
  technical:      "dsaEmphasis",
  behavioral:     "behavioralEmphasis",
  hr:             "behavioralEmphasis",
};

function trend(recent: number | null, historical: number | null, threshold = 0.10): "increasing" | "decreasing" | "stable" | "unknown" {
  if (recent == null || historical == null || historical === 0) return "unknown";
  const delta = (recent - historical) / historical;
  if (delta >  threshold) return "increasing";
  if (delta < -threshold) return "decreasing";
  return "stable";
}

function safeMean(values: number[]): number | null {
  if (values.length === 0) return null;
  return values.reduce((a, b) => a + b, 0) / values.length;
}

export class RecruiterTrendEngine {
  /**
   * Generate a full recruiter trend report for a company.
   * Cached in Redis for 2 hours.
   */
  static async getReport(companyId: string): Promise<RecruiterTrendReport | null> {
    const redis = getRedisClient();
    const cacheKey = `recruiter:trend:${companyId}`;
    const cached = await redis?.get<RecruiterTrendReport>(cacheKey).catch(() => null);
    if (cached) return cached;

    const company = await prisma.company.findUnique({
      where: { id: companyId },
      select: { id: true, name: true, slug: true },
    });
    if (!company) return null;

    const thirtyDaysAgo = new Date(Date.now() - 30 * 86_400_000);
    const ninetyDaysAgo = new Date(Date.now() - 90 * 86_400_000);

    const [recentExperiences, historicalExperiences, recruiterPatterns, recentFrequencies, recentContributions] = await Promise.all([
      prisma.interviewExperience.findMany({
        where: { companyId, moderationStatus: "approved", createdAt: { gte: thirtyDaysAgo } },
        include: { rounds: true },
        take: 20,
      }),
      prisma.interviewExperience.findMany({
        where: { companyId, moderationStatus: "approved", createdAt: { gte: ninetyDaysAgo, lt: thirtyDaysAgo } },
        include: { rounds: true },
        take: 40,
      }),
      prisma.recruiterPattern.findMany({
        where: { companyId },
        orderBy: { trustScore: "desc" },
        take: 10,
      }),
      prisma.questionFrequency.findMany({
        where: { companyId, updatedAt: { gte: thirtyDaysAgo } },
        include: { question: true },
        take: 50,
      }),
      prisma.interviewContribution.count({
        where: { companyName: company.name, status: "approved", createdAt: { gte: thirtyDaysAgo } },
      }),
    ]);

    // Round counts
    const recentRounds  = recentExperiences.map((e) => e.rounds.length);
    const historicalRounds = historicalExperiences.map((e) => e.rounds.length);
    const avgRoundsRecent = safeMean(recentRounds);
    const avgRoundsHistorical = safeMean(historicalRounds);

    // Difficulty scores
    const recentDifficultyScore = safeMean(
      recentFrequencies.map((f) => DIFFICULTY_SCORE[f.question.difficulty] ?? 0.50)
    );
    const historicalDiffScores = await prisma.questionFrequency.findMany({
      where: { companyId, updatedAt: { gte: ninetyDaysAgo, lt: thirtyDaysAgo } },
      include: { question: { select: { difficulty: true } } },
      take: 80,
    });
    const historicalDifficultyScore = safeMean(
      historicalDiffScores.map((f) => DIFFICULTY_SCORE[f.question.difficulty] ?? 0.50)
    );

    // Timeline trends
    const recentTimelines = recentExperiences.map((e) => e.timelineDays ?? 0).filter((d) => d > 0);
    const historicalTimelines = historicalExperiences.map((e) => e.timelineDays ?? 0).filter((d) => d > 0);
    const avgTimelineDaysRecent = safeMean(recentTimelines);
    const avgTimelineDaysHistorical = safeMean(historicalTimelines);

    // Round type emphasis
    const allRecentRoundTypes = recentExperiences.flatMap((e) => e.rounds.map((r) => r.type));
    const total = Math.max(allRecentRoundTypes.length, 1);
    const countType = (types: string[]) => allRecentRoundTypes.filter((rt) => types.includes(rt)).length / total;

    const machineCodingEmphasis = countType(["machine_coding"]);
    const systemDesignEmphasis  = countType(["system_design", "lld"]);
    const dsaEmphasis           = countType(["technical", "online_assessment"]);
    const behavioralEmphasis    = countType(["behavioral", "hr", "recruiter_screen"]);

    // Ghosting rate
    const ghostingReports = recruiterPatterns.filter((rp) => (rp.ghostingRate ?? 0) > 0.5);
    const ghostingRatePct = recruiterPatterns.length > 0
      ? Math.round(ghostingReports.length / recruiterPatterns.length * 100)
      : null;

    // Hiring velocity
    const hiringVelocity: RecruiterTrendReport["hiringVelocity"] =
      recentContributions > 10 ? "high" :
      recentContributions > 4  ? "normal" :
      recentContributions > 0  ? "slow" :
      "freeze";

    // Derive trend labels
    const roundCountTrend = trend(avgRoundsRecent, avgRoundsHistorical, 0.15) as RecruiterTrendReport["roundCountTrend"];
    const difficultyTrend: RecruiterTrendReport["difficultyTrend"] =
      recentDifficultyScore != null && historicalDifficultyScore != null
        ? recentDifficultyScore > historicalDifficultyScore + 0.08 ? "getting_harder"
        : recentDifficultyScore < historicalDifficultyScore - 0.08 ? "getting_easier"
        : "stable"
      : "unknown";
    const timelineTrend = trend(avgTimelineDaysRecent, avgTimelineDaysHistorical, 0.10) as RecruiterTrendReport["timelineTrend"];

    // Confidence
    const evidencePoints = recentExperiences.length + historicalExperiences.length;
    const confidence: RecruiterTrendReport["confidence"] =
      evidencePoints >= 10 ? "high" :
      evidencePoints >= 4  ? "medium" : "low";

    // Signals and top insight
    const signals: string[] = [];
    if (difficultyTrend === "getting_harder")    signals.push("⚠️ Interview difficulty increasing recently");
    if (difficultyTrend === "getting_easier")    signals.push("✅ Process appears easier than historical average");
    if (roundCountTrend === "increasing")        signals.push("📈 Round count is rising — prepare for longer process");
    if (roundCountTrend === "decreasing")        signals.push("📉 Process is becoming shorter — faster decisions");
    if (timelineTrend === "slower")              signals.push("🐢 Hiring timeline is elongating — follow up proactively");
    if (timelineTrend === "faster")              signals.push("⚡ Faster offers recently — don't delay if shortlisted");
    if (machineCodingEmphasis > 0.35)            signals.push("💻 Machine Coding is emphasized — practice CLI apps");
    if (systemDesignEmphasis > 0.30)             signals.push("🏗️ System Design is heavily weighted");
    if ((ghostingRatePct ?? 0) > 40)             signals.push("👻 High ghosting rate — follow up after every round");
    if (hiringVelocity === "high")               signals.push("🔥 High hiring activity — apply now");
    if (hiringVelocity === "freeze" || hiringVelocity === "slow") signals.push("🧊 Low hiring activity — explore alternatives");

    const topInsight = signals[0] ?? `${company.name} maintains a ${avgRoundsRecent?.toFixed(0) ?? 4}-round process`;

    const report: RecruiterTrendReport = {
      companyId, companyName: company.name, slug: company.slug, generatedAt: new Date(),
      avgRoundsRecent, avgRoundsHistorical, roundCountTrend,
      difficultyTrend, recentDifficultyScore, historicalDifficultyScore,
      avgTimelineDaysRecent, avgTimelineDaysHistorical, timelineTrend,
      hiringVelocity, recentContributionCount: recentContributions,
      machineCodingEmphasis, systemDesignEmphasis, dsaEmphasis, behavioralEmphasis,
      ghostingRatePct, topInsight, signals, confidence,
    };

    await redis?.set(cacheKey, report, { ex: 2 * 60 * 60 }).catch(() => undefined);
    return report;
  }

  /**
   * Refresh recruiter trends for all active companies.
   * Called by BullMQ daily cron job.
   */
  static async refreshAll(): Promise<{ refreshed: number; failed: number }> {
    const companies = await prisma.company.findMany({
      where: { lastIngestedAt: { gte: new Date(Date.now() - 180 * 86_400_000) } },
      select: { id: true },
      take: 100,
    });

    let refreshed = 0, failed = 0;
    for (const company of companies) {
      try {
        const redis = getRedisClient();
        await redis?.del(`recruiter:trend:${company.id}`).catch(() => undefined);
        await this.getReport(company.id);
        refreshed++;
      } catch {
        failed++;
      }
    }
    return { refreshed, failed };
  }
}

import "server-only";
import {
  InterviewContributionType,
  InterviewDifficulty,
  InterviewModerationStatus,
  InterviewQuestionKind,
  InterviewSourceType,
  Prisma,
} from "@prisma/client";
