import { prisma } from "@/lib/db/prisma";
import { logger } from "@/lib/logger";
import { geminiJSON } from "@/lib/ai/core";
import { z } from "zod";

const OpportunityIntelligenceSchema = z.object({
  opportunityScore: z.number().min(0).max(100),
  skillMatch: z.number().min(0).max(100),
  salaryGrowth: z.number().min(0).max(100),
  competition: z.number().min(0).max(100),
  careerGrowth: z.number().min(0).max(100),
  hiringDemand: z.number().min(0).max(100),
  marketTrends: z.number().min(0).max(100),
  interviewProbability: z.number().min(0).max(100),
  whyMatters: z.string(),
  salaryGrowthExplanation: z.string(),
  requiredSkills: z.array(z.string()),
  successProbability: z.number().min(0).max(100),
  predictedSalaryMin: z.number(),
  predictedSalaryMax: z.number(),
  predictedSalaryCurrency: z.string().default("INR"),
  layoffRisk: z.number().min(0).max(100),
  companyMomentum: z.number().min(0).max(100),
  stabilityScore: z.number().min(0).max(100),
});

export type OpportunityIntelligence = z.infer<typeof OpportunityIntelligenceSchema>;

export class OpportunityIntelligenceService {
  static async computeOpportunityIntelligence(jobOpportunityId: string, userId: string): Promise<OpportunityIntelligence> {
    try {
      // 1. Fetch Job
      const job = await prisma.jobOpportunity.findUnique({
        where: { id: jobOpportunityId },
      });
      if (!job) {
        throw new Error(`Job Opportunity ${jobOpportunityId} not found`);
      }

      // 2. Fetch User & Resume
      const user = await prisma.user.findUnique({
        where: { id: userId },
        select: { activeResumeId: true },
      });

      let resumeData: any = null;
      if (user?.activeResumeId) {
        const resume = await prisma.resume.findUnique({
          where: { id: user.activeResumeId },
        });
        resumeData = resume?.data;
      } else {
        const latestResume = await prisma.resume.findFirst({
          where: { userId },
          orderBy: { updatedAt: "desc" },
        });
        resumeData = latestResume?.data;
      }

      // 3. Fetch Career Profile (for 5-year goal & target salary)
      const careerProfile = await prisma.careerProfile.findUnique({
        where: { userId },
      });

      // 4. Format Prompt Context
      const goalsText = careerProfile?.goals
        ? typeof careerProfile.goals === "string"
          ? careerProfile.goals
          : JSON.stringify(careerProfile.goals)
        : "Not specified";

      const resumeText = resumeData
        ? typeof resumeData === "string"
          ? resumeData
          : JSON.stringify({
              skills: resumeData.skills,
              summary: resumeData.personal?.summary,
              experience: resumeData.work?.map((w: any) => ({
                role: w.position,
                company: w.company,
                summary: w.summary,
              })),
            })
        : "No resume profile available.";

      const targetSalaryText = careerProfile?.salaryExpectation
        ? JSON.stringify(careerProfile.salaryExpectation)
        : "Not specified";

      const systemPrompt = `You are a staff career intelligence analyst. Your task is to perform an deep-level Opportunity Analysis of a job opening against a user's professional profile.
Analyze the opportunity based on:
1. Skill Match: How well user's current skills align with the required skills.
2. Salary Growth: Growth potential compared to target salary and standard industry bumps.
3. Competition: Relative difficulty of getting this role based on standard candidate supply.
4. Career Growth: Alignment with user's 5-year goal (${goalsText}).
5. Hiring Demand: Current hiring urgency, velocity, and market need.
6. Market Trends: Future relevance of the job domain and key skills.
7. Interview Probability: Chances of scoring an interview based on profile fit.

Return a JSON object conforming exactly to the following schema:
{
  "opportunityScore": number (0-100),
  "skillMatch": number (0-100),
  "salaryGrowth": number (0-100),
  "competition": number (0-100),
  "careerGrowth": number (0-100),
  "hiringDemand": number (0-100),
  "marketTrends": number (0-100),
  "interviewProbability": number (0-100),
  "whyMatters": "Clear explanation of why this opportunity matters for the user",
  "salaryGrowthExplanation": "Explicit prediction details on expected salary growth & market comparison",
  "requiredSkills": ["list", "of", "required", "skills"],
  "successProbability": number (0-100),
  "predictedSalaryMin": number,
  "predictedSalaryMax": number,
  "predictedSalaryCurrency": "INR" or "USD",
  "layoffRisk": number (0-100),
  "companyMomentum": number (0-100),
  "stabilityScore": number (0-100)
}
Be precise. Calculate real scores. Do not return mock or placeholder values.`;

      const userPrompt = `USER PROFILE:
- Resume Summary & Skills: ${resumeText}
- 5-Year Career Goal: ${goalsText}
- Target Salary: ${targetSalaryText}

JOB OPPORTUNITY:
- Role: ${job.role}
- Company: ${job.company}
- Location: ${job.location ?? "Remote / Unknown"}
- Salary Range: ${job.salaryRange ?? "Not listed"}
- Description: ${job.description}`;

      const fallback: OpportunityIntelligence = {
        opportunityScore: 70,
        skillMatch: 70,
        salaryGrowth: 60,
        competition: 50,
        careerGrowth: 75,
        hiringDemand: 65,
        marketTrends: 70,
        interviewProbability: 60,
        whyMatters: "Good baseline match for your skills and career trajectory.",
        salaryGrowthExplanation: "Standard market rate bump anticipated.",
        requiredSkills: ["React", "TypeScript", "Node.js"],
        successProbability: 60,
        predictedSalaryMin: 1200000,
        predictedSalaryMax: 1800000,
        predictedSalaryCurrency: "INR",
        layoffRisk: 20,
        companyMomentum: 70,
        stabilityScore: 80,
      };

      const result = await geminiJSON<OpportunityIntelligence>({
        system: systemPrompt,
        user: userPrompt,
        fallback,
        schema: OpportunityIntelligenceSchema,
        temperature: 0.2,
      });

      // 5. Upsert to DB
      await prisma.jobIntelligence.upsert({
        where: { jobOpportunityId },
        update: {
          opportunityScore: result.opportunityScore,
          hiringVelocity: result.hiringDemand,
          marketDemand: result.marketTrends,
          competitionScore: result.competition,
          salaryPrediction: {
            min: result.predictedSalaryMin,
            max: result.predictedSalaryMax,
            currency: result.predictedSalaryCurrency,
            explanation: result.salaryGrowthExplanation,
          },
          layoffRisk: result.layoffRisk,
          careerGrowth: result.careerGrowth,
          companyMomentum: result.companyMomentum,
          matchQuality: result.skillMatch,
          stabilityScore: result.stabilityScore,
          whyMatters: result.whyMatters,
          interviewProbability: result.interviewProbability,
          successProbability: result.successProbability,
          requiredSkills: result.requiredSkills,
          salaryGrowth: result.salaryGrowth,
          computedAt: new Date(),
        },
        create: {
          jobOpportunityId,
          opportunityScore: result.opportunityScore,
          hiringVelocity: result.hiringDemand,
          marketDemand: result.marketTrends,
          competitionScore: result.competition,
          salaryPrediction: {
            min: result.predictedSalaryMin,
            max: result.predictedSalaryMax,
            currency: result.predictedSalaryCurrency,
            explanation: result.salaryGrowthExplanation,
          },
          layoffRisk: result.layoffRisk,
          careerGrowth: result.careerGrowth,
          companyMomentum: result.companyMomentum,
          matchQuality: result.skillMatch,
          stabilityScore: result.stabilityScore,
          whyMatters: result.whyMatters,
          interviewProbability: result.interviewProbability,
          successProbability: result.successProbability,
          requiredSkills: result.requiredSkills,
          salaryGrowth: result.salaryGrowth,
        },
      });

      return result;
    } catch (error) {
      logger.error({ error, jobOpportunityId }, "Failed to compute opportunity intelligence");
      throw error;
    }
  }

  static async getRankedOpportunities(userId: string) {
    const opportunities = await prisma.jobOpportunity.findMany({
      where: { userId },
      include: {
        intelligence: true,
      },
    });

    // Automatically trigger analysis for opportunities that don't have fresh intelligence
    const analyzedOpportunities = await Promise.all(
      opportunities.map(async (opp) => {
        let intel = opp.intelligence;
        if (!intel || Date.now() - intel.computedAt.getTime() > 1000 * 60 * 60 * 24 * 7) {
          try {
            const freshIntel = await this.computeOpportunityIntelligence(opp.id, userId);
            // Fetch updated model
            const updatedIntel = await prisma.jobIntelligence.findUnique({
              where: { jobOpportunityId: opp.id },
            });
            intel = updatedIntel;
          } catch (e) {
            logger.warn({ oppId: opp.id, error: e }, "Lazy intelligence generation failed during ranking");
          }
        }

        const mappedIntel = intel ? {
          ...intel,
          salaryGrowthExplanation: (intel.salaryPrediction as any)?.explanation || ""
        } : null;

        return {
          ...opp,
          intelligence: mappedIntel,
        };
      })
    );

    // Sort by opportunityScore descending, handling null intelligence
    return analyzedOpportunities.sort((a, b) => {
      const scoreA = a.intelligence?.opportunityScore ?? 0;
      const scoreB = b.intelligence?.opportunityScore ?? 0;
      return scoreB - scoreA;
    });
  }
}

import { prisma } from "@/lib/db/prisma";
import { logger } from "@/lib/logger";

interface OpportunityScoreInput {
  jobId: string;
  companyName: string;
  role: string;
  userMatchScore: number;
}

export class OpportunityScorer {
  /**
   * Generates or retrieves the JobIntelligence for a given job opportunity.
   */
  static async computeOpportunityScore(input: OpportunityScoreInput) {
    try {
      // 1. Check if intelligence already exists
      const existing = await prisma.jobIntelligence.findUnique({
        where: { jobOpportunityId: input.jobId },
      });

      if (existing && Date.now() - existing.computedAt.getTime() < 1000 * 60 * 60 * 24) {
        return existing; // Return cached intelligence if < 24 hours old
      }

      // 2. Fetch company intelligence
      const companyInt = await prisma.companyIntelligence.findUnique({
        where: { companyName: input.companyName },
      });

      // 3. Compute baseline metrics
      const hiringVelocity = this.calculateHiringVelocity(companyInt?.hiringVelocity);
      const layoffRisk = this.calculateLayoffRisk(companyInt?.layoffRisk);
      const companyMomentum = companyInt?.healthScore ?? 50;

      const marketDemand = this.calculateMarketDemand(input.role);
      const competitionScore = Math.random() * 40 + 60; // Mock: Usually derived from ATS/market data

      const matchQuality = Math.min(100, Math.max(0, input.userMatchScore));

      // Calculate stability score
      const stabilityScore = 100 - layoffRisk + (companyMomentum * 0.5);

      const careerGrowth = 75 + (companyMomentum * 0.15) - (layoffRisk * 0.1);

      // 4. Calculate Final Opportunity Score (0-100)
      // Weights:
      // Match Quality: 30%
      // Market Demand: 15%
      // Growth: 20%
      // Stability: 15%
      // Hiring Velocity: 10%
      // Competition: -10% (lower competition = higher score)

      let rawScore = 
        (matchQuality * 0.30) +
        (marketDemand * 0.15) +
        (careerGrowth * 0.20) +
        (stabilityScore * 0.15) +
        (hiringVelocity * 0.10) +
        ((100 - competitionScore) * 0.10);

      const opportunityScore = Math.min(100, Math.max(0, Math.round(rawScore)));

      // 5. Mock Salary & Trends
      const salaryPrediction = {
        min: 100000 + Math.random() * 20000,
        max: 150000 + Math.random() * 30000,
        currency: "USD",
        confidence: 0.85
      };

      const skillDemandTrends = [
        { skill: "React", trend: "up" },
        { skill: "Node.js", trend: "stable" },
        { skill: "TypeScript", trend: "up" }
      ];

      // 6. Upsert to database
      const intelligence = await prisma.jobIntelligence.upsert({
        where: { jobOpportunityId: input.jobId },
        update: {
          opportunityScore,
          hiringVelocity,
          marketDemand,
          competitionScore,
          salaryPrediction,
          layoffRisk,
          careerGrowth,
          skillDemandTrends,
          companyMomentum,
          matchQuality,
          stabilityScore,
          computedAt: new Date()
        },
        create: {
          jobOpportunityId: input.jobId,
          opportunityScore,
          hiringVelocity,
          marketDemand,
          competitionScore,
          salaryPrediction,
          layoffRisk,
          careerGrowth,
          skillDemandTrends,
          companyMomentum,
          matchQuality,
          stabilityScore
        }
      });

      return intelligence;
    } catch (error) {
      logger.error({ error, jobId: input.jobId }, "Failed to compute opportunity score");
      throw error;
    }
  }

  private static calculateHiringVelocity(velocityStr?: string): number {
    switch (velocityStr?.toLowerCase()) {
      case "high": return 90;
      case "medium": return 60;
      case "low": return 30;
      case "frozen": return 0;
      default: return 50;
    }
  }

  private static calculateLayoffRisk(riskStr?: string): number {
    switch (riskStr?.toLowerCase()) {
      case "high": return 80;
      case "medium": return 50;
      case "low": return 20;
      case "none": return 5;
      default: return 40;
    }
  }

  private static calculateMarketDemand(role: string): number {
    // In production, this would query the MarketAnalyzer or JobAggregator for role frequency
    const roleLower = role.toLowerCase();
    if (roleLower.includes("engineer") || roleLower.includes("developer")) return 85;
    if (roleLower.includes("data") || roleLower.includes("ai")) return 95;
    if (roleLower.includes("product") || roleLower.includes("manager")) return 75;
    return 60;
  }
}

import { createHash } from "crypto";
import { getRedisClient } from "@/lib/redis";
import { callClaudeJson } from "@/app/api/interview/_lib/claude";
import { prisma } from "@/lib/db/prisma";
import salaryBenchmarks from "@/lib/data/salary-benchmarks.json";
import { logger } from "@/lib/logger";

export interface ScamJobInfo {
  title: string;
  company: string;
  url?: string | null;
  description: string;
  salaryRange?: string | null;
  scamReports?: number;
}

export class ScamJobDetector {
  async detectScam(job: ScamJobInfo): Promise<{ score: number; signals: string[]; verdict: "safe" | "suspicious" | "scam" }> {
    let score = 0;
    const signals: string[] = [];
    const logs: string[] = [];

    // COMMUNITY REPORTS (Highest priority)
    const reports = job.scamReports || 0;
    if (reports >= 3) {
      return { score: 100, signals: ["Flagged as scam by community (3+ reports)"], verdict: "scam" };
    }
    if (reports >= 1) {
      score += 20;
      signals.push("Flagged as suspicious by community");
    }

    // 1. SALARY CHECK (max 20)
    let salaryScore = 0;
    const lowerTitle = job.title.toLowerCase();
    const benchmarkKey = Object.keys(salaryBenchmarks).find((k) => lowerTitle.includes(k));
    if (benchmarkKey && job.salaryRange) {
      // Very naive extraction of the first large number (assumed INR for India context if it's large)
      const match = job.salaryRange.match(/(\d{5,})/);
      if (match && match[1]) {
        const salaryVal = parseInt(match[1], 10);
        const benchmarkData = salaryBenchmarks as Record<string, { INR?: { median?: number } }>;
        const median = benchmarkData[benchmarkKey]?.INR?.median;
        if (median && salaryVal > median * 3) {
          salaryScore = 20;
          signals.push("Unrealistically high salary (3x+ market median)");
        } else if (median && salaryVal > median * 2) {
          salaryScore = 15;
          signals.push("Highly inflated salary (2x+ market median)");
        }
      }
    }
    score += salaryScore;

    // 2. URL CHECK
    const url = job.url || "";
    if (!url || url.includes("javascript:") || url === "#") {
      score += 15;
      signals.push("No valid application link provided");
    } else if (/whatsapp\.com|wa\.me|t\.me|telegram\.me/i.test(url)) {
      score += 25;
      signals.push("Application redirects to WhatsApp/Telegram (High Scam Risk)");
    } else if (/bit\.ly|tinyurl\.com|t\.ly|cutt\.ly|rebrand\.ly/i.test(url)) {
      score += 20;
      signals.push("Application uses a link shortener (Common in scams)");
    }

    // 3. REGEX HEURISTICS (Emails & Upfront Payments)
    const description = job.description || "";
    const lowerDesc = description.toLowerCase();

    // Free Email Providers for Recruiters
    if (/[a-zA-Z0-9._%+-]+@(gmail\.com|yahoo\.com|outlook\.com|hotmail\.com)/i.test(description)) {
      score += 15;
      signals.push("Recruiter uses a free email address (gmail/yahoo/etc) instead of company domain");
    }

    // Upfront payments
    if (/registration fee|security deposit|training fee|payment required|pay to work/i.test(description)) {
      score += 25;
      signals.push("Description mentions upfront payment or security deposit (Illegal)");
    }

    // 4. COMPANY VERIFICATION
    const suspiciousCompanyRegex = /earn|fast.*money|guaranteed|urgent.*hiring|data.*entry/i;
    if (suspiciousCompanyRegex.test(job.company)) {
      score += 10;
      signals.push("Company name contains suspicious keywords");
    }

    // Database check for company intelligence
    try {
      const companyIntel = await prisma.companyIntelligence.findUnique({
        where: { companyName: job.company },
      });
      if (!companyIntel) {
        score += 10;
        signals.push("Company has no verified intelligence profile");
      }
    } catch (err) {
      // ignore db errors
    }

    logs.push(`Heuristic score: ${score}`);

    // STAGE 2: AI ANALYSIS (Only if heuristic score >= 15)
    if (score >= 15) {
      const aiScore = await this.checkDescriptionWithAI(description);
      if (aiScore > 0) {
        score += aiScore * 3;
        signals.push("AI detected semantic scam indicators in job description");
        logs.push(`AI score applied: ${aiScore * 3}`);
      }
    } else {
      logs.push("Skipped AI analysis (heuristic score < 15)");
    }

    // CAP SCORE AT 100
    score = Math.min(100, Math.max(0, score));

    // DETERMINE VERDICT
    let verdict: "safe" | "suspicious" | "scam" = "safe";
    if (score >= 61) verdict = "scam";
    else if (score >= 26) verdict = "suspicious";

    logger.info({ score, verdict, signals, logs }, "[ScamJobDetector] Evaluated job");

    return { score, signals, verdict };
  }

  private async checkDescriptionWithAI(description: string): Promise<number> {
    if (!description || description.trim() === "") return 0;

    const cacheKey = `scam_ai:${createHash("sha256").update(description.substring(0, 500)).digest("hex")}`;
    const redis = getRedisClient();

    if (redis) {
      try {
        const cached = await redis.get<number>(cacheKey);
        if (cached !== null) return cached;
      } catch (err) {
        // ignore redis errors
      }
    }

    try {
      const systemPrompt = `You are an expert fraud investigator for an Indian job platform. Evaluate the job description for scam indicators.
Look out for: guaranteed placement, upfront fees, work from home earn lakhs daily, no experience needed, MLM/network marketing, WhatsApp required, data entry earn 50k/month, URGENT HIRING.

Return ONLY a JSON object with a single key "scamScore" containing an integer from 0 to 10 (10 being highly fraudulent).
Example: {"scamScore": 8}`;

      const { data } = await callClaudeJson<{ scamScore: number }>({
        system: systemPrompt,
        user: `Job Description:\n${description.substring(0, 3000)}`,
        maxTokens: 100,
        // using default model, usually haiku or sonnet
      });

      const score = Math.min(10, Math.max(0, data?.scamScore || 0));

      if (redis) {
        // Cache for 30 days
        redis.set(cacheKey, score, { ex: 30 * 24 * 60 * 60 }).catch(() => {});
      }
      return score;
    } catch (error) {
      logger.warn({ error }, "[ScamJobDetector] AI check failed.");
      return 0;
    }
  }
}

